// ============================================================

// ---------- 1. QUALE STRUMENTO? ----------
$__lux_slug = (string)($_GET['__lux'] ?? '');
if ($__lux_slug === '') {
    $__lux_path = (string)parse_url((string)($_SERVER['REQUEST_URI'] ?? ''), PHP_URL_PATH);
    $__lux_slug = basename($__lux_path, '.php');
}
// I trattini servono agli strumenti del catalogo generato: i loro slug sono
// "azione-argomento-preset" (es. riassumi-email-flash) e senza il trattino
// non si risalirebbe piu' alla voce giusta.
$__lux_slug = preg_replace('/[^a-z0-9_-]/', '', strtolower($__lux_slug));

// L'URL reale resta /<slug>.php: header.php (canonical, data-page), la nav e
// config.php (checkProjectStatus, trackVisit) leggono SCRIPT_NAME.
$_SERVER['SCRIPT_NAME'] = '/' . $__lux_slug . '.php';

