                'ph_it' => 'incolla qui il codice', 'ph_en' => 'paste your code here'],
            ['name' => 'livello', 'type' => 'select', 'label_it' => 'Il tuo livello', 'label_en' => 'Your level', 'default' => 'principiante',
                'options' => [['principiante', 'Principiante assoluto', 'Absolute beginner'], ['intermedio', 'So le basi', 'I know the basics'], ['avanzato', 'Avanzato', 'Advanced']],
