                $pwd = '';
                for ($j = 0; $j < $len; $j++) {
                    $pwd .= $chars[random_int(0, $max)];
                }
                $out[] = $pwd;
            }
            $it = lux_tool_lang() === 'it';
            $note = $it
                ? "Genera le password qui sotto e salva ognuna in un gestore di password.\nNessuna password viene trasmessa o registrata: il calcolo avviene sul server e non viene conservato nulla."
                : "Copy each password into a password manager.\nNothing is stored: the value is generated on the fly and never kept.";
            return ['content' => implode("\n", $out) . "\n\n" . $note, 'title' => $it ? 'Password generate' : 'Generated passwords'];
        },
        'related' => ['workmehash', 'workmeuuid'],
    ],

    // ---------------------------------------------------------
    'workmeslug' => [
        'name' => 'LUX.Slug', 'icon' => 'link', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Trasforma un titolo in uno slug URL pulito, con opzioni per separatori e lunghezza.',
        'desc_en' => 'Turn any title into a clean URL slug with separator and length options.',
        'action_it' => 'Crea slug', 'action_en' => 'Create slug',
        'result_it' => 'Slug generato', 'result_en' => 'Generated slug',
        'cta_icon' => 'link',
        'fields' => [
            ['name' => 'text', 'type' => 'textarea', 'label_it' => 'Titolo o testo', 'label_en' => 'Title or text', 'required' => true,
                'rows' => 3, 'max' => 400, 'ph_it' => 'Es. 10 Idee per un sito più veloce', 'ph_en' => 'e.g. 10 Ideas for a faster website'],
            ['name' => 'sep', 'type' => 'select', 'label_it' => 'Separatore', 'label_en' => 'Separator', 'default' => '-',
                'options' => [['-', 'Trattino (-)', 'Hyphen (-)'], ['_', 'Trattino basso (_)', 'Underscore (_)'], ['.', 'Punto (.)', 'Dot (.)']],
            ],
            ['name' => 'maxlen', 'type' => 'number', 'label_it' => 'Lunghezza massima (0 = libera)', 'label_en' => 'Max length (0 = free)', 'default' => '60', 'min_value' => 0, 'max_value' => 200, 'step' => 1],
        ],
        'run' => function (array $in) {
            $map = ['à' => 'a', 'á' => 'a', 'â' => 'a', 'ä' => 'a', 'è' => 'e', 'é' => 'e', 'ê' => 'e', 'ë' => 'e',
                    'ì' => 'i', 'í' => 'i', 'î' => 'i', 'ï' => 'i', 'ò' => 'o', 'ó' => 'o', 'ô' => 'o', 'ö' => 'o',
                    'ù' => 'u', 'ú' => 'u', 'û' => 'u', 'ü' => 'u', 'ç' => 'c', 'ñ' => 'n', 'ß' => 'ss',
                    'À' => 'A', 'È' => 'E', 'É' => 'E', 'Ì' => 'I', 'Ò' => 'O', 'Ù' => 'U'];
            $t = strtr((string)$in['text'], $map);
            $t = strtolower($t);
            $t = preg_replace('/[^a-z0-9]+/', '-', $t);
            $t = trim((string)$t, '-');
            $max = (int)($in['maxlen'] ?? 60);
            if ($max > 0 && strlen($t) > $max) {
                $t = substr($t, 0, $max);
                $t = rtrim($t, '-');
            }
            $sep = (string)($in['sep'] ?? '-');
            if ($sep !== '-') $t = str_replace('-', $sep, $t);
            return ['content' => $t];
        },
        'related' => ['workmeurl', 'workmecase'],
    ],

    // ---------------------------------------------------------
    'workmecount' => [
        'name' => 'LUX.Count', 'icon' => 'chart', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Conta caratteri, parole, frasi e righe, con tempo di lettura e parole più usate.',
        'desc_en' => 'Count characters, words, sentences and lines, with reading time and top words.',
        'action_it' => 'Analizza il testo', 'action_en' => 'Analyze text',
        'result_it' => 'Statistiche del testo', 'result_en' => 'Text statistics',
        'fields' => [
            ['name' => 'text', 'type' => 'textarea', 'label_it' => 'Testo', 'label_en' => 'Text', 'required' => true,
                'rows' => 8, 'max' => 40000, 'ph_it' => 'Incolla qui il tuo testo...', 'ph_en' => 'Paste your text here...'],
        ],
        'run' => function (array $in) {
            $it   = lux_tool_lang() === 'it';
            $text = (string)$in['text'];
            $plain = preg_replace('/\s+/', ' ', $text);
            $chars = strlen($text);
            $charsNoSpace = strlen(preg_replace('/\s/', '', $text));
            $words = preg_split('/\s+/u', trim((string)$plain), -1, PREG_SPLIT_NO_EMPTY);
            $wordCount = is_array($words) ? count($words) : 0;
            $sentences = max(1, count(preg_split('/[.!?]+/u', $plain, -1, PREG_SPLIT_NO_EMPTY)));
            $lines = count(preg_split('/\n/', $text, -1));
            $paragraphs = max(1, count(preg_split('/\n\s*\n/', trim($text), -1, PREG_SPLIT_NO_EMPTY)));
            $readMin = $wordCount > 0 ? max(1, (int)round($wordCount / 200)) : 0;
            $speakMin = $wordCount > 0 ? max(1, (int)round($wordCount / 140)) : 0;

            $freq = [];
            if (is_array($words) && $wordCount > 0) {
                foreach ($words as $w) {
                    $k = strtolower(trim($w, " \t\n\r\0\x0B.,;:!?\"'()[]{}«»"));
                    if ($k === '' || strlen($k) < 4) continue;
                    $freq[$k] = ($freq[$k] ?? 0) + 1;
                }
                arsort($freq);
            }
            $top = array_slice($freq, 0, 8, true);

            $rows = [
                ($it ? 'Caratteri (con spazi)' : 'Characters (with spaces)') => number_format($chars, 0, ',', '.'),
                ($it ? 'Caratteri (senza spazi)' : 'Characters (no spaces)') => number_format($charsNoSpace, 0, ',', '.'),
                ($it ? 'Parole' : 'Words') => number_format($wordCount, 0, ',', '.'),
                ($it ? 'Frasi' : 'Sentences') => number_format($sentences, 0, ',', '.'),
                ($it ? 'Paragrafi' : 'Paragraphs') => number_format($paragraphs, 0, ',', '.'),
                ($it ? 'Righe' : 'Lines') => number_format($lines, 0, ',', '.'),
                ($it ? 'Tempo di lettura' : 'Reading time') => $readMin . ($it ? ' min' : ' min'),
                ($it ? 'Lettura ad alta voce' : 'Speaking time') => $speakMin . ($it ? ' min' : ' min'),
            ];
            $md = '';
            foreach ($rows as $k => $v) $md .= '- **' . $k . '**: ' . $v . "\n";
            if ($top) {
                $md .= "\n### " . ($it ? 'Parole più usate' : 'Most used words') . "\n";
                foreach ($top as $w => $n) $md .= '- `' . $w . '` — ' . $n . 'x' . "\n";
            }
            return ['content' => trim($md), 'output' => 'rich'];
        },
        'related' => ['riassumi', 'workmeslug'],
    ],

    // ---------------------------------------------------------
    'workmecase' => [
        'name' => 'LUX.Case', 'icon' => 'translate', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Cambia il formato del testo: MAIUSCOLO, minuscolo, Titolo, Inizio frase, camelCase, snake_case, kebab-case.',
        'desc_en' => 'Change text case: UPPER, lower, Title, Sentence, camelCase, snake_case, kebab-case.',
        'action_it' => 'Trasforma', 'action_en' => 'Transform',
        'result_it' => 'Testo trasformato', 'result_en' => 'Transformed text',
        'cta_icon' => 'write',
        'fields' => [
            ['name' => 'text', 'type' => 'textarea', 'label_it' => 'Testo', 'label_en' => 'Text', 'required' => true, 'rows' => 6, 'max' => 20000,
                'ph_it' => 'Incolla il testo da trasformare', 'ph_en' => 'Paste the text to transform'],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Formato', 'label_en' => 'Format', 'default' => 'title',
                'options' => [
                    ['upper', 'MAIUSCOLO', 'UPPERCASE'],
                    ['lower', 'minuscolo', 'lowercase'],
                    ['title', 'Titolo Di Ogni Parola', 'Title Case'],
                    ['sentence', 'Inizio maiuscolo', 'Sentence case'],
                    ['camel', 'camelCase', 'camelCase'],
                    ['snake', 'snake_case', 'snake_case'],
                    ['kebab', 'kebab-case', 'kebab-case'],
                ],
            ],
        ],
        'run' => function (array $in) {
            $t = (string)$in['text'];
            switch ((string)$in['mode']) {
                case 'upper':    $out = strtoupper($t); break;
                case 'lower':    $out = strtolower($t); break;
                case 'sentence': $out = preg_replace_callback('/(^|[.!?]\s+)([a-zà-ÿ])/u', function ($m) { return $m[1] . strtoupper($m[2]); }, strtolower($t)); break;
                case 'camel':
                    $parts = preg_split('/[^a-zA-Z0-9]+/', strtolower($t), -1, PREG_SPLIT_NO_EMPTY);
                    $out = lcfirst(implode('', array_map('ucfirst', $parts ?: [''])));
                    break;
                case 'snake':
                    $parts = preg_split('/[^a-zA-Z0-9]+/', strtolower($t), -1, PREG_SPLIT_NO_EMPTY);
                    $out = implode('_', $parts ?: ['']);
                    break;
                case 'kebab':
                    $parts = preg_split('/[^a-zA-Z0-9]+/', strtolower($t), -1, PREG_SPLIT_NO_EMPTY);
                    $out = implode('-', $parts ?: ['']);
                    break;
                case 'title':
                default:
                    $out = preg_replace_callback('/(^|\s)([a-zà-ÿ])/u', function ($m) { return $m[1] . strtoupper($m[2]); }, strtolower($t));
            }
            return ['content' => (string)$out];
        },
        'related' => ['workmeslug', 'workmecount'],
    ],

