    'workmebase64' => [
        'name' => 'LUX.Base64', 'icon' => 'code', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Codifica o decodifica testo in Base64, con controllo di validità.',
        'desc_en' => 'Encode or decode text to Base64, with validity check.',
        'action_it' => 'Converti', 'action_en' => 'Convert',
        'result_it' => 'Risultato Base64', 'result_en' => 'Base64 result',
        'cta_icon' => 'code',
        'fields' => [
            ['name' => 'text', 'type' => 'textarea', 'label_it' => 'Testo', 'label_en' => 'Text', 'required' => true, 'rows' => 6, 'max' => 200000],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Operazione', 'label_en' => 'Operation', 'default' => 'encode',
                'options' => [['encode', 'Codifica (testo -> Base64)', 'Encode (text -> Base64)'], ['decode', 'Decodifica (Base64 -> testo)', 'Decode (Base64 -> text)']],
            ],
        ],
        'run' => function (array $in) {
            $t = (string)$in['text'];
            if ((string)$in['mode'] === 'decode') {
                $clean = preg_replace('/\s+/', '', $t);
                if (strlen($clean) < 4 || strlen($clean) % 4 !== 0 || strpos($clean, '=') === 0) {
                    return ['content' => lux_tool_lang() === 'it' ? 'La stringa non sembra Base64 valido.' : 'This does not look like valid Base64.'];
                }
                $decoded = base64_decode($clean, true);
                if ($decoded === false) {
                    return ['content' => lux_tool_lang() === 'it' ? 'Base64 non valido: decodifica impossibile.' : 'Invalid Base64: cannot decode.'];
                }
                return ['content' => $decoded];
            }
            return ['content' => chunk_split(base64_encode($t), 76, "\n")];
        },
        'related' => ['workmehash', 'workmeurl'],
    ],

