    'workmejson' => [
        'name' => 'LUX.Json', 'icon' => 'code', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Formatta, minifica o valida un JSON e ti dice esattamente dov\'è l\'errore.',
        'desc_en' => 'Pretty-print, minify or validate JSON and tell you exactly where the error is.',
        'action_it' => 'Elabora JSON', 'action_en' => 'Process JSON',
        'result_it' => 'JSON elaborato', 'result_en' => 'Processed JSON',
        'cta_icon' => 'code',
        'fields' => [
            ['name' => 'json', 'type' => 'textarea', 'label_it' => 'JSON', 'label_en' => 'JSON', 'required' => true, 'rows' => 10, 'max' => 200000,
                'ph_it' => '{"nome":"L.U.X. Verse","strumenti":100}', 'ph_en' => '{"name":"L.U.X. Verse","tools":100}'],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Azione', 'label_en' => 'Action', 'default' => 'pretty',
                'options' => [
                    ['pretty', 'Formatta (indentato)', 'Format (indented)'],
                    ['minify', 'Minifica', 'Minify'],
                    ['validate', 'Valida soltanto', 'Validate only'],
                ],
            ],
        ],
        'run' => function (array $in) {
            $it  = lux_tool_lang() === 'it';
            $raw = (string)$in['json'];
            $data = json_decode($raw, true);
            if ($data === null && trim($raw) !== 'null') {
                $msg = function_exists('json_last_error_msg') ? json_last_error_msg() : 'JSON error';
                return ['content' => ($it ? 'JSON non valido: ' : 'Invalid JSON: ') . $msg];
            }
            $mode = (string)($in['mode'] ?? 'pretty');
            if ($mode === 'validate') {
                $count = is_array($data) ? count($data) : 1;
                return ['content' => $it
                    ? "JSON valido.\nElementi di primo livello: " . $count
                    : "Valid JSON.\nTop-level items: " . $count];
            }
            $flags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT;
            if ($mode === 'minify') $flags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES;
            $outJson = json_encode($data, $flags);
            return ['content' => $outJson === false ? 'JSON error' : $outJson];
        },
        'related' => ['workmecsv', 'workmebase64'],
    ],

