                'options' => [['sha256', 'SHA-256 (consigliato)', 'SHA-256 (recommended)'], ['sha1', 'SHA-1 (obsoleto)', 'SHA-1 (legacy)'], ['md5', 'MD5 (obsoleto)', 'MD5 (legacy)'], ['crc32', 'CRC32 (solo controllo)', 'CRC32 (checksum only)']],
