    'workmeuuid' => [
        'name' => 'LUX.Uuid', 'icon' => 'cpu', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Genera identificatori univoci: UUID v4, esadecimale, compatto o con prefisso.',
