        'cta_icon' => 'cpu',
        'fields' => [
            ['name' => 'count', 'type' => 'number', 'label_it' => 'Quanti', 'label_en' => 'How many', 'default' => '5', 'min_value' => 1, 'max_value' => 50, 'step' => 1, 'max' => 2],
            ['name' => 'format', 'type' => 'select', 'label_it' => 'Formato', 'label_en' => 'Format', 'default' => 'uuid4',
                'options' => [['uuid4', 'UUID v4', 'UUID v4'], ['hex', 'Esadecimale 32', 'Hex 32'], ['short', 'Corto (12)', 'Short (12)']],
            ],
            ['name' => 'prefix', 'type' => 'text', 'label_it' => 'Prefisso (facoltativo)', 'label_en' => 'Prefix (optional)', 'max' => 24, 'ph_it' => 'es. ord-', 'ph_en' => 'e.g. ord-'],
        ],
        'run' => function (array $in) {
            $count  = max(1, min(50, (int)($in['count'] ?? 5)));
            $format = (string)($in['format'] ?? 'uuid4');
            $prefix = (string)($in['prefix'] ?? '');
            $out = [];
            for ($i = 0; $i < $count; $i++) {
                $b = bin2hex(random_bytes(16));
                if ($format === 'hex') {
                    $v = $b;
                } elseif ($format === 'short') {
                    $v = substr($b, 0, 12);
                } else {
                    $v = substr($b, 0, 8) . '-' . substr($b, 8, 4) . '-4' . substr($b, 13, 3) . '-'
                       . dechex(8 + (hexdec($b[16]) % 4)) . substr($b, 17, 3) . '-' . substr($b, 20, 12);
                }
                $out[] = $prefix . $v;
            }
            return ['content' => implode("\n", $out)];
        },
        'related' => ['workmepass', 'workmehash'],
    ],

    // ---------------------------------------------------------
    'workmelorem' => [
        'name' => 'LUX.Lorem', 'icon' => 'note', 'category' => 'creativita', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Genera testo segnaposto per i tuoi layout: paragrafi, titoli e liste.',
        'desc_en' => 'Generate placeholder text for your layouts: paragraphs, headings and lists.',
        'action_it' => 'Genera testo', 'action_en' => 'Generate text',
        'result_it' => 'Testo segnaposto', 'result_en' => 'Placeholder text',
        'cta_icon' => 'note',
        'fields' => [
            ['name' => 'paragraphs', 'type' => 'number', 'label_it' => 'Paragrafi', 'label_en' => 'Paragraphs', 'default' => '3', 'min_value' => 1, 'max_value' => 20, 'step' => 1, 'max' => 2],
            ['name' => 'sentences', 'type' => 'number', 'label_it' => 'Frasi per paragrafo', 'label_en' => 'Sentences per paragraph', 'default' => '4', 'min_value' => 1, 'max_value' => 10, 'step' => 1, 'max' => 2],
            ['name' => 'headings', 'type' => 'select', 'label_it' => 'Titoli', 'label_en' => 'Headings', 'default' => 'no',
                'options' => [['no', 'Nessun titolo', 'No headings'], ['yes', 'Titolo per paragrafo', 'Heading per paragraph']],
            ],
            ['name' => 'lang', 'type' => 'select', 'label_it' => 'Lingua del testo', 'label_en' => 'Text language', 'default' => 'la',
                'options' => [['la', 'Latino (classico)', 'Latin (classic)'], ['it', 'Italiano riempitivo', 'Neutral filler']],
            ],
        ],
        'run' => function (array $in) {
            $paras = max(1, min(20, (int)($in['paragraphs'] ?? 3)));
            $sents = max(1, min(10, (int)($in['sentences'] ?? 4)));
            $heads = (string)($in['headings'] ?? 'no');
            $lang  = (string)($in['lang'] ?? 'la');

            $words = $lang === 'it'
                ? ['lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit', 'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore', 'et', 'dolore', 'magna', 'aliqua', 'enim', 'ad', 'minim', 'veniam', 'quis', 'nostrud', 'exercitation', 'ullamco', 'laboris', 'nisi', 'aliquip', 'ex', 'ea', 'commodo', 'consequat']
                : ['lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit', 'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore', 'et', 'dolore', 'magna', 'aliqua'];
            $headsWords = ['Propositum generale', 'Structura operis', 'Consilium primum', 'Notae technicae', 'Accessibilitas', 'Design system', 'Instrumenta', 'Contenuti'];
            $max = count($words) - 1;
            $out = '';
            for ($p = 0; $p < $paras; $p++) {
                if ($heads === 'yes') {
                    $out .= '## ' . $headsWords[$p % count($headsWords)] . "\n\n";
                }
                $buf = [];
                for ($s = 0; $s < $sents; $s++) {
                    $n = random_int(8, 16);
                    $chunk = [];
                    for ($w = 0; $w < $n; $w++) $chunk[] = $words[random_int(0, $max)];
                    $chunk[0] = ucfirst($chunk[0]);
                    $buf[] = implode(' ', $chunk) . '.';
                }
                $out .= implode(' ', $buf) . ($p < $paras - 1 ? "\n\n" : '');
            }
            return ['content' => trim($out)];
        },
        'related' => ['workmecount', 'workmeslug'],
    ],

