        'cta_icon' => 'palette',
        'fields' => [
            ['name' => 'color', 'type' => 'text', 'label_it' => 'Colore (HEX o RGB)', 'label_en' => 'Colour (HEX or RGB)', 'default' => '#D8A93C', 'required' => true, 'max' => 40,
                'ph_it' => 'es. #D8A93C oppure 216,169,60', 'ph_en' => 'e.g. #D8A93C or 216,169,60'],
        ],
        'run' => function (array $in) {
            $raw = trim((string)$in['color']);
            if (preg_match('/^#?([0-9a-f]{3})$/i', $raw, $m)) {
                $h = $m[1];
                $r = hexdec($h[0] . $h[0]); $g = hexdec($h[1] . $h[1]); $b = hexdec($h[2] . $h[2]);
            } elseif (preg_match('/^#?([0-9a-f]{6})$/i', $raw, $m)) {
                $r = hexdec(substr($m[1], 0, 2)); $g = hexdec(substr($m[1], 2, 2)); $b = hexdec(substr($m[1], 4, 2));
            } elseif (preg_match('/^(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})$/', $raw, $m)) {
                $r = min(255, (int)$m[1]); $g = min(255, (int)$m[2]); $b = min(255, (int)$m[3]);
            } else {
                return ['content' => lux_tool_lang() === 'it'
                    ? "Colore non riconosciuto. Usa #RRGGBB oppure R,G,B (es. 216,169,60)."
                    : "Colour not recognised. Use #RRGGBB or R,G,B (e.g. 216,169,60)."];
            }
            $hex = sprintf('#%02X%02X%02X', $r, $g, $b);
            $rN = $r / 255; $gN = $g / 255; $bN = $b / 255;
            $mx = max($rN, $gN, $bN); $mn = min($rN, $gN, $bN);
            $l = ($mx + $mn) / 2;
            $d = $mx - $mn;
            $hm = 0.0; $s = 0.0;
            if ($d > 0) {
                $s = $d / (1 - abs(2 * $l - 1));
                if ($mx === $rN)      $hm = 60 * fmod(($gN - $bN) / $d, 6);
                elseif ($mx === $gN)  $hm = 60 * ((($bN - $rN) / $d) + 2);
                else                  $hm = 60 * ((($rN - $gN) / $d) + 4);
            }
            if ($hm < 0) $hm += 360;

            $lum = function ($c) { $c = $c / 255; return $c <= 0.03928 ? $c / 12.92 : pow(($c + 0.055) / 1.055, 2.4); };
            $L = 0.2126 * $lum($r) + 0.7152 * $lum($g) + 0.0722 * $lum($b);
            $cr = function ($a, $b) { $hi = max($a, $b); $lo = min($a, $b); return ($hi + 0.05) / ($lo + 0.05); };
            $onWhite = $cr($L, 1.0);
            $onBlack = $cr($L, 0.0);
            $it = lux_tool_lang() === 'it';

            $verdict = function ($ratio) use ($it) {
                if ($ratio >= 7)   return $it ? 'AAA (ottimo)' : 'AAA (excellent)';
                if ($ratio >= 4.5) return $it ? 'AA (buono)' : 'AA (good)';
                if ($ratio >= 3)   return $it ? 'AA large (solo titoli)' : 'AA large (headings only)';
                return $it ? 'Non sufficiente' : 'Not sufficient';
            };

            $lines = [];
            $lines[] = 'HEX:  ' . $hex;
            $lines[] = 'RGB:  rgb(' . $r . ', ' . $g . ', ' . $b . ')';
            $lines[] = 'HSL:  hsl(' . round($hm) . ', ' . round($s * 100) . '%, ' . round($l * 100) . '%)';
            $lines[] = 'Luminanza relativa: ' . number_format($L, 3);
            $lines[] = '';
            $lines[] = ($it ? 'Contrasto su BIANCO: ' : 'Contrast on WHITE: ') . number_format($onWhite, 2) . ':1  ->  ' . $verdict($onWhite);
            $lines[] = ($it ? 'Contrasto su NERO: ' : 'Contrast on BLACK: ') . number_format($onBlack, 2) . ':1  ->  ' . $verdict($onBlack);
            $lines[] = '';
            $lines[] = ($it ? 'Testo consigliato sopra questo colore: ' : 'Suggested text colour on top of it: ')
                     . ($onBlack >= $onWhite ? ($it ? 'chiaro (#EDE9E0 o #FFFFFF)' : 'light (#EDE9E0 or #FFFFFF)')
                                             : ($it ? 'scuro (#0A0B0D o #000000)' : 'dark (#0A0B0D or #000000)'));
            return ['content' => implode("\n", $lines)];
        },
        'related' => ['workmeshades', 'coloriamo'],
    ],

    // ---------------------------------------------------------
    'workmeshades' => [
        'name' => 'LUX.Shades', 'icon' => 'palette', 'category' => 'creativita', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Crea una scala di 11 tonalità da un colore base, con contrasto WCAG per ognuna.',
        'desc_en' => 'Build an 11-step shade scale from a base colour, with WCAG contrast for each step.',
        'action_it' => 'Genera scala', 'action_en' => 'Generate scale',
        'result_it' => 'Scala di tonalità', 'result_en' => 'Shade scale',
        'cta_icon' => 'palette',
        'fields' => [
            ['name' => 'color', 'type' => 'text', 'label_it' => 'Colore base (HEX)', 'label_en' => 'Base colour (HEX)', 'default' => '#D8A93C', 'required' => true, 'max' => 12],
        ],
        'run' => function (array $in) {
            $raw = trim((string)$in['color']);
            if (preg_match('/^#?([0-9a-f]{3})$/i', $raw, $m)) {
                $h = $m[1];
                $r = hexdec($h[0] . $h[0]); $g = hexdec($h[1] . $h[1]); $b = hexdec($h[2] . $h[2]);
            } elseif (preg_match('/^#?([0-9a-f]{6})$/i', $raw, $m)) {
                $r = hexdec(substr($m[1], 0, 2)); $g = hexdec(substr($m[1], 2, 2)); $b = hexdec(substr($m[1], 4, 2));
            } else {
                return ['content' => lux_tool_lang() === 'it' ? 'Inserisci un colore HEX valido (es. #D8A93C).' : 'Enter a valid HEX colour (e.g. #D8A93C).'];
            }
            $lum = function ($c) { $c = $c / 255; return $c <= 0.03928 ? $c / 12.92 : pow(($c + 0.055) / 1.055, 2.4); };
            $ratio = function ($L) { $hi = max($L, 1.0); $lo = min($L, 1.0); return ($hi + 0.05) / ($lo + 0.05); };

            $out = [];
            foreach ([95, 90, 80, 70, 60, 50, 40, 30, 20, 10, 5] as $step) {
                $mix = $step / 100;
                if ($mix < 0.5) {
                    $f = $mix / 0.5;              // verso il bianco
                    $nr = (int)round($r + (255 - $r) * (1 - $f));
                    $ng = (int)round($g + (255 - $g) * (1 - $f));
                    $nb = (int)round($b + (255 - $b) * (1 - $f));
                } else {
                    $f = ($mix - 0.5) / 0.5;      // verso il nero
                    $nr = (int)round($r * (1 - $f));
                    $ng = (int)round($g * (1 - $f));
                    $nb = (int)round($b * (1 - $f));
                }
                $hex = sprintf('#%02X%02X%02X', max(0, min(255, $nr)), max(0, min(255, $ng)), max(0, min(255, $nb)));
                $L = 0.2126 * $lum(max(0, min(255, $nr))) + 0.7152 * $lum(max(0, min(255, $ng))) + 0.0722 * $lum(max(0, min(255, $nb)));
                $cr = $ratio($L);
                $out[] = sprintf('%-3d  %-9s  contrasto su bianco %5.2f:1  %s', $step, $hex, $cr, $cr >= 4.5 ? 'OK testo' : ($cr >= 3 ? 'ok titoli' : 'solo decorativo'));
            }
            $out[] = '';
            $out[] = lux_tool_lang() === 'it'
                ? 'Usa le tonalità 10-30 per gli sfondi scuri, 40-60 per gli accenti, 70-95 per il testo su fondo scuro.'
                : 'Use 10-30 for dark surfaces, 40-60 for accents, 70-95 for text on dark backgrounds.';
            return ['content' => implode("\n", $out)];
        },
        'related' => ['workmehex', 'coloriamo'],
    ],

