                    ['m', 'Metri (m)', 'Metres (m)'], ['km', 'Chilometri (km)', 'Kilometres (km)'],
                    ['in', 'Pollici (in)', 'Inches (in)'], ['ft', 'Piedi (ft)', 'Feet (ft)'], ['mi', 'Miglia (mi)', 'Miles (mi)'],
                    ['mg', 'Milligrammi (mg)', 'Milligrams (mg)'], ['g', 'Grammi (g)', 'Grams (g)'],
                    ['kg', 'Chilogrammi (kg)', 'Kilograms (kg)'], ['t', 'Tonnellate (t)', 'Tonnes (t)'], ['lb', 'Libbre (lb)', 'Pounds (lb)'], ['oz', 'Once (oz)', 'Ounces (oz)'],
                    ['ml', 'Millilitri (ml)', 'Millilitres (ml)'], ['l', 'Litri (l)', 'Litres (l)'], ['gal', 'Galloni (gal)', 'Gallons (gal)'],
                    ['c', 'Celsius (°C)', 'Celsius (°C)'], ['f', 'Fahrenheit (°F)', 'Fahrenheit (°F)'], ['k', 'Kelvin (K)', 'Kelvin (K)'],
                    ['kmh', 'km/h', 'km/h'], ['mph', 'mph', 'mph'], ['ms', 'm/s', 'm/s'], ['knot', 'Nodi (kn)', 'Knots (kn)'],
                    ['b', 'Byte (B)', 'Bytes (B)'], ['kb', 'Kilobyte (KB)', 'Kilobytes (KB)'], ['mb', 'Megabyte (MB)', 'Megabytes (MB)'], ['gb', 'Gigabyte (GB)', 'Gigabytes (GB)'], ['tb', 'Terabyte (TB)', 'Terabytes (TB)'],
                    ['s', 'Secondi (s)', 'Seconds (s)'], ['min', 'Minuti (min)', 'Minutes (min)'], ['h', 'Ore (h)', 'Hours (h)'], ['day', 'Giorni (d)', 'Days (d)'],
                ],
            ],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $v  = (float)str_replace(',', '.', (string)$in['value']);
            $from = (string)$in['from'];
            $to   = (string)$in['to'];

            $groups = [
                'lunghezza' => ['mm' => 0.001, 'cm' => 0.01, 'm' => 1, 'km' => 1000, 'in' => 0.0254, 'ft' => 0.3048, 'mi' => 1609.344],
                'massa'     => ['mg' => 1e-6, 'g' => 0.001, 'kg' => 1, 't' => 1000, 'lb' => 0.45359237, 'oz' => 0.028349523125],
                'volume'    => ['ml' => 0.001, 'l' => 1, 'gal' => 3.785411784],
                'velocita'  => ['kmh' => 1, 'mph' => 1.609344, 'ms' => 3.6, 'knot' => 1.852],
                'dati'      => ['b' => 1, 'kb' => 1024, 'mb' => 1048576, 'gb' => 1073741824, 'tb' => 1099511627776],
                'tempo'     => ['s' => 1, 'min' => 60, 'h' => 3600, 'day' => 86400],
            ];

            if (in_array($from, ['c', 'f', 'k'], true) && in_array($to, ['c', 'f', 'k'], true)) {
                $celsius = $from === 'c' ? $v : ($from === 'f' ? ($v - 32) * 5 / 9 : $v - 273.15);
                $res = $to === 'c' ? $celsius : ($to === 'f' ? $celsius * 9 / 5 + 32 : $celsius + 273.15);
                return ['content' => $v . ' ' . strtoupper($from) . ' = ' . rtrim(rtrim(number_format($res, 4, ',', '.'), '0'), ',') . ' ' . strtoupper($to)];
            }

            foreach ($groups as $units) {
                if (isset($units[$from]) && isset($units[$to])) {
                    $res = $v * $units[$from] / $units[$to];
                    $fmt = $res !== 0.0 && abs($res) < 0.001 ? number_format($res, 8, ',', '.') : number_format($res, 6, ',', '.');
                    $fmt = rtrim(rtrim($fmt, '0'), ',');
                    return ['content' => $v . ' ' . $from . ' = ' . $fmt . ' ' . $to];
                }
            }

            return ['content' => $it
                ? 'Le due unità appartengono a categorie diverse: scegli unità della stessa famiglia (es. km -> mi).'
                : 'These units belong to different categories: pick units of the same family (e.g. km -> mi).'];
        },
        'related' => ['workmepercent', 'workmedates'],
    ],

