    'workmepercent' => [
        'name' => 'LUX.Percent', 'icon' => 'calc', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Percentuali, sconti, aumenti e variazioni: tutti i calcoli che servono al volo.',
        'desc_en' => 'Percentages, discounts, increases and changes: the quick math you need.',
        'action_it' => 'Calcola', 'action_en' => 'Calculate',
        'result_it' => 'Risultato', 'result_en' => 'Result',
        'cta_icon' => 'calc',
        'fields' => [
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Cosa vuoi calcolare', 'label_en' => 'What to calculate', 'default' => 'of',
                'options' => [
                    ['of', 'Percentuale di un numero (A% di B)', 'Percentage of a number (A% of B)'],
                    ['share', 'Che percentuale è A di B', 'What percent is A of B'],
                    ['change', 'Variazione da A a B', 'Change from A to B'],
                    ['discount', 'Sconto: prezzo A con B% di sconto', 'Discount: price A with B% off'],
                    ['increase', 'Aumento: prezzo A con B% di aumento', 'Increase: price A with B% up'],
                ],
            ],
            ['name' => 'a', 'type' => 'number', 'label_it' => 'Valore A', 'label_en' => 'Value A', 'default' => '100', 'required' => true],
            ['name' => 'b', 'type' => 'number', 'label_it' => 'Valore B (%)', 'label_en' => 'Value B (%)', 'default' => '22', 'required' => true],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $a = (float)str_replace(',', '.', (string)$in['a']);
            $b = (float)str_replace(',', '.', (string)$in['b']);
            $f = function ($n) { return rtrim(rtrim(number_format($n, 2, ',', '.'), '0'), ','); };
            $mode = (string)$in['mode'];
            $md = '';
            switch ($mode) {
                case 'share':
                    if ($b == 0.0) return ['content' => $it ? 'B non può essere zero.' : 'B cannot be zero.'];
                    $p = $a / $b * 100;
                    $md = ($it ? 'Risultato' : 'Result') . ': **' . $f($p) . "%**\n\n- A: " . $f($a) . "\n- B: " . $f($b);
                    break;
                case 'change':
                    if ($a == 0.0) return ['content' => $it ? 'A non può essere zero.' : 'A cannot be zero.'];
                    $p = ($b - $a) / abs($a) * 100;
                    $md = ($it ? ($p >= 0 ? 'Aumento' : 'Diminuzione') : ($p >= 0 ? 'Increase' : 'Decrease'))
                        . ': **' . $f(abs($p)) . "%**\n\n- " . ($it ? 'Da' : 'From') . ': ' . $f($a)
                        . "\n- " . ($it ? 'A' : 'To') . ': ' . $f($b)
                        . "\n- " . ($it ? 'Differenza' : 'Difference') . ': ' . $f($b - $a);
                    break;
                case 'discount':
                    $save = $a * $b / 100;
                    $md = ($it ? 'Prezzo scontato' : 'Discounted price') . ': **' . $f($a - $save) . "**\n\n"
                        . '- ' . ($it ? 'Prezzo pieno' : 'Full price') . ': ' . $f($a) . "\n"
                        . '- ' . ($it ? 'Sconto' : 'Discount') . ': ' . $f($b) . '% (' . $f($save) . ")\n"
                        . '- ' . ($it ? 'Risparmio' : 'You save') . ': ' . $f($save);
                    break;
                case 'increase':
                    $add = $a * $b / 100;
                    $md = ($it ? 'Prezzo aumentato' : 'Increased price') . ': **' . $f($a + $add) . "**\n\n"
                        . '- ' . ($it ? 'Prezzo di partenza' : 'Starting price') . ': ' . $f($a) . "\n"
                        . '- ' . ($it ? 'Aumento' : 'Increase') . ': ' . $f($b) . '% (' . $f($add) . ')';
                    break;
                default:
                    $md = $f($b) . '% ' . ($it ? 'di' : 'of') . ' ' . $f($a) . ' = **' . $f($a * $b / 100) . '**';
                    break;
            }
            return ['content' => $md];
        },
        'related' => ['workmevat', 'workmeloan'],
    ],

