    'workmedates' => [
        'name' => 'LUX.Dates', 'icon' => 'calendar', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Differenza tra due date in giorni, settimane, mesi e anni, con i giorni lavorativi esclusi i fine settimana.',
        'desc_en' => 'Difference between two dates in days, weeks, months and years, with business days excluding weekends.',
