        'result_it' => 'Differenza tra le date', 'result_en' => 'Date difference',
        'cta_icon' => 'calendar',
        'fields' => [
            ['name' => 'start', 'type' => 'text', 'label_it' => 'Data iniziale (AAAA-MM-GG)', 'label_en' => 'Start date (YYYY-MM-DD)', 'default' => '', 'required' => true, 'max' => 10, 'ph_it' => '2026-01-01', 'ph_en' => '2026-01-01'],
            ['name' => 'end', 'type' => 'text', 'label_it' => 'Data finale (AAAA-MM-GG)', 'label_en' => 'End date (YYYY-MM-DD)', 'default' => '', 'required' => true, 'max' => 10, 'ph_it' => '2026-12-31', 'ph_en' => '2026-12-31'],
            ['name' => 'extra', 'type' => 'number', 'label_it' => 'Oppure: aggiungi/togli giorni alla data iniziale', 'label_en' => 'Or: add/remove days to the start date', 'default' => '0', 'min_value' => -3650, 'max_value' => 3650, 'step' => 1],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $parse = function ($s) { $t = strtotime(trim((string)$s)); return $t === false ? null : $t; };
            $a = $parse($in['start']);
            $b = $parse($in['end']);
            if ($a === null || $b === null) {
                return ['content' => $it ? 'Date non valide: usa il formato AAAA-MM-GG (es. 2026-01-31).' : 'Invalid dates: use YYYY-MM-DD (e.g. 2026-01-31).'];
            }
            if ($b < $a) { $tmp = $a; $a = $b; $b = $tmp; }
            $days = (int)floor(($b - $a) / 86400);
            $weeks = floor($days / 7);
            $restDays = $days % 7;
            $d1 = new DateTime(date('Y-m-d', $a));
            $d2 = new DateTime(date('Y-m-d', $b));
            $diff = $d1->diff($d2);
            $business = 0;
            $cursor = clone $d1;
            while ($cursor < $d2) {
                $w = (int)$cursor->format('N');
                if ($w <= 5) $business++;
                $cursor->modify('+1 day');
            }
            $y = $diff->y; $m = $diff->m; $d = $diff->d;
            $md  = ($it ? 'Giorni totali' : 'Total days') . ': **' . number_format($days, 0, ',', '.') . "**\n\n";
            $md .= '- ' . ($it ? 'Settimane' : 'Weeks') . ': ' . $weeks . ($restDays ? ' + ' . $restDays . ($it ? ' giorni' : ' days') : '') . "\n";
            $md .= '- ' . ($it ? 'Giorni lavorativi (lun-ven)' : 'Business days (Mon-Fri)') . ': ' . $business . "\n";
            $md .= '- ' . ($it ? 'Anni / mesi / giorni' : 'Years / months / days') . ': ' . $y . ' / ' . $m . ' / ' . $d . "\n";
            $md .= '- ' . ($it ? 'Ore' : 'Hours') . ': ' . number_format($days * 24, 0, ',', '.') . "\n";
            $md .= '- ' . ($it ? 'Da' : 'From') . ': ' . date('d/m/Y', $a) . ' (' . $d1->format('l') . ')' . "\n";
            $md .= '- ' . ($it ? 'A' : 'To') . ': ' . date('d/m/Y', $b) . ' (' . $d2->format('l') . ')';

            $extra = (int)($in['extra'] ?? 0);
            if ($extra !== 0) {
                $newDate = (clone $d1)->modify(($extra > 0 ? '+' : '') . $extra . ' days');
                $md .= "\n\n### " . ($it ? 'Data calcolata' : 'Computed date') . "\n"
                     . date('d/m/Y', $a) . ($extra > 0 ? ' + ' : ' - ') . abs($extra) . ($it ? ' giorni = ' : ' days = ')
                     . '**' . $newDate->format('d/m/Y') . '** (' . $newDate->format('l') . ')';
            }
            return ['content' => $md];
        },
        'related' => ['workmeconvert', 'workmeschedule'],
    ],

