                     . '- ' . ($it ? 'Totale' : 'Total') . ': ' . $f($amount);
            } else {
                $vat = $amount * $rate;
                $md  = ($it ? 'Importo netto' : 'Net amount') . ': ' . $f($amount) . "\n\n"
                     . '- IVA ' . rtrim(rtrim(number_format($rate * 100, 2, ',', '.'), '0'), ',') . '%: **' . $f($vat) . "**\n"
                     . '- ' . ($it ? 'Totale lordo' : 'Gross total') . ': ' . $f($amount + $vat);
