    // ---------------------------------------------------------
    'workmeloan' => [
        'name' => 'LUX.Loan', 'icon' => 'chart', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola la rata di un mutuo o prestito, con interessi totali e costo reale del finanziamento.',
        'desc_en' => 'Work out the instalment of a mortgage or loan, with total interest and real cost.',
        'action_it' => 'Calcola la rata', 'action_en' => 'Calculate instalment',
        'result_it' => 'Piano di rimborso', 'result_en' => 'Repayment plan',
        'cta_icon' => 'chart',
        'fields' => [
            ['name' => 'amount', 'type' => 'number', 'label_it' => 'Importo finanziato (euro)', 'label_en' => 'Loan amount (euro)', 'default' => '120000', 'required' => true],
            ['name' => 'rate', 'type' => 'number', 'label_it' => 'Tasso annuo (TAN %)', 'label_en' => 'Annual rate (%)', 'default' => '3.5', 'required' => true, 'step' => '0.01'],
            ['name' => 'years', 'type' => 'number', 'label_it' => 'Durata (anni)', 'label_en' => 'Term (years)', 'default' => '25', 'required' => true, 'min_value' => 1, 'max_value' => 40, 'step' => 1],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $P = (float)str_replace(',', '.', (string)$in['amount']);
            $annual = (float)str_replace(',', '.', (string)$in['rate']) / 100;
            $years = max(1, min(40, (int)$in['years']));
            if ($P <= 0) return ['content' => $it ? 'Inserisci un importo maggiore di zero.' : 'Enter an amount greater than zero.'];
            $n = $years * 12;
            $i = $annual / 12;
            $inst = $i > 0 ? $P * $i / (1 - pow(1 + $i, -$n)) : $P / $n;
            $total = $inst * $n;
            $interest = $total - $P;
            $f = function ($x) { return number_format($x, 2, ',', '.'); };
            $md  = ($it ? 'Rata mensile' : 'Monthly instalment') . ': **' . $f($inst) . "**\n\n";
            $md .= '- ' . ($it ? 'Importo finanziato' : 'Loan amount') . ': ' . $f($P) . "\n";
            $md .= '- ' . ($it ? 'Numero rate' : 'Instalments') . ': ' . $n . "\n";
            $md .= '- ' . ($it ? 'Totale rimborsato' : 'Total repaid') . ': ' . $f($total) . "\n";
            $md .= '- ' . ($it ? 'Interessi totali' : 'Total interest') . ': ' . $f($interest) . "\n";
            $md .= '- ' . ($it ? 'Incidenza interessi' : 'Interest share') . ': ' . number_format($interest / $P * 100, 1, ',', '.') . '%';
            $md .= "\n\n" . ($it
                ? 'Stima indicativa: non include spese, assicurazioni o variazioni del tasso. Verifica sempre con la banca.'
                : 'Estimate only: it does not include fees, insurance or rate changes. Always confirm with your bank.');
            return ['content' => $md];
        },
        'related' => ['workmepercent', 'workmevat'],
    ],

