    'workmebmr' => [
        'name' => 'LUX.Cal', 'icon' => 'bolt', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Stima metabolismo basale, calorie giornaliere e ripartizione dei macronutrienti.',
        'desc_en' => 'Estimate basal metabolism, daily calories and macronutrient split.',
        'action_it' => 'Calcola le calorie', 'action_en' => 'Calculate calories',
        'result_it' => 'Fabbisogno calorico', 'result_en' => 'Calorie needs',
        'cta_icon' => 'bolt',
        'fields' => [
            ['name' => 'sex', 'type' => 'select', 'label_it' => 'Sesso biologico', 'label_en' => 'Biological sex', 'default' => 'f',
                'options' => [['f', 'Donna', 'Female'], ['m', 'Uomo', 'Male']],
            ],
            ['name' => 'age', 'type' => 'number', 'label_it' => 'Età', 'label_en' => 'Age', 'default' => '30', 'required' => true, 'min_value' => 14, 'max_value' => 100, 'step' => 1],
            ['name' => 'weight', 'type' => 'number', 'label_it' => 'Peso (kg)', 'label_en' => 'Weight (kg)', 'default' => '70', 'required' => true, 'step' => '0.1'],
            ['name' => 'height', 'type' => 'number', 'label_it' => 'Altezza (cm)', 'label_en' => 'Height (cm)', 'default' => '172', 'required' => true, 'step' => '0.5'],
            ['name' => 'activity', 'type' => 'select', 'label_it' => 'Attività', 'label_en' => 'Activity', 'default' => '1.375',
                'options' => [
                    ['1.2', 'Sedentaria (poco o nessun esercizio)', 'Sedentary (little or no exercise)'],
                    ['1.375', 'Leggera (1-3 allenamenti a settimana)', 'Light (1-3 workouts/week)'],
                    ['1.55', 'Moderata (3-5 allenamenti)', 'Moderate (3-5 workouts)'],
                    ['1.725', 'Intensa (6-7 allenamenti)', 'Intense (6-7 workouts)'],
                    ['1.9', 'Atleta (2 volte al giorno)', 'Athlete (twice a day)'],
                ],
            ],
            ['name' => 'goal', 'type' => 'select', 'label_it' => 'Obiettivo', 'label_en' => 'Goal', 'default' => 'maintain',
                'options' => [['lose', 'Perdere peso (-15%)', 'Lose weight (-15%)'], ['maintain', 'Mantenere', 'Maintain'], ['gain', 'Aumentare massa (+10%)', 'Gain mass (+10%)']],
            ],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $age = (int)$in['age'];
            $kg  = (float)str_replace(',', '.', (string)$in['weight']);
            $cm  = (float)str_replace(',', '.', (string)$in['height']);
            $act = (float)$in['activity'];
            $base = 10 * $kg + 6.25 * $cm - 5 * $age + ((string)$in['sex'] === 'm' ? 5 : -161);
            $tdee = $base * $act;
            $goal = (string)$in['goal'];
            $target = $goal === 'lose' ? $tdee * 0.85 : ($goal === 'gain' ? $tdee * 1.10 : $tdee);
            $prot = $kg * 1.8;
            $fat  = $target * 0.27 / 9;
            $carb = max(0, ($target - $prot * 4 - $fat * 9) / 4);
            $r = function ($x) { return number_format($x, 0, ',', '.'); };

            $md  = ($it ? 'Calorie giornaliere consigliate' : 'Suggested daily calories') . ': **' . $r($target) . " kcal**\n\n";
            $md .= '- ' . ($it ? 'Metabolismo basale (BMR)' : 'Basal metabolic rate (BMR)') . ': ' . $r($base) . " kcal\n";
            $md .= '- ' . ($it ? 'Dispendio giornaliero (TDEE)' : 'Daily expenditure (TDEE)') . ': ' . $r($tdee) . " kcal\n";
            $md .= '- ' . ($it ? 'Obiettivo' : 'Goal') . ': ' . ($goal === 'lose' ? ($it ? 'perdere peso' : 'lose weight') : ($goal === 'gain' ? ($it ? 'aumentare massa' : 'gain mass') : ($it ? 'mantenere' : 'maintain'))) . "\n\n";
            $md .= '### ' . ($it ? 'Macronutrienti giornalieri' : 'Daily macronutrients') . "\n";
            $md .= '- ' . ($it ? 'Proteine' : 'Protein') . ': **' . $r($prot) . " g**\n";
            $md .= '- ' . ($it ? 'Grassi' : 'Fat') . ': **' . $r($fat) . " g**\n";
            $md .= '- ' . ($it ? 'Carboidrati' : 'Carbohydrates') . ': **' . $r($carb) . " g**\n\n";
            $md .= ($it ? 'Formula Mifflin-St Jeor. Stima indicativa, non sostituisce un parere medico.' : 'Mifflin-St Jeor formula. Estimate only, not medical advice.');
            return ['content' => $md];
        },
        'related' => ['workmebmi', 'workmeworkout'],
    ],

