    'workmebmi' => [
        'name' => 'LUX.Bmi', 'icon' => 'pulse', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola l\'indice di massa corporea, la categoria e l\'intervallo di peso ideale per la tua altezza.',
        'desc_en' => 'Work out body mass index, its category and the ideal weight range for your height.',
        'action_it' => 'Calcola BMI', 'action_en' => 'Calculate BMI',
        'result_it' => 'Indice di massa corporea', 'result_en' => 'Body mass index',
        'cta_icon' => 'pulse',
        'fields' => [
            ['name' => 'weight', 'type' => 'number', 'label_it' => 'Peso (kg)', 'label_en' => 'Weight (kg)', 'default' => '70', 'required' => true, 'step' => '0.1'],
            ['name' => 'height', 'type' => 'number', 'label_it' => 'Altezza (cm)', 'label_en' => 'Height (cm)', 'default' => '172', 'required' => true, 'step' => '0.5'],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $kg = (float)str_replace(',', '.', (string)$in['weight']);
            $cm = (float)str_replace(',', '.', (string)$in['height']);
            if ($kg <= 0 || $cm <= 0) return ['content' => $it ? 'Inserisci peso e altezza validi.' : 'Enter a valid weight and height.'];
            $m = $cm / 100;
            $bmi = $kg / ($m * $m);
            if ($bmi < 18.5)      $cat = $it ? 'Sottopeso' : 'Underweight';
            elseif ($bmi < 25)    $cat = $it ? 'Normopeso' : 'Normal weight';
            elseif ($bmi < 30)    $cat = $it ? 'Sovrappeso' : 'Overweight';
            elseif ($bmi < 35)    $cat = $it ? 'Obesità di grado I' : 'Obesity class I';
            elseif ($bmi < 40)    $cat = $it ? 'Obesità di grado II' : 'Obesity class II';
            else                  $cat = $it ? 'Obesità di grado III' : 'Obesity class III';
            $min = 18.5 * $m * $m;
            $max = 24.9 * $m * $m;
            $md  = 'BMI: **' . number_format($bmi, 1, ',', '.') . '** — ' . $cat . "\n\n";
            $md .= '- ' . ($it ? 'Peso attuale' : 'Current weight') . ': ' . number_format($kg, 1, ',', '.') . " kg\n";
            $md .= '- ' . ($it ? 'Altezza' : 'Height') . ': ' . number_format($cm, 0, ',', '.') . " cm\n";
            $md .= '- ' . ($it ? 'Intervallo di peso normale' : 'Normal weight range') . ': ' . number_format($min, 1, ',', '.') . ' - ' . number_format($max, 1, ',', '.') . " kg\n\n";
            $md .= ($it ? 'Il BMI è un indicatore grezzo: non distingue massa muscolare e grasso e non vale per atleti, donne in gravidanza o minorenni.' : 'BMI is a rough indicator: it does not separate muscle from fat and does not apply to athletes, pregnant people or minors.');
            return ['content' => $md];
        },
        'related' => ['workmebmr', 'workmeworkout'],
    ],

    // ---------------------------------------------------------
    'workmepick' => [
        'name' => 'LUX.Pick', 'icon' => 'target', 'category' => 'giochi', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Sorteggia a caso da un elenco: perfetto per turni, nomi, premi o decisioni difficili.',
        'desc_en' => 'Randomly draw from a list: perfect for turns, names, prizes or hard decisions.',
        'action_it' => 'Sorteggia', 'action_en' => 'Draw',
        'result_it' => 'Risultato del sorteggio', 'result_en' => 'Draw result',
        'cta_icon' => 'target',
        'fields' => [
            ['name' => 'list', 'type' => 'textarea', 'label_it' => 'Elenco (una voce per riga)', 'label_en' => 'List (one item per line)', 'required' => true, 'rows' => 7, 'max' => 20000,
                'ph_it' => "Marco\nGiulia\nLuca\nSara", 'ph_en' => "Mark\nJulia\nLuke\nSarah"],
            ['name' => 'count', 'type' => 'number', 'label_it' => 'Quanti estratti', 'label_en' => 'How many picks', 'default' => '1', 'min_value' => 1, 'max_value' => 50, 'step' => 1],
            ['name' => 'unique', 'type' => 'select', 'label_it' => 'Senza ripetizioni', 'label_en' => 'Without repetition', 'default' => '1',
                'options' => [['1', 'Sì, non ripetere', 'Yes, no repeats'], ['0', 'No, può ripetersi', 'No, repeats allowed']],
            ],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $items = preg_split('/\r\n|\r|\n/', (string)$in['list'], -1, PREG_SPLIT_NO_EMPTY);
            $items = array_values(array_filter(array_map('trim', $items ?: []), function ($x) { return $x !== ''; }));
            if (count($items) < 2) return ['content' => $it ? 'Servono almeno due voci nell\'elenco.' : 'You need at least two items in the list.'];
            $count = max(1, (int)$in['count']);
            $unique = (string)$in['unique'] === '1';
            if ($unique) $count = min($count, count($items));

            $picked = [];
            $pool = $items;
            for ($i = 0; $i < $count; $i++) {
                if (!$pool) { $pool = $items; }
                $idx = random_int(0, count($pool) - 1);
                $picked[] = $pool[$idx];
                if ($unique) array_splice($pool, $idx, 1);
            }
            $md = ($it ? 'Estratto' : 'Picked') . ' (' . count($items) . ' ' . ($it ? 'voci' : 'items') . "):\n";
            foreach ($picked as $p) $md .= '- **' . $p . '**' . "\n";
            return ['content' => $md];
        },
        'related' => ['workmegames', 'workmesort'],
    ],

    // ---------------------------------------------------------
    'workmesort' => [
        'name' => 'LUX.Sort', 'icon' => 'filter', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Ordina elenchi, rimuove duplicati e righe vuote, conta le occorrenze.',
        'desc_en' => 'Sort lists, remove duplicates and empty lines, count occurrences.',
        'action_it' => 'Elabora elenco', 'action_en' => 'Process list',
        'result_it' => 'Elenco elaborato', 'result_en' => 'Processed list',
        'cta_icon' => 'filter',
        'fields' => [
            ['name' => 'list', 'type' => 'textarea', 'label_it' => 'Elenco (una voce per riga o separata da virgole)', 'label_en' => 'List (one item per line or comma separated)', 'required' => true, 'rows' => 7, 'max' => 30000],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Operazione', 'label_en' => 'Operation', 'default' => 'az',
                'options' => [
                    ['az', 'Ordina A-Z', 'Sort A-Z'], ['za', 'Ordina Z-A', 'Sort Z-A'],
                    ['len', 'Ordina per lunghezza', 'Sort by length'], ['num', 'Ordina numericamente', 'Sort numerically'],
                    ['unique', 'Rimuovi duplicati (in ordine)', 'Remove duplicates (keep order)'],
                    ['shuffle', 'Ordine casuale', 'Shuffle'],
                    ['count', 'Conta le occorrenze', 'Count occurrences'],
                ],
            ],
            ['name' => 'caseins', 'type' => 'select', 'label_it' => 'Maiuscole/minuscole', 'label_en' => 'Case', 'default' => '1',
                'options' => [['1', 'Ignora differenze di maiuscole', 'Ignore case'], ['0', 'Considera le maiuscole', 'Case sensitive']],
            ],
        ],
        'run' => function (array $in) {
            $raw = str_replace(["\r\n", "\r"], "\n", (string)$in['list']);
            $parts = preg_split('/\n|,|;/', $raw, -1, PREG_SPLIT_NO_EMPTY);
            $items = [];
            foreach ($parts ?: [] as $p) {
                $p = trim($p);
                if ($p !== '') $items[] = $p;
            }
            if (!$items) return ['content' => lux_tool_lang() === 'it' ? 'Elenco vuoto.' : 'Empty list.'];
            $ci = (string)$in['caseins'] === '1';
            $mode = (string)$in['mode'];

            if ($mode === 'count') {
                $freq = [];
                foreach ($items as $i) { $k = $ci ? strtolower($i) : $i; $freq[$k] = ($freq[$k] ?? 0) + 1; }
                arsort($freq);
                $out = [];
                foreach ($freq as $k => $n) $out[] = $n . 'x  ' . $k;
                return ['content' => implode("\n", $out) . "\n\n" . count($items) . ' voci, ' . count($freq) . ' uniche'];
            }
            if ($mode === 'unique') {
                $seen = [];
                foreach ($items as $i) {
                    $k = $ci ? strtolower($i) : $i;
                    if (isset($seen[$k])) continue;
                    $seen[$k] = true;
                    $out[] = $i;
                }
            } elseif ($mode === 'shuffle') {
                $out = $items;
                for ($i = count($out) - 1; $i > 0; $i--) {
                    $j = random_int(0, $i);
                    $tmp = $out[$i]; $out[$i] = $out[$j]; $out[$j] = $tmp;
                }
            } else {
                $out = $items;
                if ($mode === 'za')       usort($out, function ($a, $b) use ($ci) { return $ci ? strcasecmp($b, $a) : strcmp($b, $a); });
                elseif ($mode === 'len')  usort($out, function ($a, $b) { return strlen($a) <=> strlen($b); });
                elseif ($mode === 'num')  usort($out, function ($a, $b) { return (float)str_replace(',', '.', $a) <=> (float)str_replace(',', '.', $b); });
                else                      usort($out, function ($a, $b) use ($ci) { return $ci ? strcasecmp($a, $b) : strcmp($a, $b); });
            }
            return ['content' => implode("\n", $out) . "\n\n" . count($items) . ' -> ' . count($out) . ' ' . (lux_tool_lang() === 'it' ? 'voci' : 'items')];
        },
        'related' => ['workmepick', 'workmecsv'],
    ],

