    'workmediff' => [
        'name' => 'LUX.Diff', 'icon' => 'code', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Confronta due versioni di un testo e mostra riga per riga cosa è cambiato.',
        'desc_en' => 'Compare two versions of a text and show line by line what changed.',
        'action_it' => 'Confronta', 'action_en' => 'Compare',
        'result_it' => 'Differenze', 'result_en' => 'Differences',
        'cta_icon' => 'code',
        'fields' => [
            ['name' => 'a', 'type' => 'textarea', 'label_it' => 'Testo originale', 'label_en' => 'Original text', 'required' => true, 'rows' => 7, 'max' => 30000],
            ['name' => 'b', 'type' => 'textarea', 'label_it' => 'Testo modificato', 'label_en' => 'Changed text', 'required' => true, 'rows' => 7, 'max' => 30000],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $A = preg_split('/\r\n|\n|\r/', (string)$in['a']);
            $B = preg_split('/\r\n|\n|\r/', (string)$in['b']);
            $A = $A ?: [];
            $B = $B ?: [];
            $na = count($A); $nb = count($B);

            // LCS classico: preciso ma limitato a 500 righe per non pesare
            if ($na <= 500 && $nb <= 500) {
                $lcs = [];
                for ($i = 0; $i <= $na; $i++) $lcs[$i] = array_fill(0, $nb + 1, 0);
                for ($i = $na - 1; $i >= 0; $i--) {
                    for ($j = $nb - 1; $j >= 0; $j--) {
                        $lcs[$i][$j] = $A[$i] === $B[$j] ? $lcs[$i + 1][$j + 1] + 1 : max($lcs[$i + 1][$j], $lcs[$i][$j + 1]);
                    }
                }
                $out = [];
                $added = 0; $removed = 0;
                $i = 0; $j = 0;
                while ($i < $na && $j < $nb) {
                    if ($A[$i] === $B[$j]) { $out[] = '  ' . $A[$i]; $i++; $j++; }
                    elseif ($lcs[$i + 1][$j] >= $lcs[$i][$j + 1]) { $out[] = '- ' . $A[$i]; $removed++; $i++; }
                    else { $out[] = '+ ' . $B[$j]; $added++; $j++; }
                }
                while ($i < $na) { $out[] = '- ' . $A[$i]; $removed++; $i++; }
                while ($j < $nb) { $out[] = '+ ' . $B[$j]; $added++; $j++; }
                $head = ($it ? 'Righe aggiunte' : 'Added lines') . ': ' . $added . '   ' . ($it ? 'Rimuove' : 'Removed') . ': ' . $removed
                      . "\n" . ($it ? 'Legenda' : 'Legend') . ': + ' . ($it ? 'aggiunta' : 'added') . ', - ' . ($it ? 'rimossa' : 'removed') . ", '  ' " . ($it ? 'invariata' : 'unchanged') . "\n\n";
                return ['content' => $head . implode("\n", array_slice($out, 0, 600))];
            }
            return ['content' => $it ? 'Testi troppo lunghi per il confronto preciso: riduci a 500 righe per parte.' : 'Texts too long for an accurate diff: keep it under 500 lines per side.'];
        },
        'related' => ['workmecase', 'workmecount'],
    ],

    // ---------------------------------------------------------
    'workmecsv' => [
        'name' => 'LUX.Csv', 'icon' => 'clipboard', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Converte dati CSV in JSON e viceversa, con scelta del separatore e intestazioni automatiche.',
        'desc_en' => 'Convert CSV data to JSON and back, with separator choice and automatic headers.',
        'action_it' => 'Converti dati', 'action_en' => 'Convert data',
        'result_it' => 'Dati convertiti', 'result_en' => 'Converted data',
        'cta_icon' => 'clipboard',
        'fields' => [
            ['name' => 'data', 'type' => 'textarea', 'label_it' => 'Dati', 'label_en' => 'Data', 'required' => true, 'rows' => 9, 'max' => 200000],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Direzione', 'label_en' => 'Direction', 'default' => 'tojson',
                'options' => [['tojson', 'CSV -> JSON', 'CSV -> JSON'], ['tocsv', 'JSON -> CSV', 'JSON -> CSV']],
            ],
            ['name' => 'sep', 'type' => 'select', 'label_it' => 'Separatore CSV', 'label_en' => 'CSV separator', 'default' => ',',
                'options' => [[',', 'Virgola (,)', 'Comma (,)'], [';', 'Punto e virgola (;)', 'Semicolon (;)'], ["\t", 'Tab', 'Tab'], ['|', 'Pipe (|)', 'Pipe (|)']],
            ],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $sep = (string)($in['sep'] ?? ',');
            if ($sep === '') $sep = ',';
            $data = (string)$in['data'];

            if ((string)$in['mode'] === 'tocsv') {
                $json = json_decode($data, true);
                if (!is_array($json)) return ['content' => $it ? 'JSON non valido: impossibile convertire.' : 'Invalid JSON: cannot convert.'];
                if (isset($json[0]) && is_array($json[0])) {
                    $keys = array_keys($json[0]);
                    $rows = [$keys];
                    foreach ($json as $row) {
                        $line = [];
                        foreach ($keys as $k) $line[] = (string)($row[$k] ?? '');
                        $rows[] = $line;
                    }
                } else {
                    $rows = [['chiave', 'valore']];
                    foreach ($json as $k => $v) $rows[] = [(string)$k, is_scalar($v) ? (string)$v : json_encode($v)];
                }
                $out = [];
                foreach ($rows as $r) {
                    $out[] = implode($sep, array_map(function ($c) use ($sep) {
                        $c = str_replace('"', '""', (string)$c);
                        return (strpos($c, $sep) !== false || strpos($c, '"') !== false) ? '"' . $c . '"' : $c;
                    }, $r));
                }
                return ['content' => implode("\n", $out)];
            }

            $lines = preg_split('/\r\n|\n|\r/', trim($data), -1, PREG_SPLIT_NO_EMPTY);
            if (!$lines) return ['content' => $it ? 'Nessun dato da convertire.' : 'No data to convert.'];
            $parse = function ($line) use ($sep) {
                $out = []; $cur = ''; $inQ = false;
                $len = strlen($line);
                for ($i = 0; $i < $len; $i++) {
                    $ch = $line[$i];
                    if ($ch === '"') {
                        if ($inQ && $i + 1 < $len && $line[$i + 1] === '"') { $cur .= '"'; $i++; }
                        else { $inQ = !$inQ; }
                    } elseif ($ch === $sep && !$inQ) {
                        $out[] = $cur; $cur = '';
                    } else { $cur .= $ch; }
                }
                $out[] = $cur;
                return $out;
            };
            $head = $parse(array_shift($lines));
            $result = [];
            foreach ($lines as $line) {
                $cells = $parse($line);
                $row = [];
                foreach ($head as $i => $name) {
                    $name = trim($name);
                    if ($name === '') $name = 'col' . ($i + 1);
                    $row[$name] = $cells[$i] ?? '';
                }
                $result[] = $row;
            }
            $json = json_encode($result, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
            return ['content' => $json === false ? 'JSON error' : $json];
        },
        'related' => ['workmejson', 'workmesort'],
    ],

    // ---------------------------------------------------------
    'workmecron' => [
        'name' => 'LUX.Cron', 'icon' => 'timer', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Traduce un\'espressione cron in italiano chiaro e segnala se non è valida.',
        'desc_en' => 'Turn a cron expression into plain language and flag invalid ones.',
        'action_it' => 'Spiega espressione', 'action_en' => 'Explain expression',
        'result_it' => 'Descrizione', 'result_en' => 'Description',
        'cta_icon' => 'timer',
        'fields' => [
            ['name' => 'expr', 'type' => 'text', 'label_it' => 'Espressione cron (5 campi)', 'label_en' => 'Cron expression (5 fields)', 'default' => '*/15 9-18 * * 1-5', 'required' => true, 'max' => 120,
                'ph_it' => 'es. 0 3 * * *', 'ph_en' => 'e.g. 0 3 * * *'],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $parts = preg_split('/\s+/', trim((string)$in['expr']), -1, PREG_SPLIT_NO_EMPTY);
            if (count($parts) !== 5) {
                return ['content' => $it ? 'Un\'espressione cron ha 5 campi: minuto, ora, giorno del mese, mese, giorno della settimana.' : 'A cron expression has 5 fields: minute, hour, day of month, month, day of week.'];
            }
            $names = [
                'minuto', 'ora', 'giorno del mese', 'mese', 'giorno della settimana'
            ];
            $desc = function ($field, $kind) use ($it) {
                $f = trim($field);
                if ($f === '*') return $it ? 'ogni ' . $kind : 'every ' . $kind;
                if (strpos($f, '*/') === 0) {
                    $n = substr($f, 2);
                    return ($it ? 'ogni ' : 'every ') . $n . ' ' . $kind;
                }
                if (strpos($f, ',') !== false) return ($it ? 'ai valori ' : 'at values ') . str_replace(',', ', ', $f);
                if (strpos($f, '-') !== false) return ($it ? 'da ' : 'from ') . str_replace('-', ($it ? ' a ' : ' to '), $f);
                return '= ' . $f;
            };
            $kindsIt = ['minuto', 'ora', 'giorno', 'mese', 'giorno della settimana'];
            $kindsEn = ['minute', 'hour', 'day', 'month', 'weekday'];
            $kinds = $it ? $kindsIt : $kindsEn;
            $md = '';
            foreach ($parts as $i => $p) {
                if (!preg_match('/^(\*|[0-9,\-\*\/]+)$/', $p)) {
                    $md .= '- **' . $names[$i] . '**: `' . $p . '` ' . ($it ? 'non valido' : 'not valid') . "\n";
                } else {
                    $md .= '- **' . $names[$i] . '**: `' . $p . '` → ' . $desc($p, $kinds[$i]) . "\n";
                }
            }
            $md .= "\n" . ($it ? 'Interpretazione completa' : 'Full reading') . ": " . ($it ? 'ogni ' : 'every ')
                 . $desc($parts[0], $kinds[0]) . ', ' . $desc($parts[1], $kinds[1]) . ', '
                 . $desc($parts[2], $kinds[2]) . ', ' . $desc($parts[3], $kinds[3]) . ', ' . $desc($parts[4], $kinds[4]) . '.';
            return ['content' => $md];
        },
        'related' => ['workmedates', 'workmeuuid'],
    ],

