    'workmeiban' => [
        'name' => 'LUX.IBAN', 'icon' => 'shield', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Controlla un IBAN come fa una banca: validità reale, paese, banca e numero di conto.',
        'desc_en' => 'Checks an IBAN the way a bank does: real validity, country, bank code and account.',
        'action_it' => 'Controlla IBAN', 'action_en' => 'Check IBAN',
        'result_it' => 'Esito del controllo', 'result_en' => 'Check result',
        'cta_icon' => 'shield',
        'fields' => [
            ['name' => 'iban', 'type' => 'text', 'label_it' => 'IBAN (anche con spazi)', 'label_en' => 'IBAN (spaces are fine)', 'required' => true, 'max' => 42,
                'ph_it' => 'IT60 X054 2811 1010 0000 0123 456', 'ph_en' => 'IT60 X054 2811 1010 0000 0123 456'],
        ],
        'run' => function (array $in) {
            $it   = lux_tool_lang() === 'it';
            $raw  = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)$in['iban']));
            $len  = strlen($raw);
            $rows = [];

            $lens = ['IT' => 27, 'DE' => 22, 'FR' => 27, 'ES' => 24, 'GB' => 22, 'NL' => 18, 'BE' => 16, 'CH' => 21,
                     'AT' => 20, 'PT' => 25, 'IE' => 22, 'PL' => 28, 'SE' => 24, 'DK' => 18, 'NO' => 15, 'FI' => 18,
                     'GR' => 27, 'CZ' => 24, 'RO' => 24, 'HU' => 28, 'LU' => 20, 'MT' => 31, 'CY' => 28, 'SI' => 19];

            if ($len < 5 || !preg_match('/^[A-Z]{2}[0-9]{2}[A-Z0-9]+$/', $raw)) {
                return ['content' => $it
                    ? "**Non è un IBAN.**\nUn IBAN inizia con 2 lettere (paese) e 2 cifre di controllo, poi solo lettere e numeri. Controlla di aver copiato tutto."
                    : "**This is not an IBAN.**\nAn IBAN starts with 2 letters (country) and 2 check digits, then letters and digits only. Check that you copied it all."];
            }

            $cc      = substr($raw, 0, 2);
            $check   = substr($raw, 2, 4);
            $moved   = substr($raw, 4) . substr($raw, 0, 4);
            $numeric = '';
            for ($i = 0; $i < strlen($moved); $i++) {
                $c = $moved[$i];
                $numeric .= ctype_digit($c) ? $c : (string)(ord($c) - 55);
            }
            $rest = 0;
            for ($i = 0; $i < strlen($numeric); $i++) {
                $rest = ($rest * 10 + (int)$numeric[$i]) % 97;
            }
            $valid = ($rest === 1);

            $formatted = trim(chunk_split($raw, 4, ' '));
            $rows[] = '- **' . ($it ? 'Valido' : 'Valid') . '**: ' . ($valid
                ? ($it ? 'si, il codice di controllo torna (mod-97 = 1)' : 'yes, the check digits verify (mod-97 = 1)')
                : ($it ? 'no, il codice di controllo NON torna' : 'no, the check digits do NOT verify'));
            $rows[] = '- **' . ($it ? 'Paese' : 'Country') . '**: `' . $cc . '`';
            $rows[] = '- **' . ($it ? 'Cifre di controllo' : 'Check digits') . '**: `' . $check . '`';
            $rows[] = '- **' . ($it ? 'Lunghezza' : 'Length') . '**: ' . $len . ' ' . ($it ? 'caratteri' : 'characters');
            if (isset($lens[$cc])) {
                $ok = ($len === $lens[$cc]);
                $rows[] = '- **' . ($it ? 'Lunghezza prevista per ' : 'Expected length for ') . $cc . '**: ' . $lens[$cc] . ' (' . ($ok ? ($it ? 'corretta' : 'correct') : ($it ? 'NON corretta' : 'NOT correct')) . ')';
            }
            if ($cc === 'IT' && $len === 27) {
                $rows[] = '- **' . ($it ? 'Banca (ABI)' : 'Bank (ABI)') . '**: `' . substr($raw, 5, 5) . '`';
                $rows[] = '- **' . ($it ? 'Sportello (CAB)' : 'Branch (CAB)') . '**: `' . substr($raw, 10, 5) . '`';
                $rows[] = '- **' . ($it ? 'Numero di conto' : 'Account number') . '**: `' . substr($raw, 15, 12) . '`';
            }

            $title = $valid ? ($it ? 'IBAN formalmente valido' : 'IBAN formally valid')
                            : ($it ? 'IBAN NON valido' : 'IBAN NOT valid');
            $note  = $it
                ? "\nControllo matematico (mod-97) secondo lo standard ISO 13616. Non dice se il conto esiste davvero: quello lo sa solo la banca."
                : "\nMathematical check (mod-97) per ISO 13616. It does not prove the account exists: only the bank knows that.";

            return ['content' => $rows[0] . "\n" . implode("\n", array_slice($rows, 1)) . "\n\n**" . $formatted . "**" . $note, 'title' => $title];
        },
        'related' => ['workmehash', 'workmebarcode'],
    ],

    // ----------------------------------------------------
    'workmeip' => [
        'name' => 'LUX.Net', 'icon' => 'wifi', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola rete, maschera, broadcast e host utilizzabili da un indirizzo IP o da una notazione CIDR.',
        'desc_en' => 'Computes network, mask, broadcast and usable hosts from an IP address or CIDR notation.',
        'action_it' => 'Analizza la rete', 'action_en' => 'Analyze network',
        'result_it' => 'Dettagli della rete', 'result_en' => 'Network details',
        'cta_icon' => 'wifi',
        'fields' => [
            ['name' => 'cidr', 'type' => 'text', 'label_it' => 'Indirizzo IP o CIDR', 'label_en' => 'IP address or CIDR', 'required' => true, 'max' => 40,
                'ph_it' => '192.168.1.10/24', 'ph_en' => '192.168.1.10/24'],
        ],
        'run' => function (array $in) {
            $it   = lux_tool_lang() === 'it';
            $raw  = trim((string)$in['cidr']);
            if (!preg_match('#^(\d{1,3}(?:\.\d{1,3}){3})(?:/(\d{1,2}))?$#', $raw, $m)) {
                return ['content' => $it
                    ? "**Indirizzo non riconosciuto.**\nScrivi un IP tipo `192.168.1.10` oppure un CIDR tipo `192.168.1.0/24`."
                    : "**Address not recognized.**\nWrite an IP like `192.168.1.10` or a CIDR like `192.168.1.0/24`."];
            }
            $parts = explode('.', $m[1]);
            foreach ($parts as $p) {
                if ((int)$p > 255 || $p === '') {
                    return ['content' => $it
                        ? "**Indirizzo non valido:** ogni gruppo deve stare fra 0 e 255."
                        : "**Invalid address:** each group must be between 0 and 255."];
                }
            }
            $bits = isset($m[2]) ? (int)$m[2] : 32;
            if ($bits < 0 || $bits > 32) {
                return ['content' => $it
                    ? "**Prefisso non valido:** va da 0 a 32."
                    : "**Invalid prefix:** it must be between 0 and 32."];
            }
            $ip    = (int)sprintf('%u', ip2long($m[1]));
            $mask  = $bits === 0 ? 0 : ((0xFFFFFFFF << (32 - $bits)) & 0xFFFFFFFF);
            $wild  = (~$mask) & 0xFFFFFFFF;
            $net   = $ip & $mask;
            $bcast = $net | $wild;
            $hosts = $bits >= 31 ? ($bits === 32 ? 1 : 2) : max(0, $bcast - $net - 1);

            $rows = [];
            $rows[] = '- **' . ($it ? 'Indirizzo inserito' : 'Address you entered') . '**: `' . $m[1] . '`';
            $rows[] = '- **' . ($it ? 'Notazione CIDR' : 'CIDR notation') . '**: `' . long2ip($ip) . '/' . $bits . '`';
            $rows[] = '- **' . ($it ? 'Maschera di rete' : 'Subnet mask') . '**: `' . long2ip($mask) . '`  (' . $bits . ' ' . ($it ? 'bit a 1' : 'bits set') . ')';
            $rows[] = '- **' . ($it ? 'Wildcard' : 'Wildcard') . '**: `' . long2ip($wild) . '`';
            $rows[] = '- **' . ($it ? 'Indirizzo di rete' : 'Network address') . '**: `' . long2ip($net) . '`';
            $rows[] = '- **' . ($it ? 'Broadcast' : 'Broadcast') . '**: `' . long2ip($bcast) . '`';
            if ($bits < 31) {
                $rows[] = '- **' . ($it ? 'Primo host' : 'First host') . '**: `' . long2ip($net + 1) . '`';
                $rows[] = '- **' . ($it ? 'Ultimo host' : 'Last host') . '**: `' . long2ip($bcast - 1) . '`';
            }
            $rows[] = '- **' . ($it ? 'Host utilizzabili' : 'Usable hosts') . '**: ' . number_format($hosts, 0, ',', '.');

            $kind = $it ? 'pubblico' : 'public';
            if ($ip >= 0x0A000000 && $ip <= 0x0AFFFFFF)      $kind = $it ? 'privato (10.0.0.0/8)' : 'private (10.0.0.0/8)';
            elseif ($ip >= 0xAC100000 && $ip <= 0xAC1FFFFF)  $kind = $it ? 'privato (172.16.0.0/12)' : 'private (172.16.0.0/12)';
            elseif ($ip >= 0xC0A80000 && $ip <= 0xC0A8FFFF)  $kind = $it ? 'privato (192.168.0.0/16)' : 'private (192.168.0.0/16)';
            elseif ($ip >= 0x7F000000 && $ip <= 0x7FFFFFFF)  $kind = $it ? 'loopback (127.0.0.0/8)' : 'loopback (127.0.0.0/8)';
            elseif ($ip >= 0xA9FE0000 && $ip <= 0xA9FEFFFF)  $kind = $it ? 'link-local (169.254.0.0/16)' : 'link-local (169.254.0.0/16)';
            $rows[] = '- **' . ($it ? 'Tipo' : 'Type') . '**: ' . $kind;

            return ['content' => implode("\n", $rows)];
        },
        'related' => ['workmebinary', 'workmehash'],
    ],

    // ----------------------------------------------------
    'workmecolor' => [
        'name' => 'LUX.Color', 'icon' => 'palette', 'category' => 'utility', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Converte un colore fra HEX, RGB e HSL e ne misura il contrasto di leggibilità (WCAG).',
        'desc_en' => 'Converts a color between HEX, RGB and HSL and measures its readability contrast (WCAG).',
        'action_it' => 'Analizza il colore', 'action_en' => 'Analyze color',
        'result_it' => 'Valori del colore', 'result_en' => 'Color values',
        'cta_icon' => 'palette',
        'fields' => [
            ['name' => 'color', 'type' => 'text', 'label_it' => 'Colore (HEX o rgb)', 'label_en' => 'Color (HEX or rgb)', 'required' => true, 'max' => 32,
                'ph_it' => '#D8A93C oppure rgb(216,169,60)', 'ph_en' => '#D8A93C or rgb(216,169,60)'],
            ['name' => 'bg', 'type' => 'text', 'label_it' => 'Colore di sfondo confrontato (facoltativo)', 'label_en' => 'Background color to compare (optional)', 'max' => 32, 'default' => '',
                'ph_it' => '#0A0B0D', 'ph_en' => '#0A0B0D'],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $parse = function (string $s) {
                $s = strtolower(trim($s));
                if ($s === '') return null;
                if (preg_match('/^#?([0-9a-f]{3})$/', $s, $m)) {
                    $h = str_split($m[1]);
                    return [hexdec($h[0] . $h[0]), hexdec($h[1] . $h[1]), hexdec($h[2] . $h[2])];
                }
                if (preg_match('/^#?([0-9a-f]{6})$/', $s, $m)) {
                    return [hexdec(substr($m[1], 0, 2)), hexdec(substr($m[1], 2, 2)), hexdec(substr($m[1], 4, 2))];
                }
                if (preg_match('/rgba?\(\s*(\d{1,3})\s*[,\s]\s*(\d{1,3})\s*[,\s]\s*(\d{1,3})/', $s, $m)) {
                    $rgb = [(int)$m[1], (int)$m[2], (int)$m[3]];
                    foreach ($rgb as $v) if ($v > 255) return null;
                    return $rgb;
                }
                return null;
            };
            $rgb = $parse((string)$in['color']);
            if (!$rgb) {
                return ['content' => $it
                    ? "**Colore non riconosciuto.**\nUsa `#D8A93C`, `D8A93C`, `#abc` oppure `rgb(216,169,60)`."
                    : "**Color not recognized.**\nUse `#D8A93C`, `D8A93C`, `#abc` or `rgb(216,169,60)`."];
            }
            [$r, $g, $b] = $rgb;
            $lum = function (array $c): float {
                $c = array_map(function ($v) {
                    $v /= 255;
                    return $v <= 0.03928 ? $v / 12.92 : pow(($v + 0.055) / 1.055, 2.4);
                }, $c);
                return 0.2126 * $c[0] + 0.7152 * $c[1] + 0.0722 * $c[2];
            };
            $contrast = function (array $a, array $b) use ($lum): float {
                $la = $lum($a); $lb = $lum($b);
                $hi = max($la, $lb); $lo = min($la, $lb);
                return ($hi + 0.05) / ($lo + 0.05);
            };
            $hex = sprintf('#%02X%02X%02X', $r, $g, $b);
            $rp = $r / 255; $gp = $g / 255; $bp = $b / 255;
            $max = max($rp, $gp, $bp); $min = min($rp, $gp, $bp);
            $l = ($max + $min) / 2;
            $d = $max - $min;
            $h = 0; $s = 0;
            if ($d > 0) {
                $s = $d / (1 - abs(2 * $l - 1));
                if ($max === $rp)      $h = 60 * fmod((($gp - $bp) / $d), 6);
                elseif ($max === $gp)  $h = 60 * ((($bp - $rp) / $d) + 2);
                else                   $h = 60 * ((($rp - $gp) / $d) + 4);
                if ($h < 0) $h += 360;
            }

            $rows = [];
            $rows[] = '- **HEX**: `' . $hex . '`';
            $rows[] = '- **RGB**: `rgb(' . $r . ', ' . $g . ', ' . $b . ')`';
            $rows[] = '- **HSL**: `hsl(' . round($h) . ', ' . round($s * 100) . '%, ' . round($l * 100) . '%)`';
            $rows[] = '- **' . ($it ? 'Luminanza relativa' : 'Relative luminance') . '**: ' . number_format($lum([$r, $g, $b]), 4, ',', '.');

            $cw = $contrast([$r, $g, $b], [255, 255, 255]);
            $cb = $contrast([$r, $g, $b], [0, 0, 0]);
            $verdict = function (float $ratio) use ($it): string {
                if ($ratio >= 7)   return $it ? 'ottimo (AAA)' : 'excellent (AAA)';
                if ($ratio >= 4.5) return $it ? 'buono (AA)' : 'good (AA)';
                if ($ratio >= 3)   return $it ? 'solo testo grande (AA Large)' : 'large text only (AA Large)';
                return $it ? 'insufficiente' : 'insufficient';
            };
            $rows[] = '- **' . ($it ? 'Contrasto con testo bianco' : 'Contrast with white text') . '**: ' . number_format($cw, 2, ',', '.') . ':1 — ' . $verdict($cw);
            $rows[] = '- **' . ($it ? 'Contrasto con testo nero' : 'Contrast with black text') . '**: ' . number_format($cb, 2, ',', '.') . ':1 — ' . $verdict($cb);
            $rows[] = '- **' . ($it ? 'Testo consigliato sopra questo colore' : 'Recommended text on this color') . '**: ' . ($cw >= $cb ? ($it ? 'bianco' : 'white') : ($it ? 'nero' : 'black'));

            $bg = $parse((string)($in['bg'] ?? ''));
            if ($bg) {
                $c2 = $contrast([$r, $g, $b], $bg);
                $rows[] = '- **' . ($it ? 'Contrasto con ' : 'Contrast with ') . sprintf('#%02X%02X%02X', $bg[0], $bg[1], $bg[2]) . '**: ' . number_format($c2, 2, ',', '.') . ':1 — ' . $verdict($c2);
            }
            return ['content' => implode("\n", $rows), 'title' => $hex];
        },
        'related' => ['workmeshades', 'workmehex'],
    ],

    // ----------------------------------------------------
    'workmeprime' => [
        'name' => 'LUX.Prime', 'icon' => 'calc', 'category' => 'educativi', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Dice se un numero è primo, lo scompone in fattori primi e calcola MCD e mcm con un secondo numero.',
        'desc_en' => 'Tells whether a number is prime, factorizes it and computes GCD and LCM with a second number.',
        'action_it' => 'Analizza i numeri', 'action_en' => 'Analyze numbers',
        'result_it' => 'Risultato', 'result_en' => 'Result',
        'cta_icon' => 'calc',
        'fields' => [
            ['name' => 'n', 'type' => 'number', 'label_it' => 'Numero', 'label_en' => 'Number', 'required' => true, 'default' => '360', 'min_value' => 0, 'max_value' => 1000000000000, 'step' => 1, 'max' => 13],
            ['name' => 'n2', 'type' => 'number', 'label_it' => 'Secondo numero per MCD e mcm (facoltativo)', 'label_en' => 'Second number for GCD and LCM (optional)', 'default' => '', 'min_value' => 0, 'max_value' => 1000000000000, 'step' => 1, 'max' => 13],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $n  = (int)($in['n'] ?? 0);
            if ($n < 0) $n = 0;
            $rows = [];
            $rows[] = '- **' . ($it ? 'Numero' : 'Number') . '**: ' . number_format($n, 0, ',', '.');

            $isPrime = true;
            if ($n < 2) {
                $isPrime = false;
            } else {
                for ($i = 2; $i * $i <= $n; $i++) {
                    if ($n % $i === 0) { $isPrime = false; break; }
                }
            }
            $rows[] = '- **' . ($it ? 'Primo' : 'Prime') . '**: ' . ($isPrime ? ($it ? 'si' : 'yes') : ($it ? 'no' : 'no'));

            $temp = $n; $factors = [];
            for ($i = 2; $i * $i <= $temp; $i++) {
                while ($temp % $i === 0) { $factors[] = $i; $temp = (int)($temp / $i); }
            }
            if ($temp > 1) $factors[] = $temp;
            $counts = array_count_values($factors);
            $pretty = [];
            foreach ($counts as $f => $c) $pretty[] = $c > 1 ? $f . '^' . $c : (string)$f;
            $rows[] = '- **' . ($it ? 'Fattori primi' : 'Prime factors') . '**: ' . ($pretty ? implode(' x ', $pretty) : ($it ? 'nessuno' : 'none'));

            if ($n > 0 && $n <= 1000000) {
                $divs = [];
                for ($i = 1; $i * $i <= $n; $i++) {
                    if ($n % $i === 0) { $divs[] = $i; if ($i !== (int)($n / $i)) $divs[] = (int)($n / $i); }
                }
                sort($divs);
                $rows[] = '- **' . ($it ? 'Divisori' : 'Divisors') . '**: ' . count($divs);
                if (count($divs) <= 24) $rows[] = '- **' . ($it ? 'Elenco divisori' : 'Divisor list') . '**: ' . implode(', ', $divs);
            }

            $n2 = (int)($in['n2'] ?? 0);
            if ($n2 > 0) {
                $a = $n; $b = $n2;
                while ($b !== 0) { $t = $a % $b; $a = $b; $b = $t; }
                $gcd = $a;
                $lcm = ($gcd > 0) ? (int)(($n / $gcd) * $n2) : 0;
                $rows[] = '- **' . ($it ? 'Secondo numero' : 'Second number') . '**: ' . number_format($n2, 0, ',', '.');
                $rows[] = '- **MCD**: ' . number_format($gcd, 0, ',', '.');
                $rows[] = '- **mcm**: ' . number_format($lcm, 0, ',', '.');
                $rows[] = '- **' . ($it ? 'Coprimi (nessun divisore comune oltre 1)' : 'Coprime (no common divisor above 1)') . '**: ' . ($gcd === 1 ? ($it ? 'si' : 'yes') : ($it ? 'no' : 'no'));
            }
            return ['content' => implode("\n", $rows)];
        },
        'related' => ['workmestat', 'workmebinary'],
    ],

    // ----------------------------------------------------
    'workmestat' => [
        'name' => 'LUX.Stats', 'icon' => 'chart', 'category' => 'educativi', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola media, mediana, moda, deviazione standard e quartili da un elenco di numeri.',
        'desc_en' => 'Computes mean, median, mode, standard deviation and quartiles from a list of numbers.',
        'action_it' => 'Calcola le statistiche', 'action_en' => 'Compute statistics',
        'result_it' => 'Statistiche', 'result_en' => 'Statistics',
        'cta_icon' => 'chart',
        'fields' => [
            ['name' => 'data', 'type' => 'textarea', 'label_it' => 'Numeri (uno per riga, virgola o spazio)', 'label_en' => 'Numbers (per line, comma or space)', 'required' => true, 'rows' => 7, 'max' => 20000,
                'ph_it' => "12\n15\n9\n22\n15", 'ph_en' => "12\n15\n9\n22\n15"],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $raw = preg_replace('/[^0-9,.\-\s]/', ' ', (string)$in['data']);
            $raw = str_replace(',', ' ', $raw);
            $nums = [];
            foreach (preg_split('/\s+/', trim($raw), -1, PREG_SPLIT_NO_EMPTY) as $tok) {
                if (is_numeric($tok)) $nums[] = (float)$tok;
            }
            $count = count($nums);
            if ($count === 0) {
                return ['content' => $it
                    ? "**Nessun numero trovato.**\nScrivi un numero per riga (anche separati da virgola)."
                    : "**No numbers found.**\nWrite one number per line (commas are fine too)."];
            }
            sort($nums);
            $sum = array_sum($nums);
            $mean = $sum / $count;
            $mid = (int)floor($count / 2);
            $median = ($count % 2) ? $nums[$mid] : (($nums[$mid - 1] + $nums[$mid]) / 2);
            $freq = array_count_values(array_map(function ($v) { return rtrim(rtrim(number_format($v, 6, '.', ''), '0'), '.'); }, $nums));
            arsort($freq);
            $topFreq = reset($freq);
            $modes = $topFreq > 1 ? array_keys($freq, $topFreq, true) : [];
            $var = 0;
            foreach ($nums as $v) $var += pow($v - $mean, 2);
            $var = $var / $count;
            $sd = sqrt($var);
            $q = function (float $p) use ($nums, $count): float {
                $pos = $p * ($count - 1);
                $lo = (int)floor($pos); $hi = (int)ceil($pos);
                if ($lo === $hi) return $nums[$lo];
                return $nums[$lo] + ($pos - $lo) * ($nums[$hi] - $nums[$lo]);
            };
            $q1 = $q(0.25); $q3 = $q(0.75);
            $iqr = $q3 - $q1;
            $outLow = $q1 - 1.5 * $iqr; $outHigh = $q3 + 1.5 * $iqr;
            $outliers = array_values(array_filter($nums, function ($v) use ($outLow, $outHigh) {
                return $v < $outLow || $v > $outHigh;
            }));
            $f = function (float $v): string { return number_format($v, 2, ',', '.'); };

            $rows = [];
            $rows[] = '- **' . ($it ? 'Valori' : 'Values') . '**: ' . $count;
            $rows[] = '- **' . ($it ? 'Somma' : 'Sum') . '**: ' . $f($sum);
            $rows[] = '- **' . ($it ? 'Media' : 'Mean') . '**: ' . $f($mean);
            $rows[] = '- **' . ($it ? 'Mediana' : 'Median') . '**: ' . $f($median);
            $rows[] = '- **' . ($it ? 'Moda' : 'Mode') . '**: ' . ($modes ? implode(', ', $modes) : ($it ? 'nessuna (ogni valore compare una volta)' : 'none (every value appears once)'));
            $rows[] = '- **' . ($it ? 'Minimo' : 'Minimum') . '**: ' . $f($nums[0]) . ' — **' . ($it ? 'Massimo' : 'Maximum') . '**: ' . $f($nums[$count - 1]);
            $rows[] = '- **' . ($it ? 'Intervallo' : 'Range') . '**: ' . $f($nums[$count - 1] - $nums[0]);
            $rows[] = '- **' . ($it ? 'Varianza (popolazione)' : 'Variance (population)') . '**: ' . $f($var);
            $rows[] = '- **' . ($it ? 'Deviazione standard' : 'Standard deviation') . '**: ' . $f($sd);
            $rows[] = '- **Q1**: ' . $f($q1) . ' — **Q3**: ' . $f($q3) . ' — **IQR**: ' . $f($iqr);
            if ($outliers) {
                $rows[] = '- **' . ($it ? 'Valori anomali (oltre 1,5 x IQR)' : 'Outliers (beyond 1.5 x IQR)') . '**: ' . implode(', ', array_map($f, $outliers));
            }
            return ['content' => implode("\n", $rows)];
        },
        'related' => ['workmeprime', 'workmecount'],
    ],

    // ----------------------------------------------------
    'workmeascii' => [
        'name' => 'LUX.Codes', 'icon' => 'code', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Vede il codice di ogni carattere (ASCII/Unicode) e fa il percorso inverso, da codice a carattere.',
        'desc_en' => 'Shows the code of every character (ASCII/Unicode) and converts codes back to characters.',
        'action_it' => 'Converti', 'action_en' => 'Convert',
        'result_it' => 'Codici', 'result_en' => 'Codes',
        'cta_icon' => 'code',
        'fields' => [
            ['name' => 'text', 'type' => 'textarea', 'label_it' => 'Testo o codici', 'label_en' => 'Text or codes', 'required' => true, 'rows' => 5, 'max' => 20000,
                'ph_it' => 'Ciao, mondo!', 'ph_en' => 'Hello, world!'],
            ['name' => 'mode', 'type' => 'select', 'label_it' => 'Operazione', 'label_en' => 'Operation', 'default' => 'encode',
                'options' => [
                    ['encode', 'Testo verso codici', 'Text to codes'],
                    ['decode', 'Codici verso testo', 'Codes to text'],
                    ['binary', 'Testo verso binario', 'Text to binary'],
                    ['frombinary', 'Binario verso testo', 'Binary to text'],
                ],
            ],
        ],
        'run' => function (array $in) {
            $it   = lux_tool_lang() === 'it';
            $text = (string)$in['text'];
            $mode = (string)$in['mode'];

            // mbstring non e' presente su ogni hosting: la conversione UTF-8
            // e' fatta a mano, cosi' lo strumento funziona sempre.
            $chr = function (int $cp): string {
                if ($cp < 0x80) return chr($cp);
                if ($cp < 0x800) return chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F));
                if ($cp < 0x10000) return chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
                return chr(0xF0 | ($cp >> 18)) . chr(0x80 | (($cp >> 12) & 0x3F)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
            };
            $ord = function (string $ch): int {
                $b = array_values(unpack('C*', $ch));
                $n = count($b);
                if ($n === 2) return (($b[0] & 0x1F) << 6) | ($b[1] & 0x3F);
                if ($n === 3) return (($b[0] & 0x0F) << 12) | (($b[1] & 0x3F) << 6) | ($b[2] & 0x3F);
                if ($n === 4) return (($b[0] & 0x07) << 18) | (($b[1] & 0x3F) << 12) | (($b[2] & 0x3F) << 6) | ($b[3] & 0x3F);
                return $b[0];
            };

            if ($mode === 'decode') {
                $out = '';
                foreach (preg_split('/[\s,;]+/', trim($text), -1, PREG_SPLIT_NO_EMPTY) as $tok) {
                    $cp = ctype_digit($tok) ? (int)$tok : 0;
                    if ($cp <= 0 || $cp > 1114111) continue;
                    $out .= $chr($cp);
                }
                return ['content' => $out === '' ? ($it ? 'Nessun codice valido trovato.' : 'No valid code found.') : $out];
            }

            if ($mode === 'binary') {
                // Byte reali del testo (UTF-8), 8 bit ciascuno: reversibile.
                $bytes = unpack('C*', $text);
                $out = [];
                foreach ($bytes as $b) $out[] = str_pad(decbin($b), 8, '0', STR_PAD_LEFT);
                return ['content' => implode(' ', $out)];
            }

            if ($mode === 'frombinary') {
                $bin = '';
                foreach (preg_split('/\s+/', trim($text), -1, PREG_SPLIT_NO_EMPTY) as $tok) {
                    if (preg_match('/^[01]{8}$/', $tok)) $bin .= chr(bindec($tok));
                }
                return ['content' => $bin === '' ? ($it ? 'Nessun byte valido trovato (servono gruppi da 8 bit).' : 'No valid byte found (8-bit groups required).') : $bin];
            }

            $chars = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY);
            $truncated = false;
            if (count($chars) > 300) { $chars = array_slice($chars, 0, 300); $truncated = true; }
            $lines = [];
            $names = [32 => 'spazio', 10 => 'nuova riga', 9 => 'tab'];
            $namesEn = [32 => 'space', 10 => 'new line', 9 => 'tab'];
            foreach ($chars as $ch) {
                $cp = $ord($ch);
                $label = $ch === " " ? '<spazio>' : $ch;
                if ($cp === 10) $label = '<nuova riga>';
                if ($cp === 9) $label = '<tab>';
                $extra = isset($names[$cp]) ? '  (' . ($it ? $names[$cp] : $namesEn[$cp]) . ')' : '';
                $lines[] = str_pad((string)$cp, 7, ' ', STR_PAD_LEFT) . '  ' . str_pad(dechex($cp), 5, ' ', STR_PAD_LEFT) . '  ' . str_pad(($cp <= 255 ? decbin($cp) : ''), 9, ' ', STR_PAD_LEFT) . '  ' . $label . $extra;
            }
            $head = str_pad('DEC', 7, ' ', STR_PAD_LEFT) . '  ' . str_pad('HEX', 5, ' ', STR_PAD_LEFT) . '  ' . str_pad('BIN', 9, ' ', STR_PAD_LEFT) . '  ' . ($it ? 'CARATTERE' : 'CHARACTER');
            $tail = $truncated ? "\n" . ($it ? '(mostrati i primi 300 caratteri)' : '(first 300 characters shown)') : '';
            return ['content' => $head . "\n" . implode("\n", $lines) . $tail];
        },
        'related' => ['workmebinary', 'workmehash'],
    ],

    // ----------------------------------------------------
    'workmeorario' => [
        'name' => 'LUX.Hours', 'icon' => 'time', 'category' => 'produttivita', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola le ore lavorate fra due orari, toglie le pause e stima il guadagno con la paga oraria.',
        'desc_en' => 'Computes hours worked between two times, subtracts breaks and estimates pay from an hourly rate.',
        'action_it' => 'Calcola le ore', 'action_en' => 'Compute hours',
        'result_it' => 'Ore e guadagno', 'result_en' => 'Hours and pay',
        'cta_icon' => 'time',
        'fields' => [
            ['name' => 'start', 'type' => 'text', 'label_it' => 'Inizio (HH:MM)', 'label_en' => 'Start (HH:MM)', 'required' => true, 'default' => '09:00', 'max' => 5, 'ph_it' => '09:00', 'ph_en' => '09:00'],
            ['name' => 'end', 'type' => 'text', 'label_it' => 'Fine (HH:MM)', 'label_en' => 'End (HH:MM)', 'required' => true, 'default' => '18:00', 'max' => 5, 'ph_it' => '18:00', 'ph_en' => '18:00'],
            ['name' => 'pause', 'type' => 'number', 'label_it' => 'Pausa in minuti', 'label_en' => 'Break in minutes', 'default' => '60', 'min_value' => 0, 'max_value' => 600, 'step' => 5, 'max' => 3],
            ['name' => 'rate', 'type' => 'number', 'label_it' => 'Paga oraria in euro (facoltativo)', 'label_en' => 'Hourly pay in euro (optional)', 'default' => '', 'min_value' => 0, 'max_value' => 1000, 'step' => 0.5, 'max' => 6],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $toMin = function (string $s): ?int {
                if (!preg_match('/^(\d{1,2})[:.](\d{2})$/', trim($s), $m)) return null;
                $h = (int)$m[1]; $mi = (int)$m[2];
                if ($h > 23 || $mi > 59) return null;
                return $h * 60 + $mi;
            };
            $s = $toMin((string)$in['start']);
            $e = $toMin((string)$in['end']);
            if ($s === null || $e === null) {
                return ['content' => $it
                    ? "**Orario non valido.**\nScrivi gli orari come `09:00` e `18:30`."
                    : "**Invalid time.**\nWrite times like `09:00` and `18:30`."];
            }
            $crossed = false;
            $diff = $e - $s;
            if ($diff < 0) { $diff += 1440; $crossed = true; }
            $pause = max(0, (int)($in['pause'] ?? 0));
            if ($pause > $diff) $pause = $diff;
            $worked = $diff - $pause;
            $hours = intdiv($worked, 60);
            $mins  = $worked % 60;
            $decimal = $worked / 60;

            $rows = [];
            $rows[] = '- **' . ($it ? 'Intervallo' : 'Interval') . '**: ' . $in['start'] . ' - ' . $in['end'] . ($crossed ? ($it ? ' (notte, passa la mezzanotte)' : ' (crosses midnight)') : '');
            $rows[] = '- **' . ($it ? 'Durata totale' : 'Total duration') . '**: ' . sprintf('%02d:%02d', intdiv($diff, 60), $diff % 60);
            $rows[] = '- **' . ($it ? 'Pausa sottratta' : 'Break subtracted') . '**: ' . $pause . ' ' . ($it ? 'minuti' : 'minutes');
            $rows[] = '- **' . ($it ? 'Ore lavorate' : 'Hours worked') . '**: ' . sprintf('%d h %02d min', $hours, $mins) . '  (' . number_format($decimal, 2, ',', '.') . ' ' . ($it ? 'ore decimali' : 'decimal hours') . ')';
            $rate = (float)str_replace(',', '.', (string)($in['rate'] ?? ''));
            if ($rate > 0) {
                $pay = $decimal * $rate;
                $rows[] = '- **' . ($it ? 'Paga oraria' : 'Hourly pay') . '**: ' . number_format($rate, 2, ',', '.') . ' euro';
                $rows[] = '- **' . ($it ? 'Guadagno stimato' : 'Estimated pay') . '**: ' . number_format($pay, 2, ',', '.') . ' euro';
                $rows[] = '- **' . ($it ? 'Guadagno settimanale (5 giorni uguali)' : 'Weekly pay (5 identical days)') . '**: ' . number_format($pay * 5, 2, ',', '.') . ' euro';
                $rows[] = '- **' . ($it ? 'Guadagno mensile (21 giorni)' : 'Monthly pay (21 days)') . '**: ' . number_format($pay * 21, 2, ',', '.') . ' euro';
            }
            return ['content' => implode("\n", $rows), 'title' => sprintf('%d h %02d min', $hours, $mins)];
        },
        'related' => ['workmedates', 'workmecron'],
    ],

    // ----------------------------------------------------
    'workmebarcode' => [
        'name' => 'LUX.Barcode', 'icon' => 'grid', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Controlla e completa codici a barre EAN-13, EAN-8, UPC-A e ISBN: calcola la cifra di controllo.',
        'desc_en' => 'Validates and completes EAN-13, EAN-8, UPC-A and ISBN barcodes: computes the check digit.',
        'action_it' => 'Controlla il codice', 'action_en' => 'Check the code',
        'result_it' => 'Risultato', 'result_en' => 'Result',
        'cta_icon' => 'grid',
        'fields' => [
            ['name' => 'code', 'type' => 'text', 'label_it' => 'Codice (anche senza cifra di controllo)', 'label_en' => 'Code (check digit optional)', 'required' => true, 'max' => 20,
                'ph_it' => '801234567890 o 9781234567', 'ph_en' => '801234567890 or 9781234567'],
        ],
        'run' => function (array $in) {
            $it   = lux_tool_lang() === 'it';
            $code = preg_replace('/[^0-9Xx]/', '', (string)$in['code']);
            $len  = strlen($code);
            if ($len === 0) {
                return ['content' => $it ? 'Scrivi un codice numerico.' : 'Write a numeric code.'];
            }

            $ean = function (string $digits, int $len) {
                $sum = 0;
                $fromRight = 0;
                for ($i = $len - 1; $i >= 0; $i--) {
                    $d = (int)$digits[$i];
                    $sum += ($fromRight % 2 === 0) ? $d * 3 : $d;
                    $fromRight++;
                }
                return (10 - ($sum % 10)) % 10;
            };

            if ($len === 12 || $len === 13 || $len === 7 || $len === 8) {
                $bodyLen = $len - 1;
                $body = substr($code, 0, $bodyLen);
                $given = (int)$code[$bodyLen];
                $right = $ean($body, $bodyLen);
                $type = $len <= 8 ? 'EAN-8' : 'EAN-13';
                $lines = [];
                $lines[] = ($it ? 'Tipo rilevato: ' : 'Detected type: ') . $type;
                $lines[] = ($it ? 'Codice completo: ' : 'Full code: ') . $body . $right;
                $lines[] = ($it ? 'Cifra di controllo: ' : 'Check digit: ') . $right . ' (' . ($it ? 'calcolata' : 'computed') . ')';
                $lines[] = ($it ? 'Cifra nel codice che hai scritto: ' : 'Digit in the code you typed: ') . $given;
                $lines[] = ($right === $given ? ($it ? 'ESITO: il codice e corretto.' : 'RESULT: the code is correct.')
                                              : ($it ? 'ESITO: la cifra di controllo NON torna, il codice e sbagliato.' : 'RESULT: the check digit does NOT match, the code is wrong.'));
                if (substr($body, 0, 3) === '978' || substr($body, 0, 3) === '979') {
                    $lines[] = ($it ? 'Nota: prefisso 978/979, e un codice ISBN di un libro.' : 'Note: prefix 978/979, this is a book ISBN.');
                }
                if (substr($body, 0, 2) === '80' || substr($body, 0, 2) === '81') {
                    $lines[] = ($it ? 'Nota: prefisso 80/81, assegnato all\'Italia.' : 'Note: prefix 80/81, assigned to Italy.');
                }
                return ['content' => implode("\n", $lines)];
            }

            if ($len === 9 || $len === 10) {
                $body = substr($code, 0, 9);
                $sum = 0;
                for ($i = 0; $i < 9; $i++) $sum += (int)$body[$i] * (10 - $i);
                $right = (11 - ($sum % 11)) % 11;
                $rightChar = $right === 10 ? 'X' : (string)$right;
                $given = $len === 10 ? strtoupper($code[9]) : null;
                $lines = [];
                $lines[] = ($it ? 'Tipo rilevato: ISBN-10' : 'Detected type: ISBN-10');
                $lines[] = ($it ? 'Codice completo: ' : 'Full code: ') . $body . $rightChar;
                $lines[] = ($it ? 'Carattere di controllo: ' : 'Check character: ') . $rightChar;
                if ($given !== null) {
                    $lines[] = ($it ? 'Carattere scritto: ' : 'Character typed: ') . $given;
                    $lines[] = ($given === $rightChar ? ($it ? 'ESITO: corretto.' : 'RESULT: correct.') : ($it ? 'ESITO: NON corretto.' : 'RESULT: NOT correct.'));
                }
                return ['content' => implode("\n", $lines)];
            }

            return ['content' => $it
                ? "Lunghezza " . $len . " non gestita.\nSono supportati EAN-8 (8 cifre), EAN-13 e UPC-A (12/13 cifre), ISBN-10 (10 caratteri)."
                : "Length " . $len . " not supported.\nSupported: EAN-8 (8 digits), EAN-13 and UPC-A (12/13 digits), ISBN-10 (10 characters)."];
        },
        'related' => ['workmeiban', 'workmehash'],
    ],

    // ----------------------------------------------------
    'workmeinteresse' => [
        'name' => 'LUX.Grow', 'icon' => 'seedling', 'category' => 'produttivita', 'engine' => 'local',
        'output' => 'rich',
        'desc_it' => 'Calcola quanto cresce un risparmio con interesse composto e versamenti mensili, anno per anno.',
        'desc_en' => 'Computes how a saving grows with compound interest and monthly deposits, year by year.',
        'action_it' => 'Calcola la crescita', 'action_en' => 'Compute growth',
        'result_it' => 'Crescita del capitale', 'result_en' => 'Capital growth',
        'cta_icon' => 'seedling',
        'fields' => [
            ['name' => 'initial', 'type' => 'number', 'label_it' => 'Capitale iniziale (euro)', 'label_en' => 'Starting capital (euro)', 'default' => '1000', 'min_value' => 0, 'max_value' => 100000000, 'step' => 100, 'max' => 12],
            ['name' => 'monthly', 'type' => 'number', 'label_it' => 'Versamento mensile (euro)', 'label_en' => 'Monthly deposit (euro)', 'default' => '100', 'min_value' => 0, 'max_value' => 1000000, 'step' => 10, 'max' => 10],
            ['name' => 'rate', 'type' => 'number', 'label_it' => 'Interesse annuo (%)', 'label_en' => 'Annual interest (%)', 'default' => '5', 'min_value' => 0, 'max_value' => 100, 'step' => 0.1, 'max' => 6],
            ['name' => 'years', 'type' => 'number', 'label_it' => 'Anni', 'label_en' => 'Years', 'default' => '10', 'min_value' => 1, 'max_value' => 60, 'step' => 1, 'max' => 2],
            ['name' => 'freq', 'type' => 'select', 'label_it' => 'Frequenza di capitalizzazione', 'label_en' => 'Compounding frequency', 'default' => 'mensile',
                'options' => [['mensile', 'Mensile', 'Monthly'], ['trimestrale', 'Trimestrale', 'Quarterly'], ['annuale', 'Annuale', 'Yearly']],
            ],
        ],
        'run' => function (array $in) {
            $it = lux_tool_lang() === 'it';
            $initial = max(0, (float)str_replace(',', '.', (string)($in['initial'] ?? '0')));
            $monthly = max(0, (float)str_replace(',', '.', (string)($in['monthly'] ?? '0')));
            $rate    = max(0, (float)str_replace(',', '.', (string)($in['rate'] ?? '0'))) / 100;
            $years   = max(1, min(60, (int)($in['years'] ?? 1)));
            $freq    = (string)($in['freq'] ?? 'mensile');
            $perYear = $freq === 'annuale' ? 1 : ($freq === 'trimestrale' ? 4 : 12);
            $periodRate = $rate / $perYear;
            $monthsPerPeriod = (int)(12 / $perYear);
            $months  = $years * 12;

            $balance = $initial;
            $invested = $initial;
            $rows = [];
            $yearMark = 0;
            for ($m = 1; $m <= $months; $m++) {
                $balance += $monthly;
                $invested += $monthly;
                if ($m % $monthsPerPeriod === 0) $balance *= (1 + $periodRate);
                if ($m % 12 === 0) {
                    $yearMark++;
                    $rows[] = '| ' . $yearMark . ' | ' . number_format($balance, 2, ',', '.') . ' | ' . number_format($invested, 2, ',', '.') . ' | ' . number_format($balance - $invested, 2, ',', '.') . ' |';
                }
            }
            $interest = $balance - $invested;
            $head = [];
            $head[] = '- **' . ($it ? 'Versato in totale' : 'Total deposited') . '**: ' . number_format($invested, 2, ',', '.') . ' euro';
            $head[] = '- **' . ($it ? 'Interessi maturati' : 'Interest earned') . '**: ' . number_format($interest, 2, ',', '.') . ' euro';
            $head[] = '- **' . ($it ? 'Capitale finale' : 'Final capital') . '**: ' . number_format($balance, 2, ',', '.') . ' euro';
            $head[] = '- **' . ($it ? 'Crescita sul versato' : 'Growth on deposits') . '**: ' . ($invested > 0 ? number_format(($interest / $invested) * 100, 1, ',', '.') . '%' : '0%');

            $table = '';
            if ($rows && $years > 1) {
                $table = "\n\n### " . ($it ? 'Anno per anno' : 'Year by year') . "\n\n"
                    . '| ' . ($it ? 'Anno' : 'Year') . ' | ' . ($it ? 'Capitale' : 'Capital') . ' | ' . ($it ? 'Versato' : 'Deposited') . ' | ' . ($it ? 'Interessi' : 'Interest') . " |\n|---|---|---|---|\n"
                    . implode("\n", $rows);
            }
            $note = "\n\n" . ($it
                ? 'Stima matematica, non un consiglio finanziario: non tiene conto di tasse, inflazione e commissioni.'
                : 'Mathematical estimate, not financial advice: taxes, inflation and fees are not included.');
            return ['content' => implode("\n", $head) . $table . $note];
        },
        'related' => ['workmeloan', 'workmevat'],
    ],

    // ----------------------------------------------------
    'workmebinary' => [
        'name' => 'LUX.Base', 'icon' => 'cpu', 'category' => 'utility', 'engine' => 'local',
        'output' => 'mono',
        'desc_it' => 'Converte un valore fra binario, ottale, decimale, esadecimale e testo, con tutti i valori insieme.',
        'desc_en' => 'Converts a value between binary, octal, decimal, hexadecimal and text, showing all at once.',
        'action_it' => 'Converti', 'action_en' => 'Convert',
        'result_it' => 'Tutte le basi', 'result_en' => 'All bases',
        'cta_icon' => 'cpu',
        'fields' => [
            ['name' => 'value', 'type' => 'text', 'label_it' => 'Valore', 'label_en' => 'Value', 'required' => true, 'max' => 400,
                'ph_it' => '255 oppure 11111111 oppure FF', 'ph_en' => '255 or 11111111 or FF'],
            ['name' => 'base', 'type' => 'select', 'label_it' => 'Base di partenza', 'label_en' => 'Starting base', 'default' => '10',
                'options' => [['2', 'Binario (2)', 'Binary (2)'], ['8', 'Ottale (8)', 'Octal (8)'], ['10', 'Decimale (10)', 'Decimal (10)'], ['16', 'Esadecimale (16)', 'Hexadecimal (16)'], ['text', 'Testo', 'Text']],
            ],
        ],
        'run' => function (array $in) {
            $it    = lux_tool_lang() === 'it';
            $value = trim((string)$in['value']);
            $base  = (string)$in['base'];

            // Come sopra: nessuna dipendenza da mbstring.
            $chr = function (int $cp): string {
                if ($cp < 0x80) return chr($cp);
                if ($cp < 0x800) return chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F));
                if ($cp < 0x10000) return chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
                return chr(0xF0 | ($cp >> 18)) . chr(0x80 | (($cp >> 12) & 0x3F)) . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
            };
            $ord = function (string $ch): int {
                $b = array_values(unpack('C*', $ch));
                $n = count($b);
                if ($n === 2) return (($b[0] & 0x1F) << 6) | ($b[1] & 0x3F);
                if ($n === 3) return (($b[0] & 0x0F) << 12) | (($b[1] & 0x3F) << 6) | ($b[2] & 0x3F);
                if ($n === 4) return (($b[0] & 0x07) << 18) | (($b[1] & 0x3F) << 12) | (($b[2] & 0x3F) << 6) | ($b[3] & 0x3F);
                return $b[0];
            };

            if ($base === 'text') {
                $codes = [];
                foreach (preg_split('//u', $value, -1, PREG_SPLIT_NO_EMPTY) as $ch) {
                    $codes[] = $ord($ch);
                }
                if (!$codes) return ['content' => $it ? 'Scrivi del testo.' : 'Write some text.'];
                $rows = [];
                foreach ($codes as $i => $cp) {
                    $rows[] = str_pad((string)$cp, 8, ' ', STR_PAD_LEFT) . '  ' . str_pad(decbin($cp), 16, ' ', STR_PAD_LEFT) . '  ' . str_pad(dechex($cp), 6, ' ', STR_PAD_LEFT) . '  ' . $chr($cp);
                }
                $head = str_pad('DEC', 8, ' ', STR_PAD_LEFT) . '  ' . str_pad('BIN', 16, ' ', STR_PAD_LEFT) . '  ' . str_pad('HEX', 6, ' ', STR_PAD_LEFT) . '  ' . ($it ? 'CARATTERE' : 'CHARACTER');
                return ['content' => $head . "\n" . implode("\n", $rows)];
            }

            $clean = preg_replace('/[\s_]/', '', $value);
            $neg = false;
            if (substr($clean, 0, 1) === '-') { $neg = true; $clean = substr($clean, 1); }
            $patterns = ['2' => '/^[01]+$/', '8' => '/^[0-7]+$/', '10' => '/^\d+$/', '16' => '/^[0-9a-fA-F]+$/'];
            if ($clean === '' || !isset($patterns[$base]) || !preg_match($patterns[$base], $clean)) {
                return ['content' => $it
                    ? "**Valore non valido per la base " . $base . ".**\nControlla le cifre ammesse in quella base."
                    : "**Invalid value for base " . $base . ".**\nCheck the digits allowed in that base."];
            }
            // Limite di sicurezza: oltre queste cifre il valore non e' piu'
            // rappresentabile esattamente con gli interi a 64 bit di PHP.
            $maxDigits = ['2' => 63, '8' => 21, '10' => 18, '16' => 16];
            if (strlen($clean) > $maxDigits[$base]) {
                return ['content' => $it
                    ? "**Valore troppo grande.**\nIn base " . $base . " il massimo e' " . $maxDigits[$base] . " cifre (limite dei numeri interi)."
                    : "**Value too large.**\nIn base " . $base . " the maximum is " . $maxDigits[$base] . " digits (integer limit)."];
            }
            $dec = (int)base_convert($clean, (int)$base, 10);
            if ($neg) $dec = -$dec;

            $mag = abs($dec);
            $sgn = $dec < 0 ? '-' : '';
            $bitsUsed = strlen(decbin($mag));
            $rows = [];
            $rows[] = 'DEC    ' . $sgn . number_format($mag, 0, ',', '.');
            $rows[] = 'BIN    ' . $sgn . decbin($mag);
            $rows[] = 'OCT    ' . $sgn . decoct($mag);
            $rows[] = 'HEX    ' . $sgn . strtoupper(dechex($mag));
            $rows[] = 'BIT    ' . $bitsUsed . ' (' . (int)max(1, (int)ceil($bitsUsed / 8)) . ' byte)';
            if ($dec >= 32 && $dec <= 1114111) {
                $rows[] = 'CHAR   ' . $chr($dec);
            }
            $note = "\n" . ($it
                ? 'Base di partenza: ' . ($base === 'text' ? 'testo' : $base) . '. Numeri negativi gestiti col segno meno.'
                : 'Starting base: ' . $base . '. Negative numbers use a minus sign.');
            return ['content' => implode("\n", $rows) . $note];
        },
        'related' => ['workmeascii', 'workmehex'],
    ],
];
})();

// ---------- 4. MOTORE CONDIVISO ----------
// ============================================================
// L.U.X. VERSE - TOOL ENGINE
// Un solo motore per tutti gli strumenti del catalogo (includes/tools/*.php):
//   * UI identica e coerente con il design ONYX
//   * POST gestito in pagina (AJAX) come negli altri tool del sito
//   * engine "ai"    -> prompt costruito dallo spec, risposta ripulita
//   * engine "local" -> calcolo istantaneo in PHP, nessuna chiamata esterna
//   * i18n IT/EN, icone SVG (zero emoji), cronologia in localStorage
// Nessuna dipendenza esterna, nessuna emoji, nessun crash possibile: gli
// errori tornano sempre come JSON con success=false.
// ============================================================

if (!function_exists('lux_tools')) {

    /** Tutti gli strumenti extra (chiave => spec). */
    function lux_tools(): array
    {
        static $tools = null;
        if ($tools === null) {
            $ai    = $GLOBALS['__lux_ai'] ?? [];
            $local = $GLOBALS['__lux_local'] ?? [];
            $tools = $local + $ai;
            // La chiave dello strumento e' l'indice dell'array: la copiamo
            // dentro lo spec cosi' i link (pagina, strumenti correlati)
            // funzionano senza warning "undefined array key".
            foreach ($tools as $k => $spec) {
                $tools[$k]['key'] = $k;
            }
        }
        return $tools;
    }

    // ============================================================
    // STRUMENTI "AUTOMATICI" (catalogo senza spec dedicato)
    // ------------------------------------------------------------
    // data/projects.json e' l'elenco ufficiale. Se una chiave esiste
    // li' ma non ha uno spec in $__lux_ai/$__lux_local, la scheda
    // viene creata qui al volo (spec generico, motore AI, stessa UI
    // e stesso design L.U.X.). Cosi' il catalogo puo' crescere a
    // 1000+ strumenti toccando SOLO il .json: zero file, zero case.
    // ============================================================
    function lux_tool_auto(string $key): ?array
    {
        // Catalogo generato: lo slug e' "azione-argomento-preset" e la scheda
        // viene calcolata al volo (vedi includes/catalog.php). Nessun file,
        // nessun json: due lookup in array e la pagina esiste.
        if (strpos($key, '-') !== false) {
            $spec = lux_catalog_spec($key);
            if ($spec !== null) {
                $spec['related'] = [];
                foreach (lux_catalog_related($key, 6) as $rel) {
                    $spec['related'][] = (string)($rel['short'] ?? '');
                }
                $spec['related'] = array_values(array_filter($spec['related']));
                return $spec;
            }
            // Non e' una voce del catalogo generato, ma NON si esce qui: ci
            // sono strumenti con pagina propria il cui indirizzo contiene un
            // trattino (es. lux-podcast-brief). Vanno cercati piu' sotto, in
            // data/projects.json.
        }

        static $catalog = null;
        if ($catalog === null) {
            $catalog = [];
            foreach (getProjectsFromLocal() as $p) {
                $k = (string)($p['key'] ?? '');
                if ($k !== '') $catalog[$k] = $p;
            }
        }
        $p = $catalog[$key] ?? null;
        if (!$p) return null;

        $name   = (string)($p['name'] ?? 'LUX.' . ucfirst($key));
        $descIt = (string)($p['description_it'] ?? $name);
        $descEn = (string)($p['description_en'] ?? $descIt);

        return [
            'key'         => $key,
            'name'        => $name,
            'icon'        => (string)($p['icon'] ?? 'sparkles'),
            'category'    => (string)($p['category'] ?? 'utility'),
            'engine'      => 'ai',
            'output'      => 'rich',
            'temperature' => 0.7,
            'max_tokens'  => 1500,
            'desc_it'     => $descIt,
            'desc_en'     => $descEn,
            'action_it'   => 'Genera',
            'action_en'   => 'Generate',
            'result_it'   => 'Risultato',
            'result_en'   => 'Result',
            'cta_icon'    => 'sparkles',
            'fields'      => [[
                'name'     => 'topic',
                'type'     => 'textarea',
                'label_it' => 'Cosa vuoi generare?',
                'label_en' => 'What do you want to generate?',
                'rows'     => 6,
                'required' => true,
                'max'      => 3500,
                'ph_it'    => 'Descrivi cosa ti serve...',
                'ph_en'    => 'Describe what you need...',
            ]],
            'system_it'   => 'Sei "' . $name . '", uno strumento di L.U.X. Verse. Il tuo scopo: ' . $descIt . '. Rispondi sempre in modo chiaro, completo e ben organizzato, nella lingua richiesta dall\'utente.',
            'system_en'   => 'You are "' . $name . '", a L.U.X. Verse tool. Your purpose: ' . $descEn . '. Always answer clearly, completely and well organized, in the language requested by the user.',
            'prompt_it'   => 'Attivita\': ' . $descIt . "\n\nRichiesta utente:\n{topic}",
            'prompt_en'   => 'Task: ' . $descEn . "\n\nUser request:\n{topic}",
        ];
    }

    function lux_tool(string $key): ?array
    {
        $all = lux_tools();
        return $all[$key] ?? lux_tool_auto($key);
    }

    function lux_tool_lang(): string
    {
        return currentLang() === 'en' ? 'en' : 'it';
    }

    /** Campo localizzato dello spec (es. desc_it / desc_en). */
    function lux_tool_txt(array $tool, string $field): string
    {
        $lang = lux_tool_lang();
        return (string)($tool[$field . '_' . $lang] ?? $tool[$field . '_it'] ?? '');
    }

    /** Legge e valida gli input del form secondo lo spec. */
    function lux_tool_inputs(array $tool): array
    {
        $in = [];
        foreach ($tool['fields'] as $f) {
            $name = $f['name'];
            $val  = $_POST[$name] ?? ($f['default'] ?? '');
            if (!is_string($val)) $val = '';
            $val = str_replace(["\r\n", "\r"], "\n", trim($val));

            $max = (int)($f['max'] ?? 6000);
            if ($max > 0 && strlen($val) > $max) {
                $val = substr($val, 0, $max);
            }
            if (!empty($f['options']) && is_array($f['options'])) {
                $allowed = array_map(function ($o) { return (string)$o[0]; }, $f['options']);
                if ($val !== '' && !in_array($val, $allowed, true)) {
                    $val = (string)$allowed[0];
                }
                if ($val === '' && !empty($f['default'])) $val = (string)$f['default'];
            }
            if (($f['type'] ?? 'text') === 'number' && $val !== '') {
                $min = $f['min'] ?? null;
                $maxV = $f['max_value'] ?? null;
                if (!is_numeric(str_replace(',', '.', $val))) $val = (string)($f['default'] ?? '0');
            }
            if (($f['required'] ?? false) && $val === '') {
                jsonResponse(['success' => false, 'error' => t('Please fill in all fields!')]);
            }
            $in[$name] = $val;
        }
        return $in;
    }

    /** Esegue lo strumento (AI o locale) e ritorna la risposta JSON. */
    function lux_tool_execute(array $tool, array $in): array
    {
        $engine = $tool['engine'] ?? 'ai';

        if ($engine === 'local') {
            $fn = $tool['run'] ?? null;
            if (!is_callable($fn)) {
                return ['success' => false, 'error' => t('This tool is not available right now.')];
            }
            try {
                $out = $fn($in);
            } catch (Throwable $e) {
                return ['success' => false, 'error' => t('Calculation error. Check the values and try again.')];
            }
            if (!is_array($out) || !isset($out['content'])) {
                return ['success' => false, 'error' => t('Calculation error. Check the values and try again.')];
            }
            return [
                'success' => true,
                'engine'  => 'local',
                'content' => (string)$out['content'],
                'output'  => $out['output'] ?? ($tool['output'] ?? 'rich'),
                'title'   => $out['title'] ?? '',
                'meta'    => $out['meta'] ?? [],
            ];
        }

        $lang   = lux_tool_lang();
        $system = (string)($tool['system_' . $lang] ?? $tool['system_it'] ?? '');
        $tpl    = (string)($tool['prompt_' . $lang] ?? $tool['prompt_it'] ?? '');
        if ($tpl === '') {
            return ['success' => false, 'error' => t('This tool is not available right now.')];
        }
        $vars = [];
        foreach ($in as $k => $v) $vars['{' . $k . '}'] = $v;
        $prompt = trim(strtr($tpl, $vars));
        if ($prompt === '') {
            return ['success' => false, 'error' => t('Please fill in all fields!')];
        }

        $messages = [];
        if ($system !== '') $messages[] = ['role' => 'system', 'content' => $system];
        $messages[] = ['role' => 'user', 'content' => $prompt];

        $res = askGroq($messages, [
            'temperature' => (float)($tool['temperature'] ?? 0.7),
            'max_tokens'  => (int)($tool['max_tokens'] ?? 1600),
        ]);
        if (empty($res['success'])) {
            return ['success' => false, 'error' => $res['error'] ?? t('Empty response')];
        }

        return [
            'success' => true,
            'engine'  => 'ai',
            'content' => (string)$res['content'],
            'output'  => $tool['output'] ?? 'rich',
            'meta'    => ['model' => GROQ_MODEL],
        ];
    }

    /** Gestisce la richiesta POST (AJAX) e termina con JSON. */
    function lux_tool_handle_post(): void
    {
        $key  = (string)($_POST['lux_tool'] ?? '');
        $tool = lux_tool($key);
        if (!$tool) {
            jsonResponse(['success' => false, 'error' => t('Unknown tool.')], 404);
        }

        // Limite anti-abuso solo per gli strumenti con chiamata AI.
        if (($tool['engine'] ?? 'ai') === 'ai') {
            if (session_status() === PHP_SESSION_NONE && !headers_sent()) {
                lux_session_start();
            }
            $now = time();
            $rate = $_SESSION['lux_tool_rate'] ?? ['start' => $now, 'count' => 0];
            if ($now - (int)$rate['start'] > 300) $rate = ['start' => $now, 'count' => 0];
            $rate['count'] = (int)$rate['count'] + 1;
            $_SESSION['lux_tool_rate'] = $rate;
            if ($rate['count'] > 30) {
                jsonResponse([
                    'success' => false,
                    'error'   => t('Too many requests in a short time. Try again in a few minutes.'),
                ], 429);
            }
        }

        $in  = lux_tool_inputs($tool);
        $out = lux_tool_execute($tool, $in);
        if (empty($out['success'])) {
            jsonResponse($out);
        }
        jsonResponse($out);
    }

    /** Etichetta di categoria tradotta. */
    function lux_tool_category_label(string $cat): string
    {
        $map = [
            'creativita'   => t('Creativity'),
            'produttivita' => t('Productivity'),
            'educativi'    => t('Educational'),
            'giochi'       => t('Games'),
            'utility'      => t('Utilities'),
        ];
        return $map[$cat] ?? t('Utilities');
    }

    /** Markup di un campo del form. */
    function lux_tool_field(array $f): string
    {
        $lang  = lux_tool_lang();
        $name  = htmlspecialchars((string)$f['name'], ENT_QUOTES);
        $label = htmlspecialchars((string)($f['label_' . $lang] ?? $f['label_it'] ?? $f['name']), ENT_QUOTES);
        $ph    = htmlspecialchars((string)($f['ph_' . $lang] ?? $f['ph_it'] ?? ''), ENT_QUOTES);
        $req   = !empty($f['required']) ? ' *' : '';
        $type  = $f['type'] ?? 'text';
        $out   = '<div class="input-group">';
        $out  .= '<label for="f_' . $name . '">' . $label . $req . '</label>';

        switch ($type) {
            case 'textarea':
                $rows = (int)($f['rows'] ?? 6);
                $max  = (int)($f['max'] ?? 6000);
                $out .= '<textarea id="f_' . $name . '" name="' . $name . '" rows="' . $rows . '" '
                      . 'maxlength="' . $max . '" placeholder="' . $ph . '"></textarea>';
                break;

            case 'select':
                $out .= '<select id="f_' . $name . '" name="' . $name . '">';
                foreach (($f['options'] ?? []) as $opt) {
                    $val   = htmlspecialchars((string)$opt[0], ENT_QUOTES);
                    $olab  = htmlspecialchars((string)($opt[$lang === 'en' ? 2 : 1] ?? $opt[1] ?? $opt[0]), ENT_QUOTES);
                    $sel   = (string)($f['default'] ?? '') === (string)$opt[0] ? ' selected' : '';
                    $out  .= '<option value="' . $val . '"' . $sel . '>' . $olab . '</option>';
                }
                $out .= '</select>';
                break;

            case 'chips':
                $out .= '<div class="engine-chips" role="group">';
                foreach (($f['options'] ?? []) as $opt) {
                    $val  = htmlspecialchars((string)$opt[0], ENT_QUOTES);
                    $olab = htmlspecialchars((string)($opt[$lang === 'en' ? 2 : 1] ?? $opt[1] ?? $opt[0]), ENT_QUOTES);
                    $out .= '<button type="button" class="engine-chip" data-target="' . $name . '" data-value="' . $val . '">'
                          . $olab . '</button>';
                }
                $out .= '</div>';
                $out .= '<input type="hidden" id="f_' . $name . '" name="' . $name . '" value="' . htmlspecialchars((string)($f['default'] ?? ''), ENT_QUOTES) . '">';
                break;

            case 'number':
                $out .= '<input type="number" id="f_' . $name . '" name="' . $name . '" '
                      . 'value="' . htmlspecialchars((string)($f['default'] ?? ''), ENT_QUOTES) . '" '
                      . (isset($f['min_value']) ? 'min="' . htmlspecialchars((string)$f['min_value'], ENT_QUOTES) . '" ' : '')
                      . (isset($f['max_value']) ? 'max="' . htmlspecialchars((string)$f['max_value'], ENT_QUOTES) . '" ' : '')
                      . 'step="' . htmlspecialchars((string)($f['step'] ?? 'any'), ENT_QUOTES) . '" placeholder="' . $ph . '">';
                break;

            default:
                $max = (int)($f['max'] ?? 300);
                $out .= '<input type="text" id="f_' . $name . '" name="' . $name . '" maxlength="' . $max . '" '
                      . 'value="' . htmlspecialchars((string)($f['default'] ?? ''), ENT_QUOTES) . '" placeholder="' . $ph . '">';
        }

        if (!empty($f['hint_it'])) {
            $hint = htmlspecialchars((string)($f['hint_' . $lang] ?? $f['hint_it']), ENT_QUOTES);
            $out .= '<p class="engine-hint">' . $hint . '</p>';
        }
        return $out . '</div>';
    }

    /** Renderizza la pagina completa dello strumento (o risponde al POST). */
    function lux_render_tool(string $key): void
    {
        $tool = lux_tool($key);

        // Stato dello strumento. Vale anche per i 99.000 generati (vedi
        // lux_project_state): se l'amministrazione ha messo uno strumento in
        // manutenzione, pausa o bloccato, qui si avvisa invece di mostrarlo.
        $toolState = ($tool && function_exists('lux_project_state')) ? lux_project_state((string)$key) : 'attivo';
        if ($tool && $toolState !== 'attivo' && !isAdminLoggedIn()) {
            http_response_code(503);
            $pageTitle       = (string)($tool['name'] ?? 'L.U.X.');
            $pageDescription = '';
            lux_header();
            ?>
            <main>
                <section class="hero">
                    <div class="container">
                        <div class="hero-badge"><span class="dot" aria-hidden="true"></span><span><?= t('Temporarily unavailable') ?></span></div>
                        <h1 class="hero-title"><?= htmlspecialchars((string)($tool['name'] ?? 'L.U.X.')) ?></h1>
                        <p class="hero-lead"><?= t('This tool is currently {state}. It will be back soon.', ['state' => lux_project_state_label($toolState)]) ?></p>
                        <div class="hero-buttons">
                            <a href="index.php" class="btn-neon"><?= icon('grid', 17) ?><span><?= t('Explore Projects') ?></span></a>
                        </div>
                    </div>
                </section>
            </main>
            <?php
            lux_footer();
            return;
        }

        if (!$tool) {
            http_response_code(404);
            $tool = [
                'key' => 'nope', 'name' => 'L.U.X.', 'category' => 'utility', 'icon' => 'orb',
                'desc_it' => t('This tool is not available right now.'),
                'desc_en' => t('This tool is not available right now.'),
                'fields' => [],
            ];
        }

        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            lux_tool_handle_post();
        }

        $lang        = lux_tool_lang();
        $engine      = $tool['engine'] ?? 'ai';
        $name        = (string)$tool['name'];
        $desc        = lux_tool_txt($tool, 'desc');
        $badgeIcon   = (string)($tool['icon'] ?? 'sparkles');
        $category    = (string)($tool['category'] ?? 'utility');
        $output      = (string)($tool['output'] ?? 'rich');
        $submitLabel = lux_tool_txt($tool, 'action');
        if ($submitLabel === '') {
            $submitLabel = $engine === 'local' ? t('Calculate now') : t('Generate now');
        }
        $resultTitle = lux_tool_txt($tool, 'result');
        if ($resultTitle === '') $resultTitle = t('Your result');
        $phLabel     = htmlspecialchars($submitLabel, ENT_QUOTES);

        $related = [];
        foreach (($tool['related'] ?? []) as $rKey) {
            $r = lux_tool($rKey);
            if ($r) $related[] = $r;
        }

        $pageTitle       = $name . ' - ' . $desc;
        $pageDescription = $desc;
        $pageKeywords    = implode(', ', array_filter([$name, $category, 'L.U.X.', 'L.U.X. Verse', 'AI', 'free tools']));
        $extraCSS        = lux_tool_css();
        $hideMarketing   = false;

        // Le variabili qui sopra sono locali a questa funzione: le passiamo
        // esplicitamente all'header (che altrimenti le leggerebbe dal globale).
        lux_header([
            'pageTitle'       => $pageTitle ?? null,
            'pageDescription' => $pageDescription ?? null,
            'pageKeywords'    => $pageKeywords ?? null,
            'extraCSS'        => $extraCSS ?? null,
        ]);
        ?>
<main>

