        <div class="container">
            <div class="hero-badge">
                <?= icon($badgeIcon, 14) ?>
                <?= htmlspecialchars(lux_tool_category_label($category)) ?>
                <?php if ($engine === 'local'): ?>
                    <span class="engine-tag"><?= t('Instant') ?></span>
