<script>
(function () {
    'use strict';

    var KEY         = <?= json_encode($key) ?>;
    var OUTPUT      = <?= json_encode($output) ?>;
    var ENGINE      = <?= json_encode($engine) ?>;
    var IS_LOCAL    = ENGINE === 'local';
    var HISTORY_KEY = 'luxtool_' + KEY + '_history';
    var MAX_HISTORY = 5;
    var current     = '';
    var lastInput   = {};
    var form        = document.getElementById('engineForm');
    var submitBtn   = document.getElementById('engineSubmit');
    var loading     = document.getElementById('loadingBox');
    var wrapper     = document.getElementById('resultWrapper');
    var out         = document.getElementById('engineOutput');
    var metaEl      = document.getElementById('resultMeta');

    var T = {
        done:    <?= json_encode(t('Done')) ?>,
        toastError: <?= json_encode(t('Connection error')) ?>,
        empty:   <?= json_encode(t('No results saved')) ?>,
        copied:  <?= json_encode(t('Copied!')) ?>,
        nothing: <?= json_encode(t('Nothing to copy')) ?>,
        downloaded: <?= json_encode(t('Downloaded!')) ?>,
        fetching: <?= json_encode($engine === 'local' ? t('Calculating...') : t('Working...')) ?>,
        listenUnsupported: <?= json_encode(t('The reading is not available on this browser')) ?>
    };

    /* preset rapidi */
    document.querySelectorAll('.engine-chip').forEach(function (chip) {
        chip.addEventListener('click', function () {
            var target = document.getElementById('f_' + chip.dataset.target);
            if (!target) return;
            target.value = chip.dataset.value;
            document.querySelectorAll('.engine-chip[data-target="' + chip.dataset.target + '"]')
                .forEach(function (c) { c.classList.remove('active'); });
            chip.classList.add('active');
            target.dispatchEvent(new Event('change', { bubbles: true }));
        });
    });

    function render(content, title, meta) {
        current = content || '';
        if (OUTPUT === 'mono') {
            out.textContent = current;
        } else {
            out.innerHTML = (typeof markdownToHTML === 'function') ? markdownToHTML(current) : current;
            if (window.luxUpgrade) window.luxUpgrade(out);
        }
        metaEl.textContent = meta || '';
        wrapper.classList.add('active');
        wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function history() {
        try { return JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]'); } catch (e) { return []; }
    }
    function saveHistory(list) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(list.slice(0, MAX_HISTORY))); } catch (e) {}
    }
    function renderHistory() {
        var list = document.getElementById('historyList');
        var items = history();
        if (!list) return;
        if (!items.length) {
            list.innerHTML = '<div class="history-empty">' + T.empty + '</div>';
            return;
        }
        list.innerHTML = items.map(function (item, i) {
            var when = new Date(item.date);
            var label = when.toLocaleDateString() + ' ' + when.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            var preview = String(item.input || '').substring(0, 70);
            return '<div class="history-item" onclick="window.__engineLoad(' + i + ')">'
                + '<div class="history-item-info">'
                + '<div class="history-item-preview">' + escapeHtml(preview) + '</div>'
                + '<div class="history-item-date">' + label + '</div>'
                + '</div></div>';
        }).join('');
    }

    window.__engineLoad = function (i) {
        var item = history()[i];
        if (!item) return;
        render(item.content, item.title || '', '');
    };

    form.addEventListener('submit', function (e) {
        e.preventDefault();
        var data = new FormData(form);
        lastInput = {};
        data.forEach(function (v, k) { if (k !== 'lux_tool') lastInput[k] = v; });

        var original = submitBtn.innerHTML;
        submitBtn.disabled = true;
        submitBtn.querySelector('.engine-btn-text').textContent = T.fetching;
        loading.classList.add('active');
        wrapper.classList.remove('active');

        fetch(window.location.pathname, { method: 'POST', body: data, headers: { 'X-Requested-With': 'fetch' } })
            .then(function (r) { return r.json(); })
            .then(function (res) {
                loading.classList.remove('active');
                if (res.success) {
                    render(res.content, res.title || '', res.meta && res.meta.model ? res.meta.model : '');
                    var items = history();
                    items.unshift({
                        input: Object.keys(lastInput).map(function (k) { return lastInput[k]; }).join(' · ').substring(0, 120),
                        title: res.title || '',
                        content: res.content,
                        date: new Date().toISOString()
                    });
                    saveHistory(items);
                    renderHistory();
                    showToast(T.done, 'success');
                } else {
                    showToast(res.error || T.toastError, 'error');
                }
            })
            .catch(function () {
                loading.classList.remove('active');
                showToast(T.toastError, 'error');
            })
            .then(function () {
                submitBtn.disabled = false;
                submitBtn.innerHTML = original;
            });
    });

    window.engineCopy = function () {
        if (!current) { showToast(T.nothing, 'error'); return; }
        navigator.clipboard.writeText(current)
            .then(function () { showToast(T.copied, 'success'); })
            .catch(function () { showToast(T.toastError, 'error'); });
    };

    window.engineDownload = function () {
        if (!current) { showToast(T.nothing, 'error'); return; }
        var date = new Date().toISOString().slice(0, 10);
        var head = <?= json_encode($name) ?> + ' - ' + date + '\n\n';
        var blob = new Blob([head + current], { type: 'text/plain;charset=utf-8' });
        var a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = KEY + '_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(a.href);
        showToast(T.downloaded, 'success');
    };

    window.engineSpeak = function () {
        if (!current) { showToast(T.nothing, 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast(T.listenUnsupported, 'error'); return; }
        var u = new SpeechSynthesisUtterance(current);
        u.lang = <?= json_encode(currentLang() === 'it' ? 'it-IT' : 'en-US') ?>;
        speechSynthesis.cancel();
        speechSynthesis.speak(u);
    };

    window.engineClearHistory = function () {
        saveHistory([]);
        renderHistory();
    };

    renderHistory();
})();
</script>
<?php
        lux_footer();
    }

    /** CSS specifico del motore (condiviso da tutti gli strumenti). */
    function lux_tool_css(): string
    {
        return '
.engine-tag{font-family:var(--font-mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--bone);border:1px solid var(--line-3);padding:1px 6px;margin-left:8px}
.engine-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:4px}
.engine-chip{font:inherit;font-size:13px;padding:8px 14px;background:transparent;color:var(--text-light);border:1px solid var(--line-2);cursor:pointer;transition:border-color .15s,color .15s}
.engine-chip:hover{border-color:var(--line-3);color:var(--bone)}
.engine-chip.active{border-color:var(--gold);color:var(--bone)}
.engine-hint{font-size:12px;color:var(--text-muted);margin-top:6px}
.engine-out{background:var(--ink-2);border:1px solid var(--line-2);border-left:2px solid var(--gold);padding:22px;line-height:1.75;color:var(--text-light);word-break:break-word}
.engine-out h1,.engine-out h2,.engine-out h3{font-family:var(--font-title);color:var(--bone);margin:18px 0 10px;letter-spacing:-.02em}
.engine-out h1:first-child,.engine-out h2:first-child,.engine-out h3:first-child{margin-top:0}
.engine-out p{margin:0 0 12px}
.engine-out ul,.engine-out ol{margin:0 0 14px 22px}
.engine-out li{margin-bottom:6px}
.engine-out code{font-family:var(--font-mono);font-size:.92em;background:var(--ink-3);border:1px solid var(--line-2);padding:1px 5px}
.engine-pre{font-family:var(--font-mono);font-size:13.5px;line-height:1.7;background:var(--ink-2);border:1px solid var(--line-2);border-left:2px solid var(--gold);padding:20px;color:var(--bone);white-space:pre-wrap;word-break:break-word;overflow-x:auto;max-height:520px}
.engine-meta{font-family:var(--font-mono);font-size:11px;letter-spacing:.04em}
@media (max-width:640px){
  .engine-out,.engine-pre{padding:16px}
  .engine-pre{font-size:12.5px}
}
';
    }
}

