// === AI REQUEST (AJAX) ===
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['theme'])) {
    $theme = trim($_POST['theme'] ?? '');

    if (empty($theme)) {
        jsonResponse(['success' => false, 'error' => t('Missing theme')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei un esperto di colori. Rispondi solo con JSON.';
        $prompt = "Genera una palette di 5 colori per il tema: '$theme'. Rispondi SOLO con un JSON array di 5 oggetti, ogni oggetto con 'hex', 'nome' e 'descrizione'. Formato: [{\"hex\":\"#D96C5B\",\"nome\":\"Rosso\",\"descrizione\":\"Descrizione\"}]";
    } else {
        $systemPrompt = 'You are a color expert. Answer only with JSON.';
        $prompt = "Generate a palette of 5 colors for the theme: '$theme'. Answer ONLY with a JSON array of 5 objects, each object with 'hex', 'nome' and 'descrizione'. Format: [{\"hex\":\"#D96C5B\",\"nome\":\"Red\",\"descrizione\":\"Description\"}]";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 500]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);

    $content = $result['content'];
    $palette = [];
    $direct = json_decode($content, true);
    if (is_array($direct)) $palette = $direct;
    else {
        preg_match('/\[.*\]/s', $content, $matches);
        if (!empty($matches[0])) $palette = json_decode($matches[0], true) ?? [];
    }

    if (empty($palette)) jsonResponse(['success' => false, 'error' => t('Invalid AI response')]);

    jsonResponse(['success' => true, 'result' => $palette, 'theme' => $theme]);
}

