<script>
    let currentPalette = [];
    let currentTheme = '';
    const HISTORY_KEY = 'workmechroma_history';
    const MAX_HISTORY = 5;

    function setTheme(theme) {
        document.getElementById('themeInput').value = theme;
        document.getElementById('themeInput').focus();
    }

    async function generatePalette() {
        const theme = document.getElementById('themeInput').value.trim();
        if (!theme) {
            showToast('Write a palette theme!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Generating...';

        document.getElementById('paletteWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('theme', theme);

            const response = await fetch('coloriamo.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentPalette = data.result;
                currentTheme = data.theme;
                renderPalette(data.result, data.theme);
                saveToHistory(data.result, data.theme);
                showToast('Palette generated!', 'success');
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function renderPalette(palette, theme) {
        document.getElementById('paletteTheme').textContent = theme;
        const grid = document.getElementById('paletteGrid');
        grid.innerHTML = '';

        palette.forEach((color, index) => {
            const card = document.createElement('div');
            card.className = 'palette-card';
            card.style.background = color.hex;
            card.onclick = () => copyColor(color.hex, color.nome);

            const rgb = hexToRgb(color.hex);
            const brightness = (rgb.r * 299 + rgb.g * 587 + rgb.b * 114) / 1000;
            const textColor = brightness > 155 ? '#121417' : '#FFFFFF';

            card.innerHTML =
                '<div class="color-name" style="color: ' + textColor + ';">' + escapeHtml(color.nome || 'Color ' + (index + 1)) + '</div>' +
                '<div class="color-hex" style="color: ' + textColor + '; background: ' + (brightness > 155 ? 'rgba(0,0,0,0.1)' : 'rgba(0,0,0,0.3)') + ';">' + color.hex.toUpperCase() + '</div>' +
                '<div class="color-desc" style="color: ' + textColor + ';">' + escapeHtml(color.descrizione || '') + '</div>';

            grid.appendChild(card);
        });

        document.getElementById('paletteWrapper').classList.add('active');
        document.getElementById('paletteWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function copyColor(hex, name) {
        navigator.clipboard.writeText(hex).then(() => {
            showToast('Copied:' + hex + (name ? ' (' + name + ')' : ''), 'success');
        }).catch(() => {
            const temp = document.createElement('input');
            temp.value = hex;
            document.body.appendChild(temp);
            temp.select();
            document.execCommand('copy');
            document.body.removeChild(temp);
            showToast('Copied:' + hex, 'success');
        });
    }

    function copyAllPalette() {
        if (currentPalette.length === 0) return;
        const allHex = currentPalette.map(c => c.hex).join(', ');
        navigator.clipboard.writeText(allHex).then(() => {
            showToast('All colors copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadPalette() {
        if (currentPalette.length === 0) return;
        const data = {
            theme: currentTheme,
            palette: currentPalette,
            date: new Date().toISOString()
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmechroma_palette_' + currentTheme.replace(/\s+/g, '_') + '.json';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Palette downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(palette, theme) {
        let history = loadHistory();
        history = history.filter(h => h.theme !== theme);
        history.unshift({
            theme: theme,
            palette: palette,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No palettes saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            let swatches = '';
            item.palette.forEach(c => {
                swatches += '<div class="history-swatch" style="background: ' + c.hex + ';"></div>';
            });
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-preview">' + swatches + '</div>' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-theme">' + escapeHtml(item.theme) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentPalette = history[index].palette;
            currentTheme = history[index].theme;
            document.getElementById('themeInput').value = history[index].theme;
            renderPalette(history[index].palette, history[index].theme);
            showToast('Palette loaded from history', 'success');
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole palette history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    function hexToRgb(hex) {
        hex = hex.replace('#', '');
        if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
        return {
            r: parseInt(hex.substr(0, 2), 16),
            g: parseInt(hex.substr(2, 2), 16),
            b: parseInt(hex.substr(4, 2), 16)
        };
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

