<script>
    let currentComparison = '';
    let currentProductA = '';
    let currentProductB = '';

    const HISTORY_KEY = 'workmecompare_history';
    const MAX_HISTORY = 5;

    function setPair(a, b) {
        document.getElementById('productA').value = a;
        document.getElementById('productB').value = b;
    }

    document.getElementById('productA').addEventListener('keydown', function(e) {
        if (e.key === 'Enter') document.getElementById('productB').focus();
    });
    document.getElementById('productB').addEventListener('keydown', function(e) {
        if (e.key === 'Enter') compareProducts();
    });

    async function compareProducts() {
        const productA = document.getElementById('productA').value.trim();
        const productB = document.getElementById('productB').value.trim();
        if (!productA || !productB) {
            showToast('Enter both products to compare!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Comparing...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('compare', '1');
            formData.append('product_a', productA);
            formData.append('product_b', productB);

            const response = await fetch('comparami.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentComparison = data.comparison;
                currentProductA = productA;
                currentProductB = productB;
                document.getElementById('resultContent').innerHTML = markdownToHTML(data.comparison);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(data.comparison, productA, productB);
                showToast('Comparison ready!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyComparison() {
        if (!currentComparison) {
            showToast('No comparison to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentComparison).then(() => {
            showToast('Comparison copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadComparison() {
        if (!currentComparison) {
            showToast('No comparison to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'COMPARISON - LUX.Compare\nDate: ' + date + '\nProducts: ' + currentProductA +
                        ' vs ' + currentProductB + '\n\n' + currentComparison;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmecompare_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Comparison downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(comparison, productA, productB) {
        let history = loadHistory();
        history = history.filter(h => h.comparison !== comparison);
        history.unshift({
            comparison: comparison,
            productA: productA,
            productB: productB,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No comparisons saved</div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = (item.productA || '') + ' vs ' + (item.productB || '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentComparison = history[index].comparison;
            currentProductA = history[index].productA;
            currentProductB = history[index].productB;
            document.getElementById('resultContent').innerHTML = markdownToHTML(history[index].comparison);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Comparison loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the comparisons history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

