// FASE 1: analisi descrizione -> domande
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['analyze'])) {
    $description = trim($_POST['description'] ?? '');

    if (empty($description)) {
        jsonResponse(['success' => false, 'error' => t('Write a description!')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei un assistente che aiuta a raccogliere informazioni per creare siti web. Rispondi SOLO con un array JSON.';
        $prompt = "Leggi questa descrizione del sito e genera esattamente 5 domande mirate per capire meglio cosa desidera l'utente (stile, sezioni, colori, funzionalita, contenuti). Rispondi SOLO con un array JSON di 5 oggetti con una chiave \"domanda\" ciascuno, come: [{\"domanda\":\"testo\"}]. Descrizione: \"$description\"";
    } else {
        $systemPrompt = 'You are an assistant that helps collect information to create websites. Reply ONLY with a JSON array.';
        $prompt = "Read this website description and generate exactly 5 targeted questions to better understand what the user wants (style, sections, colors, features, contents). Reply ONLY with a JSON array of 5 objects, each with a \"domanda\" key, like: [{\"domanda\":\"text\"}]. Description: \"$description\"";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 500]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);

    $content = trim($result['content']);
    if (preg_match('/```(?:json)?\s*([\s\S]*?)```/', $content, $m)) $content = trim($m[1]);

    $start = strpos($content, '[');
    $end = strrpos($content, ']');
    $questions = [];
    if ($start !== false && $end !== false && $end > $start) {
        $decoded = json_decode(trim(substr($content, $start, $end - $start + 1)), true);
        if (is_array($decoded)) {
            foreach ($decoded as $item) {
                if (is_array($item) && isset($item['domanda']) && trim($item['domanda']) !== '') {
                    $questions[] = ['domanda' => trim($item['domanda'])];
                }
            }
        }
    }

    if (count($questions) === 0) {
        jsonResponse(['success' => false, 'error' => t('Could not read the AI response. Try again!')]);
    }

    jsonResponse(['success' => true, 'questions' => array_slice($questions, 0, 5)]);
}

// FASE 2: descrizione + risposte -> codice
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate'])) {
    $description = trim($_POST['description'] ?? '');
    $answersRaw = json_decode($_POST['answers'] ?? '[]', true);
    $answers = is_array($answersRaw) ? array_map(function($v) { return trim((string)$v); }, $answersRaw) : [];

    if (empty($description)) {
        jsonResponse(['success' => false, 'error' => t('Write a description!')]);
    }

    $answersText = '';
    foreach ($answers as $i => $answer) {
        $answersText .= ($i + 1) . '. ' . ($answer !== '' ? $answer : '-') . "\n";
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei uno sviluppatore web esperto. Crei siti web completi, moderni e funzionanti.';
        $prompt = "Descrizione del sito: \"$description\"\n\nRisposte dell'utente alle domande:\n$answersText\n\nGenera un sito web completo in un unico file HTML. Rispondi SOLO con tre blocchi separati da questi marcatori esatti:\n###HTML###\n(contenuto della pagina, solo markup da mettere dentro <body>)\n###CSS###\n(tutto il CSS, ben organizzato, con variabili di colore e responsive)\n###JS###\n(tutto il JavaScript)";
    } else {
        $systemPrompt = 'You are an expert web developer. You create complete, modern and functional websites.';
        $prompt = "Website description: \"$description\"\n\nUser answers to the questions:\n$answersText\n\nGenerate a complete website in a single HTML file. Reply ONLY with three blocks separated by these exact markers:\n###HTML###\n(page content, only markup to put inside <body>)\n###CSS###\n(all the CSS, well organized, with color variables and responsive)\n###JS###\n(all the JavaScript)";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 4000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);

    $content = $result['content'];
    $html = '';
    $css = '';
    $js = '';

    if (preg_match('/###HTML###\s*([\s\S]*?)(?=###CSS###|$)/i', $content, $m)) $html = trim($m[1]);
    if (preg_match('/###CSS###\s*([\s\S]*?)(?=###JS###|$)/i', $content, $m)) $css = trim($m[1]);
    if (preg_match('/###JS###\s*([\s\S]*?)$/i', $content, $m)) $js = trim($m[1]);

    if ($html === '') {
        jsonResponse(['success' => false, 'error' => t('Could not read the AI response. Try again!')]);
    }

    jsonResponse(['success' => true, 'html' => $html, 'css' => $css, 'js' => $js]);
}

