<script>
    // ===== GLOBAL STATE =====
    let currentQuestions = [];
    let generatedHtml = '';
    let generatedCss = '';
    let generatedJs = '';
    let currentDescription = '';
    const HISTORY_KEY = 'workmecode_history';
    const MAX_HISTORY = 5;

    // ===== STEP INDICATOR =====
    function setStep(step) {
        document.getElementById('stepDot1').className = 'step-dot' + (step === 1 ? ' active' : (step > 1 ? ' completed' : ''));
        document.getElementById('stepDot2').className = 'step-dot' + (step === 2 ? ' active' : (step > 2 ? ' completed' : ''));
        document.getElementById('stepDot3').className = 'step-dot' + (step === 3 ? ' active' : (step > 3 ? ' completed' : ''));
    }

    // ===== QUICK EXAMPLES =====
    function setDescription(text) {
        document.getElementById('descriptionInput').value = text;
        document.getElementById('descriptionInput').focus();
        showToast('Example loaded!', 'success');
    }

    // ===== STEP 1: ANALYZE =====
    async function analyzeDescription() {
        const description = document.getElementById('descriptionInput').value.trim();
        if (!description) {
            showToast('Write a description!', 'error');
            return;
        }

        const btn = document.getElementById('analyzeBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Analyzing...';

        document.getElementById('loadingText').textContent = 'Analyzing the description...';
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('analyze', '1');
            formData.append('description', description);

            const response = await fetch('facciolo.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentQuestions = data.questions;
                currentDescription = description;
                showQuestions();
                setStep(2);
                showToast('Questions generated!', 'success');
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    // ===== STEP 2: SHOW QUESTIONS =====
    function showQuestions() {
        document.getElementById('phase-1').style.display = 'none';
        document.getElementById('phase-2').style.display = 'block';
        const container = document.getElementById('questions-container');
        container.innerHTML = '';
        currentQuestions.forEach((q, index) => {
            const div = document.createElement('div');
            div.className = 'question-item';
            div.innerHTML =
                '<label>' + escapeHtml(q.domanda) + '</label>' +
                '<input type="text" class="answer-input" data-index="' + index + '" placeholder="Your answer...">';
            container.appendChild(div);
        });
    }

    // ===== STEP 3: GENERATE CODE =====
    async function generateCode() {
        const description = document.getElementById('descriptionInput').value.trim();
        const answers = [];
        document.querySelectorAll('.answer-input').forEach(input => {
            answers.push(input.value.trim());
        });

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Generating...';

        document.getElementById('loadingText').textContent = 'Generating the code...';
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('description', description);
            formData.append('answers', JSON.stringify(answers));

            const response = await fetch('facciolo.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                generatedHtml = data.html;
                generatedCss = data.css;
                generatedJs = data.js;
                document.getElementById('html-content').textContent = data.html;
                document.getElementById('css-content').textContent = data.css;
                document.getElementById('js-content').textContent = data.js;

                const preview = document.getElementById('previewFrame');
                const doc = preview.contentDocument || preview.contentWindow.document;
                doc.open();
                doc.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><style>' + data.css + '</style></head><body>' + data.html + '<script>' + data.js + '<\/script></body></html>');
                doc.close();

                document.getElementById('resultGrid').classList.add('active');
                document.getElementById('phase-2').style.display = 'none';
                document.getElementById('historySection').style.display = 'block';
                setStep(3);
                saveToHistory(description, data.html, data.css, data.js);
                showToast('Code generated!', 'success');
                document.getElementById('resultGrid').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    // ===== COPY SECTION =====
    function copySection(type) {
        const content = type === 'html' ? generatedHtml : (type === 'css' ? generatedCss : generatedJs);
        if (!content) { showToast('No code to copy', 'error'); return; }
        navigator.clipboard.writeText(content).then(() => {
            showToast(type.toUpperCase() + ' copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    // ===== OPEN SITE =====
    function openSite() {
        if (!generatedHtml) { showToast('Generate the code first!', 'error'); return; }
        const fullCode = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>' + generatedCss + '</style></head><body>' + generatedHtml + '<script>' + generatedJs + '<\/script></body></html>';
        const blob = new Blob([fullCode], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        window.open(url, '_blank');
        setTimeout(() => URL.revokeObjectURL(url), 10000);
    }

    // ===== DOWNLOAD HTML =====
    function downloadCode() {
        if (!generatedHtml) { showToast('Generate the code first!', 'error'); return; }
        const fullCode = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Site generated by LUX.Code</title><style>' + generatedCss + '</style></head><body>' + generatedHtml + '<script>' + generatedJs + '<\/script></body></html>';
        const blob = new Blob([fullCode], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmecode_site_' + new Date().toISOString().slice(0, 10) + '.html';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Site downloaded!', 'success');
    }

    // ===== HISTORY =====
    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(description, html, css, js) {
        let history = loadHistory();
        history = history.filter(h => h.description !== description);
        history.unshift({
            description: description,
            html: html,
            css: css,
            js: js,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        const section = document.getElementById('historySection');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No sites saved</div>';
            return;
        }
        section.style.display = 'block';
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString({ day: '2-digit', month: '2-digit' }) + ' ' +
                            date.toLocaleTimeString({ hour: '2-digit', minute: '2-digit' });
            const preview = item.description.length > 80 ? item.description.substring(0, 80) + '...' : item.description;
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                    '<div class="history-item-date">' + timeStr + '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            generatedHtml = history[index].html;
            generatedCss = history[index].css;
            generatedJs = history[index].js;
            currentDescription = history[index].description;
            document.getElementById('html-content').textContent = generatedHtml;
            document.getElementById('css-content').textContent = generatedCss;
            document.getElementById('js-content').textContent = generatedJs;

            const preview = document.getElementById('previewFrame');
            const doc = preview.contentDocument || preview.contentWindow.document;
            doc.open();
            doc.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><style>' + generatedCss + '</style></head><body>' + generatedHtml + '<script>' + generatedJs + '<\/script></body></html>');
            doc.close();

            document.getElementById('resultGrid').classList.add('active');
            setStep(3);
            showToast('Site loaded from history', 'success');
            document.getElementById('resultGrid').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole websites history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
        setStep(1);
    });
</script>

