if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate'])) {
    $planType = trim($_POST['plan_type'] ?? '');
    $topic = trim($_POST['topic'] ?? '');
    $days = trim($_POST['days'] ?? '');
    $level = trim($_POST['level'] ?? '');
    $grade = trim($_POST['grade'] ?? '');

    if (empty($planType) || empty($topic) || empty($days) || empty($level)) {
        jsonResponse(['success' => false, 'error' => t('Fill in all the required fields!')]);
    }

    $planTypeMap = [
        'studio' => 'Studio Scolastico',
        'esame' => 'Preparazione Esame',
        'allenamento' => 'Allenamento / Palestra',
        'dieta' => 'Dieta / Nutrizione',
        'risparmio' => 'Risparmio Economico',
        'lavoro' => 'Progetto di Lavoro',
        'evento' => 'Organizzazione Eventi',
        'pulizia' => 'Pulizia Casa',
        'viaggio' => 'Pianificazione Viaggio',
        'lingua' => 'Apprendimento Lingua',
        'personale' => 'Sviluppo Personale',
        'marketing' => 'Marketing / Social Media',
        'lettura' => 'Piano di Lettura',
        'musica' => 'Apprendimento Strumento Musicale',
        'arte' => 'Progetto Artistico',
        'cucina' => 'Piano Culinario',
        'altro' => 'Altro'
    ];
    $planTypeName = $planTypeMap[$planType] ?? $planType;

    $levelMap = [
        'principiante' => 'Principiante',
        'base' => 'Base',
        'intermedio' => 'Intermedio',
        'avanzato' => 'Avanzato',
        'esperto' => 'Esperto'
    ];
    $levelName = $levelMap[$level] ?? $level;

    $gradeMap = [
        'elementari' => 'Scuola Elementare',
        'medie' => 'Scuola Media',
        'superiori' => 'Scuola Superiore',
        'universita' => 'Università',
        'master' => 'Master',
        'nessuno' => 'Nessun grado specifico'
    ];
    $gradeName = $gradeMap[$grade] ?? 'nessuno';

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei un esperto nella creazione di piani personalizzati. Crea piani realistici, dettagliati e organizzati per qualsiasi tipo di obiettivo. Usa testo semplice, paragrafi e punti elenco. Non usare tabelle.';
        $prompt = "Crea un piano dettagliato per: $planTypeName. Argomento/Obiettivo: $topic. Giorni a disposizione: $days. Livello: $levelName. Grado di istruzione (se applicabile): $gradeName. Organizza il piano giorno per giorno con attività specifiche e realistiche. Aggiungi anche consigli finali. Usa SOLO testo semplice con paragrafi e punti elenco. NON usare tabelle. Rispondi in modo COMPLETO.";
    } else {
        $systemPrompt = 'You are an expert at creating personalized plans. Create realistic, detailed and organized plans for any type of goal. Use plain text, paragraphs and bullet points. Do not use tables.';
        $prompt = "Create a detailed plan for: $planTypeName. Topic/Goal: $topic. Days available: $days. Level: $levelName. Education grade (if applicable): $gradeName. Organize the plan day by day with specific and realistic activities. Also add final tips. Use ONLY plain text with paragraphs and bullet points. Do NOT use tables. Answer in a COMPLETE way.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 4000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);

    jsonResponse(['success' => true, 'result' => $result['content']]);
}

