<script>
    let currentPlan = '';
    let currentTopic = '';
    const HISTORY_KEY = 'workmeplan_history';
    const MAX_HISTORY = 5;

    function setExample(type, topic, days, level, grade) {
        document.getElementById('planType').value = type;
        document.getElementById('topic').value = topic;
        document.getElementById('days').value = days;
        document.getElementById('level').value = level;
        document.getElementById('grade').value = grade;
        showToast('Example loaded!', 'success');
    }

    async function generatePlan() {
        const planType = document.getElementById('planType').value;
        const topic = document.getElementById('topic').value.trim();
        const days = document.getElementById('days').value.trim();
        const level = document.getElementById('level').value;
        const grade = document.getElementById('grade').value;

        if (!planType || !topic || !days || !level) {
            showToast('Fill in all the required fields!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Generating...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('plan_type', planType);
            formData.append('topic', topic);
            formData.append('days', days);
            formData.append('level', level);
            formData.append('grade', grade);

            const response = await fetch('generatorepiani.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentPlan = data.result;
                currentTopic = topic;
                document.getElementById('planContent').innerHTML = markdownToHTML(data.result);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(topic, data.result);
                showToast('Plan generated!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyPlan() {
        if (!currentPlan) { showToast('No plan to copy', 'error'); return; }
        navigator.clipboard.writeText(currentPlan).then(() => {
            showToast('Plan copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function speakPlan() {
        if (!currentPlan) { showToast('No plan to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentPlan);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadPlan() {
        if (!currentPlan) { showToast('No plan to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Plan - Personalized Plan\nDate: ' + date + '\nGoal: ' + currentTopic + '\n\n' + currentPlan;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmeplan_' + currentTopic.replace(/\s+/g, '_') + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Plan downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(topic, plan) {
        let history = loadHistory();
        history = history.filter(h => h.topic !== topic);
        history.unshift({
            topic: topic,
            plan: plan,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No plans saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(item.topic) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentPlan = history[index].plan;
            currentTopic = history[index].topic;
            document.getElementById('topic').value = history[index].topic;
            document.getElementById('planContent').innerHTML = markdownToHTML(history[index].plan);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Plan loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole plan history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

