<script>
    let currentMap = '';
    let currentTopic = '';
    let currentMapType = '';
    let selectedMapType = 'albero';
    const HISTORY_KEY = 'workmemind_history';
    const MAX_HISTORY = 5;

    const typeNames = {
        'albero': '<?= t('Tree') ?>',
        'ragno': '<?= t('Spider') ?>',
        'flusso': '<?= t('Flow') ?>'
    };

    function selectMapType(type) {
        selectedMapType = type;
        document.querySelectorAll('.map-type-card').forEach(c => c.classList.remove('selected'));
        document.querySelector('.map-type-card[data-type="' + type + '"]').classList.add('selected');
    }

    function setTopic(topic) {
        document.getElementById('topicInput').value = topic;
        document.getElementById('topicInput').focus();
    }

    async function generateMap() {
        const topic = document.getElementById('topicInput').value.trim();
        if (!topic) {
            showToast('Write a topic!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Generating...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('topic', topic);
            formData.append('map_type', selectedMapType);

            const response = await fetch('mappaidee.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentMap = data.result;
                currentTopic = data.topic;
                currentMapType = data.map_type;
                renderMap(data.result, data.topic, data.map_type);
                saveToHistory(data.result, data.topic, data.map_type);
                showToast('Map generated!', 'success');
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function renderMap(map, topic, mapType) {
        document.getElementById('mapTopic').textContent = topic;
        const badge = document.getElementById('mapTypeBadge');
        badge.textContent = typeNames[mapType] || '<?= t('Tree') ?>';
        badge.className = 'type-badge ' + mapType;

        const box = document.getElementById('mapContent');
        box.className = 'map-box ' + mapType;
        box.textContent = map;

        document.getElementById('resultWrapper').classList.add('active');
        document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function copyMap() {
        if (!currentMap) { showToast('No map to copy', 'error'); return; }
        navigator.clipboard.writeText(currentMap).then(() => {
            showToast('Map copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function downloadMap() {
        if (!currentMap) { showToast('No map to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Mind - Mind Map\nDate: ' + date + '\nTopic: ' + currentTopic + '\nType: ' + typeNames[currentMapType] + '\n\n=== MAP ===\n\n' + currentMap;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmemind_' + currentTopic.replace(/\s+/g, '_') + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Map downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(map, topic, mapType) {
        let history = loadHistory();
        history = history.filter(h => !(h.topic === topic && h.mapType === mapType));
        history.unshift({
            map: map,
            topic: topic,
            mapType: mapType,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No maps saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const icons = { albero: '<i data-i=tree class=ic></i>', ragno: '<i data-i=spider class=ic></i>', flusso: '<i data-i=droplet class=ic></i>' };
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div style="font-size: 22px;">' + (icons[item.mapType] || '<i data-i=tree class=ic></i>') + '</div>' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(item.topic) + '</div>' +
                        '<div class="history-item-date">' + typeNames[item.mapType] + ' · ' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentMap = history[index].map;
            currentTopic = history[index].topic;
            currentMapType = history[index].mapType;
            renderMap(history[index].map, history[index].topic, history[index].mapType);
            showToast('Map loaded from history', 'success');
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole map history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

