    box-shadow:
        0 20px 50px rgba(212, 170, 87,0.5),
        0 0 80px rgba(200, 127, 42,0.3),
        inset 0 -6px 0 rgba(0,0,0,0.2);
}
.btn-tap:active {
    transform: translateY(2px);
    box-shadow:
        0 8px 20px rgba(212, 170, 87,0.3),
        0 0 40px rgba(200, 127, 42,0.15),
        inset 0 -2px 0 rgba(0,0,0,0.2);
}
.btn-tap.glow-on { animation: tapGlow 0.3s ease; }
@keyframes tapGlow {
    0% { filter: brightness(1); }
    50% { filter: brightness(1.4); }
    100% { filter: brightness(1); }
}
.counter-wrap {
    margin-top: 40px;
    position: relative;
    z-index: 2;
}
.counter {
    font-family: var(--font-title);
    font-size: 5em;
    font-weight: 700;
    background: var(--gradient-full);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1;
    transition: transform 0.15s ease;
    display: inline-block;
}
.counter.bump { animation: counterBump 0.2s ease; }
@keyframes counterBump {
    0% { transform: scale(1); }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); }
}
.counter-label {
    color: var(--text-light);
    font-size: 14px;
    margin-top: 8px;
    font-weight: 500;
    letter-spacing: 1px;
    text-transform: uppercase;
}
.rank-box {
    margin-top: 24px;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 12px 24px;
    background: rgba(212,175,55,0.08);
    border: 1px solid rgba(212,175,55,0.25);
    border-radius: 24px;
    font-family: var(--font-title);
    font-weight: 700;
    font-size: 1.1em;
    color: var(--yellow);
    position: relative;
    z-index: 2;
    transition: all 0.3s;
}
.rank-box .rank-icon { width: 28px; height: 28px; display: inline-flex; }
.rank-box .rank-icon svg { width: 100%; height: 100%; }
.message-box {
    margin-top: 20px;
    font-size: 1.1em;
    font-weight: 600;
    color: var(--pink);
    min-height: 30px;
    text-align: center;
    transition: all 0.3s;
    position: relative;
    z-index: 2;
}
.message-box.fade { animation: msgFade 0.4s ease; }
@keyframes msgFade {
    0% { opacity: 0; transform: translateY(10px); }
    100% { opacity: 1; transform: translateY(0); }
}
.particle {
    position: fixed;
    pointer-events: none;
    width: 20px;
    height: 20px;
    z-index: 100;
    animation: particleFly 1s ease-out forwards;
    will-change: transform, opacity;
}
.particle svg { width: 100%; height: 100%; }
@keyframes particleFly {
    0% { transform: translate(0, 0) scale(1) rotate(0deg); opacity: 1; }
    100% { transform: translate(var(--dx), var(--dy)) scale(0.3) rotate(var(--rot)); opacity: 0; }
}
.achievements-section {
    margin-top: 40px;
    padding-top: 30px;
    border-top: 1px solid var(--border);
}
.achievements-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    flex-wrap: wrap;
    gap: 12px;
}
.achievements-header h3 {
    font-family: var(--font-title);
    font-size: 1.3em;
    font-weight: 700;
    color: var(--text-light);
    display: flex;
    align-items: center;
    gap: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.achievements-header h3 svg {
    width: 20px; height: 20px;
    stroke: var(--yellow);
}
.achievements-progress {
    font-size: 13px;
    color: var(--text-muted);
    font-weight: 600;
}
.achievements-progress strong {
    color: var(--yellow);
    font-family: var(--font-title);
}
.achievements-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 12px;
}
.achievement {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 18px 16px;
    text-align: center;
    transition: all 0.3s;
    position: relative;
    overflow: hidden;
}
.achievement::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--gradient-primary);
    transform: scaleX(0);
    transition: transform 0.3s;
}
.achievement.unlocked {
    background: rgba(212,175,55,0.05);
    border-color: rgba(212,175,55,0.3);
}
.achievement.unlocked::before { transform: scaleX(1); }
.achievement.unlocked:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 25px rgba(212,175,55,0.15);
}
.achievement .ach-icon {
    width: 34px;
    height: 34px;
    margin-bottom: 8px;
    display: block;
    filter: grayscale(1) opacity(0.3);
    transition: filter 0.3s;
}
.achievement .ach-icon svg { width: 100%; height: 100%; }
.achievement.unlocked .ach-icon { filter: none; }
.achievement .ach-title {
    font-family: var(--font-title);
    font-size: 13.5px;
    font-weight: 700;
    color: var(--text-muted);
    margin-bottom: 4px;
    transition: color 0.3s;
}
.achievement.unlocked .ach-title { color: #fff; }
.achievement .ach-desc {
    font-size: 11px;
    color: var(--text-muted);
    line-height: 1.4;
}
.achievement .ach-required {
    font-family: var(--font-title);
    font-size: 10.5px;
    font-weight: 700;
    color: var(--yellow);
    margin-top: 6px;
    letter-spacing: 0.5px;
}
.stats-section {
    margin-top: 40px;
    padding-top: 30px;
    border-top: 1px solid var(--border);
}
.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
}
.stat-mini {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 18px 16px;
    text-align: center;
}
.stat-mini .stat-mini-num {
    font-family: var(--font-title);
    font-size: 1.8em;
    font-weight: 700;
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1.1;
}
.stat-mini .stat-mini-lbl {
    color: var(--text-light);
    font-size: 11.5px;
    margin-top: 4px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.btn-reset {
    margin-top: 30px;
    padding: 12px 24px;
    background: rgba(232,97,75,0.08);
    border: 1px solid rgba(232,97,75,0.25);
    border-radius: 12px;
    color: var(--pink);
    font-family: var(--font-body);
    font-size: 13.5px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}
.btn-reset:hover {
    background: rgba(232,97,75,0.15);
    transform: translateY(-2px);
}
.btn-reset svg { width: 16px; height: 16px; }
.toast.achievement { border-left: 4px solid var(--yellow); }
@media (max-width: 768px) {
    .btn-tap { padding: 24px 40px; font-size: 1.3em; }
    .counter { font-size: 3.5em; }
}
@media (max-width: 480px) {
    .btn-tap { padding: 20px 32px; font-size: 1.1em; }
    .counter { font-size: 3em; }
    .achievements-grid { grid-template-columns: repeat(2, 1fr); gap: 8px; }
}
';

lux_header();
