        { threshold: 25, icon: '<i data-i=strength class=ic></i>', title: 'Clicker' },
        { threshold: 50, icon: '<i data-i=flame class=ic></i>', title: 'Enthusiast' },
        { threshold: 100, icon: '<i data-i=bolt class=ic></i>', title: 'Fanatic' },
        { threshold: 250, icon: '<i data-i=spiral class=ic></i>', title: 'Obsessed' },
        { threshold: 500, icon: '<i data-i=trophy class=ic></i>', title: 'Champion' },
        { threshold: 1000, icon: '<i data-i=crown class=ic></i>', title: 'Legend' },
        { threshold: 2500, icon: '<i data-i=star-solid class=ic></i>', title: 'Myth' },
        { threshold: 5000, icon: '<i data-i=trident class=ic></i>', title: 'Deity' },
        { threshold: 10000, icon: '<i data-i=infinity class=ic></i>', title: 'Infinity' },
        { threshold: 25000, icon: '<i data-i=rocket class=ic></i>', title: 'Impossible' }
    ];

    // ============================================
    // PROGRESSIVE MESSAGES
    // ============================================
    const MESSAGES = {
        1: 'Nice, you started!',
        5: 'Keep going...',
        10: 'Wow, 10 clicks!',
        25: 'You are on fire!',
        50: 'You are obsessed!',
        100: 'Help, you never stop!',
        200: 'Are you even human?',
        300: 'This is absurd!',
        500: 'WORLD CHAMPION!',
        750: 'Breaking every record!',
        1000: 'YOU ARE THE CLICK GOD!',
        2000: 'I am out of words...',
        5000: 'YOUR DEDICATION IS UNHEARD OF!',
        10000: 'YOU ENTERED THE LEGEND!',
        25000: 'BEYOND ANY HUMAN LIMIT!'
    };

    // ============================================
    // SOUNDS (Web Audio API)
    // ============================================
    let audioCtx = null;
    function playClickSound() {
        try {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.frequency.value = 800 + Math.random() * 400;
            osc.type = 'sine';
            gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.08);
            osc.start(audioCtx.currentTime);
            osc.stop(audioCtx.currentTime + 0.1);
        } catch (e) {}
    }

    function playAchievementSound() {
        try {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            const notes = [523.25, 659.25, 783.99, 1046.5];
            notes.forEach((freq, i) => {
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.frequency.value = freq;
                osc.type = 'sine';
                const startTime = audioCtx.currentTime + i * 0.1;
                gain.gain.setValueAtTime(0.1, startTime);
                gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.3);
                osc.start(startTime);
                osc.stop(startTime + 0.4);
            });
        } catch (e) {}
    }

    // ============================================
    // GLOBAL STATE
    // ============================================
    const STORAGE_KEY = 'workmetap_state';
    let state = {
        total: 0,
        session: 0,
        unlockedAchievements: [],
        bestCPS: 0,
        currentStreak: 0,
        lastClickTime: 0,
        firstClickDate: null
    };
    let clickTimestamps = [];

    function loadState() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                state = { ...state, ...parsed };
            }
        } catch (e) {}
    }

    function saveState() {
        try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        } catch (e) {}
    }

    // ============================================
    // GET CURRENT RANK
    // ============================================
    function getCurrentRank(total) {
        let current = RANKS[0];
        for (const r of RANKS) {
            if (total >= r.threshold) current = r;
            else break;
        }
        return current;
    }

    // ============================================
    // PARTICLES
    // ============================================
    const PARTICLE_EMOJIS = ['<i data-i=sparkles class=ic></i>', '<i data-i=star-solid class=ic></i>', '<i data-i=star-solid class=ic></i>', '<i data-i=orbit class=ic></i>', '<i data-i=bolt class=ic></i>', '<i data-i=flame class=ic></i>', '<i data-i=burst class=ic></i>', '<i data-i=party class=ic></i>', '<i data-i=confetti class=ic></i>', '<i data-i=gem class=ic></i>'];
    function spawnParticles(x, y) {
        const numParticles = 6;
        for (let i = 0; i < numParticles; i++) {
            const p = document.createElement('div');
            p.className = 'particle';
            p.innerHTML = PRESS_ICONS[PARTICLE_EMOJIS[Math.floor(Math.random() * PARTICLE_EMOJIS.length)]] || PARTICLE_EMOJIS[Math.floor(Math.random() * PARTICLE_EMOJIS.length)];
            p.style.left = x + 'px';
            p.style.top = y + 'px';
            const angle = (Math.PI * 2 * i) / numParticles + Math.random() * 0.5;
            const distance = 80 + Math.random() * 100;
            p.style.setProperty('--dx', Math.cos(angle) * distance + 'px');
            p.style.setProperty('--dy', Math.sin(angle) * distance + 'px');
            p.style.setProperty('--rot', (Math.random() * 720 - 360) + 'deg');
            p.style.fontSize = (14 + Math.random() * 14) + 'px';
            document.body.appendChild(p);
            setTimeout(() => p.remove(), 1000);
        }
    }

    // ============================================
    // PRESS BUTTON
    // ============================================
    function pressButton(event) {
        state.total++;
        state.session++;

        const now = Date.now();
        state.lastClickTime = now;
        if (!state.firstClickDate) state.firstClickDate = new Date().toISOString();

        if (now - (state.lastClickTime - 5000) < 5000) {
            state.currentStreak = Math.max(state.currentStreak, 1);
        }

        clickTimestamps.push(now);
        clickTimestamps = clickTimestamps.filter(t => now - t < 1000);
        const cps = clickTimestamps.length;
        if (cps > state.bestCPS) state.bestCPS = cps;

        playClickSound();

        const rect = event.currentTarget.getBoundingClientRect();
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        spawnParticles(cx, cy);

        const counter = document.getElementById('counter');
        counter.textContent = state.total.toLocaleString();
        counter.classList.add('bump');
        setTimeout(() => counter.classList.remove('bump'), 200);

        const btn = document.getElementById('tapBtn');
        btn.classList.add('glow-on');
        setTimeout(() => btn.classList.remove('glow-on'), 300);

        checkAchievements();
        updateRank();
        updateMessage(state.total);
        updateStats();
        saveState();
    }

    // ============================================
    // CHECK ACHIEVEMENTS
    // ============================================
    function checkAchievements() {
        let newUnlocked = false;
        ACHIEVEMENTS.forEach(a => {
            if (state.total >= a.required && !state.unlockedAchievements.includes(a.id)) {
                state.unlockedAchievements.push(a.id);
                newUnlocked = true;
                showToast('Achievement unlocked:' + a.title + '!', 'achievement');
                playAchievementSound();
            }
        });
        if (newUnlocked) {
            renderAchievements();
            updateAchievementsProgress();
        }
    }

    // ============================================
    // RENDER ACHIEVEMENTS
    // ============================================
    function renderAchievements() {
        const grid = document.getElementById('achievementsGrid');
        grid.innerHTML = '';
        ACHIEVEMENTS.forEach(a => {
            const unlocked = state.unlockedAchievements.includes(a.id);
            const div = document.createElement('div');
            div.className = 'achievement' + (unlocked ? ' unlocked' : '');
            div.innerHTML =
                '<span class="ach-icon">' + (PRESS_ICONS[a.icon] || a.icon) + '</span>' +
                '<div class="ach-title">' + a.title + '</div>' +
                '<div class="ach-desc">' + a.desc + '</div>' +
                (unlocked
                    ? '<div class="ach-required"><i data-i=check class=ic></i> UNLOCKED</div>'
                    : '<div class="ach-required">' + a.required.toLocaleString() + ' clicks</div>');
            grid.appendChild(div);
        });
    }

    function updateAchievementsProgress() {
        document.getElementById('achProgress').textContent =
            state.unlockedAchievements.length + '/' + ACHIEVEMENTS.length;
    }

    // ============================================
    // RANK
    // ============================================
    function updateRank() {
        const rank = getCurrentRank(state.total);
        document.getElementById('rankIcon').innerHTML = PRESS_ICONS[rank.icon] || rank.icon;
        document.getElementById('rankTitle').textContent = rank.title;
        document.getElementById('statRank').textContent = rank.title;
    }

    // ============================================
    // PROGRESSIVE MESSAGES
    // ============================================
    let lastMessage = '';
    function updateMessage(total) {
        let msg = '';
        const keys = Object.keys(MESSAGES).map(Number).sort((a, b) => b - a);
        for (const k of keys) {
            if (total >= k) {
                msg = MESSAGES[k];
                break;
            }
        }
        if (msg && msg !== lastMessage) {
            const box = document.getElementById('messageBox');
            box.textContent = msg;
            box.classList.remove('fade');
            void box.offsetWidth;
            box.classList.add('fade');
            lastMessage = msg;
        }
    }

    // ============================================
    // STATISTICS
    // ============================================
    function updateStats() {
        document.getElementById('statTotal').textContent = state.total.toLocaleString();
        document.getElementById('statSession').textContent = state.session.toLocaleString();
        document.getElementById('statCPS').textContent = state.bestCPS;
        document.getElementById('statStreak').textContent = state.currentStreak;

        if (state.firstClickDate) {
            const d = new Date(state.firstClickDate);
            document.getElementById('statStarted').textContent =
                d.toLocaleDateString({ day: '2-digit', month: '2-digit' });
        }
    }

    // ============================================
    // RESET
    // ============================================
    function resetAll() {
        if (!confirm('Are you sure you want to reset EVERYTHING? You will lose clicks, achievements and stats!')) return;
        if (!confirm('Really sure? This action is irreversible!')) return;

        state = {
            total: 0,
            session: 0,
            unlockedAchievements: [],
            bestCPS: 0,
            currentStreak: 0,
            lastClickTime: 0,
            firstClickDate: null
        };
        clickTimestamps = [];
        localStorage.removeItem(STORAGE_KEY);

        document.getElementById('counter').textContent = '0';
        document.getElementById('messageBox').textContent = '';
        lastMessage = '';

        updateRank();
        updateStats();
        renderAchievements();
        updateAchievementsProgress();

        showToast('Everything reset. Back to zero!', 'info');
    }

    // ============================================
    // INIT
    // ============================================
    document.addEventListener('DOMContentLoaded', function() {
        showToast = function(message, type = 'info') {
            let container = document.querySelector('.toast-container');
            if (!container) {
                container = document.createElement('div');
                container.className = 'toast-container';
                document.body.appendChild(container);
            }
            const icons = { success: '<i data-i=check class=ic></i>', error: '<i data-i=close class=ic></i>', info: 'i', achievement: '<i data-i=star-solid class=ic></i>' };
            const toast = document.createElement('div');
            toast.className = 'toast ' + type;
            toast.innerHTML = '<strong>' + (icons[type] || 'i') + '</strong> ' + message;
            container.appendChild(toast);
            setTimeout(() => {
                toast.style.transition = 'opacity 0.3s, transform 0.3s';
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(20px)';
                setTimeout(() => toast.remove(), 300);
            }, 3000);
        };

        loadState();
        document.getElementById('counter').textContent = state.total.toLocaleString();
        updateRank();
        updateStats();
        renderAchievements();
        updateAchievementsProgress();
        if (state.total > 0) {
            const keys = Object.keys(MESSAGES).map(Number).sort((a, b) => b - a);
            for (const k of keys) {
                if (state.total >= k) { lastMessage = MESSAGES[k]; break; }
            }
        }
    });
</script>

