if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate'])) {
    $recipient = trim($_POST['recipient'] ?? '');
    $context = trim($_POST['context'] ?? '');
    $tone = trim($_POST['tone'] ?? '');
    $details = trim($_POST['details'] ?? '');

    if (empty($recipient) || empty($context) || empty($tone)) {
        jsonResponse(['success' => false, 'error' => t('Fill in all required fields!')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei un assistente che scrive email professionali. Usa SOLO testo semplice e paragrafi. NON usare Markdown, NON usare tabelle, NON usare elenchi puntati.';
        $prompt = "Genera un'email professionale per: $recipient. Contesto: $context. Tono: $tone. Dettagli aggiuntivi: $details. Scrivi un'email completa e ben strutturata con: Oggetto, corpo del messaggio, saluti finali e firma. Usa SOLO testo semplice e paragrafi. NON usare Markdown, NON usare tabelle, NON usare elenchi puntati.";
    } else {
        $systemPrompt = 'You are an assistant that writes professional emails. Use ONLY plain text and paragraphs. Do NOT use Markdown, do NOT use tables, do NOT use bullet lists.';
        $prompt = "Generate a professional email for: $recipient. Context: $context. Tone: $tone. Additional details: $details. Write a complete and well-structured email with: Subject, message body, closing greetings and signature. Use ONLY plain text and paragraphs. Do NOT use Markdown, do NOT use tables, do NOT use bullet lists.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 2000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);
    jsonResponse(['success' => true, 'email' => $result['content']]);
}

