<script>
    let currentEmail = '';

    const HISTORY_KEY = 'workmemail_history';
    const MAX_HISTORY = 5;

    async function generateEmail() {
        const recipient = document.getElementById('recipientInput').value.trim();
        const context = document.getElementById('contextInput').value.trim();
        const tone = document.getElementById('toneInput').value;
        const details = document.getElementById('detailsInput').value.trim();

        if (!recipient || !context || !tone) {
            showToast('Fill in recipient, context and tone!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> <?= t('Generating...') ?>';

        document.getElementById('emailPreview').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('recipient', recipient);
            formData.append('context', context);
            formData.append('tone', tone);
            formData.append('details', details);

            const response = await fetch('promailer.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentEmail = data.email;
                document.getElementById('emailContent').textContent = data.email;
                document.getElementById('emailPreview').classList.add('active');
                saveToHistory(data.email, recipient, context);
                showToast('Email generated!', 'success');
                document.getElementById('emailPreview').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyEmail() {
        if (!currentEmail) {
            showToast('No email to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentEmail).then(() => {
            showToast('Email copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadEmail() {
        if (!currentEmail) {
            showToast('No email to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'EMAIL - LUX.Mail\nDate: ' + date + '\n\n' + currentEmail;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmemail_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Email downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(email, recipient, context) {
        let history = loadHistory();
        history = history.filter(h => h.email !== email);
        history.unshift({
            email: email,
            recipient: recipient,
            context: context,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No emails saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(item.recipient) + ' - ' + escapeHtml(item.context) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentEmail = history[index].email;
            document.getElementById('emailContent').textContent = history[index].email;
            document.getElementById('emailPreview').classList.add('active');
            showToast('Email loaded from history', 'success');
            document.getElementById('emailPreview').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the email history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

