<script>
    let selectedLength = 'medio';
    let currentSummary = '';
    let currentOriginalText = '';

    const HISTORY_KEY = 'workmeshort_history';
    const MAX_HISTORY = 5;

    function selectLength(length) {
        selectedLength = length;
        document.querySelectorAll('.length-card').forEach(c => c.classList.remove('selected'));
        document.querySelector('.length-card[data-length="' + length + '"]').classList.add('selected');
    }

    function updateTextStats() {
        const text = document.getElementById('textInput').value;
        const words = text.trim() ? text.trim().split(/\s+/).length : 0;
        const chars = text.length;
        const readTime = Math.max(1, Math.ceil(words / 200));

        document.getElementById('wordCount').textContent = words;
        document.getElementById('charCount').textContent = chars;
        document.getElementById('readTime').textContent = words > 0 ? readTime + ' min' : '0 min';
        document.getElementById('inputCounter').textContent = words + ' words | ' + chars + ' characters';
    }

    document.getElementById('textInput').addEventListener('input', updateTextStats);

    async function summarizeText() {
        const text = document.getElementById('textInput').value.trim();
        if (!text) {
            showToast('Paste a text to summarize!', 'error');
            return;
        }
        if (text.length < 50) {
            showToast('The text is too short to be summarized', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Summarizing...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('summarize', '1');
            formData.append('text', text);
            formData.append('length', selectedLength);

            const response = await fetch('riassumi.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentSummary = data.summary;
                currentOriginalText = text;
                document.getElementById('resultContent').innerHTML = markdownToHTML(data.summary);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(data.summary, text);
                showToast('Summary generated!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copySummary() {
        if (!currentSummary) {
            showToast('No summary to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentSummary).then(() => {
            showToast('Summary copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadSummary() {
        if (!currentSummary) {
            showToast('No summary to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'SUMMARY - LUX.Short\nDate: ' + date + '\nLength: ' + selectedLength + '\n\n' +
                        '=== SUMMARY ===\n\n' + currentSummary + '\n\n' +
                        '=== ORIGINAL TEXT ===\n\n' + currentOriginalText;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmeshort_summary_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Summary downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(summary, originalText) {
        let history = loadHistory();
        history = history.filter(h => h.summary !== summary);
        history.unshift({
            summary: summary,
            originalText: originalText.substring(0, 500),
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No summaries saved</div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.summary.substring(0, 80) + (item.summary.length > 80 ? '...' : '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentSummary = history[index].summary;
            currentOriginalText = history[index].originalText;
            document.getElementById('resultContent').innerHTML = markdownToHTML(history[index].summary);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Summary loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the summaries history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
        updateTextStats();
    });
</script>

