    } else {
        $systemPrompt = "You are a naming and branding expert. Generate creative and memorable names. Respond in English. Use plain text with numbered lists.";
        $prompt = "Generate 10 creative names for: '$context'. Requested style: $styleName. For each name, provide a short explanation of the meaning (1-2 lines). Answer format: numbered (1., 2., 3., etc.) with the name in bold and the explanation below. Use ONLY plain text. Do NOT use tables. Answer in English in a COMPLETE way.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.9, 'max_tokens' => 2000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);
    jsonResponse(['success' => true, 'result' => $result['content']]);
}

