<script>
    let selectedStyle = 'social';
    let currentRewritten = '';
    let currentOriginalText = '';

    const HISTORY_KEY = 'workmerewrite_history';
    const MAX_HISTORY = 5;

    function selectStyle(style) {
        selectedStyle = style;
        document.getElementById('styleSelect').value = style;
        document.querySelectorAll('.suggestion-chip').forEach(c => {
            c.classList.toggle('active', c.getAttribute('onclick').includes("'" + style + "'"));
        });
    }

    document.getElementById('textInput').addEventListener('input', function() {
        document.getElementById('charCounter').textContent = this.value.length + ' characters';
    });

    async function rewriteText() {
        const text = document.getElementById('textInput').value.trim();
        if (!text) {
            showToast('Paste a text to rewrite!', 'error');
            return;
        }
        if (text.length < 50) {
            showToast('The text is too short to rewrite', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Rewriting...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('rewrite', '1');
            formData.append('text', text);
            formData.append('style', selectedStyle);

            const response = await fetch('riscivili.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentRewritten = data.rewritten;
                currentOriginalText = text;
                document.getElementById('resultContent').innerHTML = markdownToHTML(data.rewritten);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(data.rewritten, text);
                showToast('Text rewritten!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyRewritten() {
        if (!currentRewritten) {
            showToast('No rewritten text to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentRewritten).then(() => {
            showToast('Copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadRewritten() {
        if (!currentRewritten) {
            showToast('No rewritten text to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'REWRITE - LUX.Rewrite\nDate: ' + date + '\nStyle: ' + selectedStyle + '\n\n' +
                        '=== REWRITTEN TEXT ===\n\n' + currentRewritten + '\n\n' +
                        '=== ORIGINAL TEXT ===\n\n' + currentOriginalText;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmerewrite_' + selectedStyle + '_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Rewritten text downloaded!', 'success');
    }

    function speakRewritten() {
        if (!currentRewritten) {
            showToast('No rewritten text to read', 'error');
            return;
        }
        if (!('speechSynthesis' in window)) {
            showToast('The reading is not available on this browser', 'error');
            return;
        }
        const utterance = new SpeechSynthesisUtterance(currentRewritten);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        speechSynthesis.cancel();
        speechSynthesis.speak(utterance);
        showToast('Text read aloud', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(rewritten, originalText) {
        let history = loadHistory();
        history = history.filter(h => h.rewritten !== rewritten);
        history.unshift({
            rewritten: rewritten,
            originalText: originalText.substring(0, 500),
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No rewrites saved</div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.rewritten.substring(0, 80) + (item.rewritten.length > 80 ? '...' : '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentRewritten = history[index].rewritten;
            currentOriginalText = history[index].originalText;
            document.getElementById('resultContent').innerHTML = markdownToHTML(history[index].rewritten);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Rewrite loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the rewrites history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
        document.getElementById('textInput').dispatchEvent(new Event('input'));
    });
</script>

