    $level = trim($_POST['level'] ?? '');

    if (empty($concept) || empty($level)) {
        jsonResponse(['success' => false, 'error' => t('Please fill in all fields!')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $levelMap = [
            'bambino' => 'bambino di 8 anni',
            'studente' => 'studente universitario',
            'esperto' => 'esperto del settore',
            'alieno' => 'un alieno che non conosce nulla della Terra'
        ];
        $levelName = $levelMap[$level] ?? $level;
        $systemPrompt = 'Sei un insegnante esperto. Spieghi concetti complessi in modo chiaro, semplice e adattato alla persona che ti ascolta.';
        $prompt = "Spiega il concetto '$concept' a $levelName. Usa un linguaggio appropriato al livello scelto. Usa SOLO testo semplice e paragrafi. NON usare Markdown. Rispondi in modo COMPLETO e chiaro.";
    } else {
        $levelMap = [
            'bambino' => 'an 8-year-old child',
            'studente' => 'a college student',
            'esperto' => 'a domain expert',
            'alieno' => 'an alien that knows nothing about Earth'
        ];
        $levelName = $levelMap[$level] ?? $level;
        $systemPrompt = 'You are an expert teacher. You explain complex concepts clearly, simply and adapted to the person who listens to you.';
        $prompt = "Explain the concept '$concept' to $levelName. Use a language appropriate to the chosen level. Use ONLY plain text and paragraphs. Do NOT use Markdown. Reply completely and clearly.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 2000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);
    jsonResponse(['success' => true, 'explanation' => $result['content'], 'concept' => $concept, 'level' => $level]);
}

