    function selectLevel(level) {
        selectedLevel = level;
        document.querySelectorAll('.level-card').forEach(c => c.classList.remove('selected'));
        document.querySelector('.level-card[data-level="' + level + '"]').classList.add('selected');
        document.getElementById('levelBadge').textContent = levelLabels[level] || level;
    }

    document.getElementById('conceptInput').addEventListener('keydown', function(e) {
        if (e.key === 'Enter') explainConcept();
    });

    async function explainConcept() {
        const concept = document.getElementById('conceptInput').value.trim();
        if (!concept) {
            showToast('Enter a concept to explain!', 'error');
            return;
        }
        if (concept.length < 2) {
            showToast('The concept is too short', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Explaining...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('explain', '1');
            formData.append('concept', concept);
            formData.append('level', selectedLevel);

            const response = await fetch('spiegalo.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentExplanation = data.explanation;
                currentConcept = concept;
                document.getElementById('levelBadge').textContent = levelLabels[selectedLevel] || selectedLevel;
                document.getElementById('explanationBox').innerHTML = markdownToHTML(data.explanation);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(data.explanation, concept);
                showToast('Explanation ready!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyExplanation() {
        if (!currentExplanation) {
            showToast('No explanation to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentExplanation).then(() => {
            showToast('Explanation copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    function downloadExplanation() {
        if (!currentExplanation) {
            showToast('No explanation to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const safeConcept = (currentConcept || 'concept').replace(/[^a-z0-9]+/gi, '_').toLowerCase();
        const content = 'EXPLANATION - LUX.Explain\nDate: ' + date + '\nConcept: ' + currentConcept +
                        '\nLevel: ' + (levelLabels[selectedLevel] || selectedLevel) + '\n\n' + currentExplanation;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmeexplain_' + safeConcept + '_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Explanation downloaded!', 'success');
    }

    function speakExplanation() {
        if (!currentExplanation) {
            showToast('No explanation to read', 'error');
            return;
        }
        if (!('speechSynthesis' in window)) {
            showToast('The reading is not available on this browser', 'error');
            return;
        }
        const utterance = new SpeechSynthesisUtterance(currentExplanation);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        speechSynthesis.cancel();
        speechSynthesis.speak(utterance);
        showToast('Explanation read aloud', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(explanation, concept) {
        let history = loadHistory();
        history = history.filter(h => h.explanation !== explanation);
        history.unshift({
            explanation: explanation,
            concept: concept,
            level: selectedLevel,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No explanations saved</div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = (item.concept || '') + ' - ' + item.explanation.substring(0, 60) +
                            (item.explanation.length > 60 ? '...' : '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentExplanation = history[index].explanation;
            currentConcept = history[index].concept;
            selectedLevel = history[index].level || 'studente';
            document.getElementById('levelBadge').textContent = levelLabels[selectedLevel] || selectedLevel;
            document.getElementById('explanationBox').innerHTML = markdownToHTML(history[index].explanation);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Explanation loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the explanations history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

