function containsBadWord($name) {
    $badWords = [
        'cazzo', 'caz', 'stronzo', 'stronza', 'merda', 'merd', 'puttana', 'puttan',
        'troia', 'vaffanculo', 'vaffa', 'fanculo', 'fottuto', 'fottuta', 'bastardo',
        'bastarda', 'porco', 'porca', 'minchia', 'minchion', 'coglione', 'coglioni',
        'cacca', 'pipi', 'piscio', 'segaiolo', 'segaiola', 'mignotta', 'zoccola',
        'dio', 'gesù', 'gesu', 'cristo', 'madonna', 'dio cane', 'dio porco',
        'dio stronzo', 'dio merda', 'dio bastardo', 'dio puttana', 'cristo cane',
        'cristo porco', 'madonna puttana', 'madonna troia', 'porco dio', 'porca puttana',
        'fuck', 'fucking', 'shit', 'bitch', 'asshole', 'dick', 'cunt', 'whore',
        'bastard', 'motherfucker', 'slut', 'piss', 'damn', 'hell',
        'fascismo', 'fascista', 'nazismo', 'nazista', 'hitler', 'mussolini',
        'dittatore', 'dittatura', 'totalitarismo', 'razzismo', 'razzista',
        'xenofobia', 'xenofobo', 'antisemitismo', 'antisemita', 'olocausto',
        'genocidio', 'supremazia', 'suprematista', 'arianesimo', 'ariano',
        'violenza', 'violent', 'omicidio', 'omicida', 'assassino', 'terrorismo',
        'terrorista', 'strage', 'massacro', 'eccidio',
        'pedofilia', 'pedofilo', 'pedopornografia', 'pornografia minorile',
        'droga', 'cocaina', 'eroina', 'marijuana', 'stupefacenti', 'spaccio',
        'prostituzione', 'prostituta', 'pornografia', 'porno',
    ];
    $nameLower = strtolower($name);
    foreach ($badWords as $badWord) {
        if (strpos($nameLower, $badWord) !== false) return true;
    }
    return false;
}

// === GESTIONE RICHIESTA AI (GENERA QUIZ) ===
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate_quiz'])) {
    $topic = $_POST['topic'] ?? '';
    if (empty($topic)) {
        jsonResponse(['success' => false, 'error' => t('Missing topic')]);
    }
    $topicName = $topicList[$topic]['name'] ?? ucfirst($topic);

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = "Sei un creatore di quiz professionale. Genera 15 domande. SCRIVI TUTTO IN ITALIANO. Le domande devono essere MEDIO-DIFFICILI ma NON impossibili. Le opzioni NON devono avere lettere (A, B, C, D). IMPORTANTE: La risposta corretta deve essere MESCOLATA tra le opzioni, NON sempre la prima. Restituisci SOLO JSON valido.";
        $prompt = "Genera 15 domande di quiz sul tema: $topicName. Scrivi TUTTO IN ITALIANO. Le domande devono essere DIVERSE e VARIE, di difficolta MEDIA/DIFFICILE ma NON impossibili. Se il tema e calcio, usa SOLO calcio maschile. IMPORTANTE: Le opzioni devono essere MESCOLATE, la risposta corretta NON deve essere sempre la prima. Per ogni domanda, fornisci 4 opzioni (senza lettere, solo testo) e indica la risposta corretta con l'indice (0-3). Formato JSON: [{\"question\":\"testo\",\"options\":[\"opzione1\",\"opzione2\",\"opzione3\",\"opzione4\"],\"correct\":indice}]. Restituisci SOLO il JSON, nient'altro. TUTTE LE DOMANDE E LE OPZIONI DEVONO ESSERE IN ITALIANO.";
    } else {
        $systemPrompt = "You are a professional quiz creator. Generate 15 questions. WRITE EVERYTHING IN ENGLISH. The questions must be MEDIUM/DIFFICULT but not impossible. The options must NOT have letters (A, B, C, D). IMPORTANT: The correct answer must be MIXED among the options, NOT always the first one. Return ONLY valid JSON.";
        $prompt = "Generate 15 quiz questions on the topic: $topicName. Write EVERYTHING IN ENGLISH. The questions must be DIFFERENT and VARIED, MEDIUM/DIFFICULT but not impossible. IMPORTANT: The options must be MIXED, the correct answer must NOT always be the first one. For each question provide 4 options (no letters, only text) and indicate the correct answer with its index (0-3). JSON format: [{\"question\":\"text\",\"options\":[\"option1\",\"option2\",\"option3\",\"option4\"],\"correct\":index}]. Return ONLY the JSON, nothing else. ALL QUESTIONS AND OPTIONS MUST BE IN ENGLISH.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 1.0, 'max_tokens' => 4000]);

    if (!$result['success']) {
        jsonResponse(['success' => false, 'error' => $result['error']]);
    }

    $questions = extractJsonFromAI($result['content']);
    if (!is_array($questions) || count($questions) < 15) {
        jsonResponse(['success' => false, 'error' => t('Invalid AI response: generated {n} questions', ['n' => is_array($questions) ? count($questions) : 0])]);
    }

    jsonResponse(['success' => true, 'questions' => $questions]);
}

