if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['save_score'])) {
    $score = intval($_POST['score'] ?? 0);
    $name = trim($_POST['name'] ?? '');
    $topic = trim($_POST['topic'] ?? '');

    if (containsBadWord($name)) {
        jsonResponse([
