    stroke-width: 5;
}
.timer-circle .timer-fg {
    fill: none;
    stroke: var(--yellow);
    stroke-width: 5;
    stroke-linecap: round;
    stroke-dasharray: 188.4;
    stroke-dashoffset: 0;
    transition: stroke-dashoffset 1s linear, stroke 0.3s;
}
.timer-number {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--font-title);
    font-size: 1.3em;
    font-weight: 700;
    color: var(--yellow);
}
.timer-circle.warning .timer-number {
    color: var(--pink);
    animation: timerPulse 1s infinite;
}
@keyframes timerPulse {
    0%, 100% { transform: translate(-50%, -50%) scale(1); }
    50% { transform: translate(-50%, -50%) scale(1.15); }
}

.quiz-question {
    font-family: var(--font-title);
    font-size: 1.35em;
    font-weight: 600;
    margin-bottom: 24px;
    text-align: center;
    line-height: 1.4;
    color: #fff;
    padding: 20px;
    background: rgba(255,255,255,0.02);
    border-radius: 14px;
    border: 1px solid var(--border);
}
.quiz-options { display: grid; gap: 10px; }
.quiz-option {
    padding: 16px 20px;
    background: rgba(255,255,255,0.04);
    border: 2px solid var(--border);
    border-radius: 14px;
    cursor: pointer;
    transition: all 0.2s;
    text-align: left;
    font-size: 15px;
    color: var(--text);
    font-family: var(--font-body);
    font-weight: 500;
    position: relative;
}
.quiz-option:hover {
    border-color: var(--cyan);
    background: rgba(212, 170, 87,0.05);
    transform: translateX(4px);
}
.quiz-option.selected {
    border-color: var(--cyan);
    background: rgba(212, 170, 87,0.1);
}
.quiz-option.correct {
    border-color: var(--green);
    background: rgba(60,207,145,0.15);
    color: var(--green);
}
.quiz-option.wrong {
    border-color: var(--pink);
    background: rgba(232,97,75,0.15);
    color: var(--pink);
}
.quiz-option:disabled { cursor: not-allowed; }

/* Result */
.result-area { display: none; }
.result-area.active { display: block; }
.result-header { text-align: center; margin-bottom: 30px; }
.result-score-big {
    font-family: var(--font-title);
    font-size: 5em;
    font-weight: 700;
    background: var(--gradient-full);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    line-height: 1;
    margin-bottom: 8px;
}
.result-label {
    color: var(--text-light);
    font-size: 1.1em;
    font-weight: 500;
}
.result-emoji { font-size: 3em; margin-bottom: 12px; }
.result-emoji svg { width: 64px; height: 64px; }
.result-details {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 30px;
}
.result-detail {
    background: rgba(255,255,255,0.02);
    border-radius: 12px;
    padding: 14px 18px;
    border-left: 3px solid var(--cyan);
}
.result-detail.correct { border-left-color: var(--green); }
.result-detail.wrong { border-left-color: var(--pink); }
.result-detail .question {
    font-weight: 600;
    margin-bottom: 6px;
    color: #fff;
    font-size: 14px;
}
.result-detail .answer {
    color: var(--text-light);
    font-size: 13px;
    margin-bottom: 2px;
}
.result-detail .answer.correct-answer { color: var(--green); }
.result-detail .answer.wrong-answer { color: var(--pink); }

/* Leaderboard */
.leaderboard {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 20px;
}
.leaderboard h3 {
    font-family: var(--font-title);
    color: var(--purple);
    margin-bottom: 15px;
    font-size: 1.1em;
    display: flex;
    align-items: center;
    gap: 8px;
}
.leaderboard-list { display: flex; flex-direction: column; gap: 6px; }
.leaderboard-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 14px;
    background: rgba(255,255,255,0.02);
    border-radius: 10px;
    font-size: 14px;
    transition: background 0.2s;
}
.leaderboard-item:hover { background: rgba(255,255,255,0.04); }
.leaderboard-item .rank {
    font-weight: 800;
    color: var(--yellow);
    min-width: 32px;
    font-family: var(--font-title);
}
.leaderboard-item .rank.gold { color: #F0CE86; font-size: 1.2em; }
.leaderboard-item .rank.silver { color: #C9C4BA; font-size: 1.15em; }
.leaderboard-item .rank.bronze { color: #D8A93C; font-size: 1.1em; }
.leaderboard-item .name {
    flex: 1;
    margin-left: 10px;
    color: #fff;
    font-weight: 500;
}
.leaderboard-item .score {
    font-weight: 700;
    color: var(--cyan);
    font-family: var(--font-title);
}
.leaderboard-item.me {
    border: 1px solid var(--cyan);
    background: rgba(212, 170, 87,0.05);
}
.leaderboard-empty {
    text-align: center;
    color: var(--text-muted);
    font-size: 13px;
    padding: 20px;
}

/* Leaderboard tabs */
.leaderboard-tab {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 20px;
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--border);
    border-radius: 12px;
    cursor: pointer;
    color: var(--text-light);
    font-weight: 500;
    transition: all 0.2s;
    font-family: var(--font-body);
    white-space: nowrap;
}
.leaderboard-tab:hover { background: rgba(255,255,255,0.06); color: #fff; }
.leaderboard-tab.active {
    background: var(--gradient-primary);
    color: #fff;
    border-color: transparent;
}

@media (max-width: 768px) {
    .content-box { padding: 22px; }
    .topic-select { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .quiz-question { font-size: 1.15em; padding: 16px; }
    .quiz-option { padding: 14px 16px; font-size: 14px; }
    .result-score-big { font-size: 3.5em; }
    .quiz-header { flex-direction: column; align-items: stretch; }
    .timer-wrapper { justify-content: center; }
}
@media (max-width: 480px) {
    .topic-select { grid-template-columns: 1fr 1fr; }
    .timer-circle { width: 60px; height: 60px; }
    .result-score-big { font-size: 3em; }
    .cta-buttons { flex-direction: column; }
    .cta-buttons .btn-primary,
    .cta-buttons .btn-secondary { width: 100%; justify-content: center; }
}
CSS;

