<script>
    // STATO GLOBALE
    let currentTopic = '';
    let currentTopicName = '';
    let currentQuestions = [];
    let currentQuestionIndex = 0;
    let score = 0;
    let timer = 45;
    let timerInterval = null;
    let answerSelected = false;
    let results = [];
    let playerName = '';
    let wantsLeaderboard = false;

    const topicNames = <?= $topicNamesJson ?>;

    // SELEZIONA TEMA
    function selectTopic(topicKey) {
        currentTopic = topicKey;
        currentTopicName = topicNames[topicKey] || topicKey;
        document.querySelectorAll('.topic-card').forEach(c => c.classList.remove('selected'));
        document.querySelector('.topic-card[data-topic="' + topicKey + '"]').classList.add('selected');

        setTimeout(() => {
            document.getElementById('topic-selection').style.display = 'none';
            document.getElementById('rules-section').style.display = 'block';
            document.getElementById('leaderboard-topic-name').textContent = currentTopicName;
        }, 200);
    }

    // VERIFICA ACCETTAZIONE
    function showLeaderboardAndName() {
        const acceptRules = document.getElementById('accept-rules').checked;
        const acceptPrivacy = document.getElementById('accept-privacy').checked;
        if (!acceptRules || !acceptPrivacy) {
            alert('You must accept all the rules to continue!');
            return;
        }
        document.getElementById('rules-section').style.display = 'none';
        document.getElementById('leaderboard-section').style.display = 'block';
        loadLeaderboardPreview();
    }

    // CARICA CLASSIFICA PREVIEW
    async function loadLeaderboardPreview() {
        try {
            const response = await fetch('squizzati.php?topic_leaderboard=' + currentTopic);
            const data = await response.json();
            const list = document.getElementById('leaderboard-list-preview');
            if (data.success && data.leaderboard) {
                const entries = data.leaderboard;
                if (entries.length === 0) {
                    list.innerHTML = '<div class="leaderboard-empty">No scores for this topic yet. Be the first!</div>';
                } else {
                    list.innerHTML = renderLeaderboard(entries.slice(0, 10), '');
                }
            }
        } catch (error) {
            const list = document.getElementById('leaderboard-list-preview');
            list.innerHTML = '<div class="leaderboard-empty">Error loading</div>';
        }
    }

    function renderLeaderboard(entries, myName) {
        let html = '';
        entries.forEach((entry, index) => {
            let rankClass = '';
            let rankText = '#' + (index + 1);
            if (index === 0) { rankClass = 'gold'; rankText = '1°'; }
            else if (index === 1) { rankClass = 'silver'; rankText = '2°'; }
            else if (index === 2) { rankClass = 'bronze'; rankText = '3°'; }
            const isMe = myName && entry.name === myName;
            html += '<div class="leaderboard-item ' + (isMe ? 'me' : '') + '">' +
                '<span class="rank ' + rankClass + '">' + rankText + '</span>' +
                '<span class="name">' + escapeHtml(entry.name) + '</span>' +
                '<span class="score">' + entry.score + '/15</span>' +
            '</div>';
        });
        return html;
    }

    function showNameInput() {
        document.getElementById('name-input-section').style.display = 'block';
    }

    // INIZIA QUIZ
    async function startQuiz() {
        playerName = document.getElementById('player-name').value.trim();
        wantsLeaderboard = true;
        if (document.getElementById('name-input-section').style.display === 'block' && !playerName) {
            alert('Enter your name!');
            return;
        }
        document.getElementById('leaderboard-section').style.display = 'none';
        document.getElementById('quiz-area').classList.add('active');
        document.getElementById('question').textContent = 'Generating questions...';
        document.getElementById('options').innerHTML = '';

        try {
            const formData = new FormData();
            formData.append('generate_quiz', '1');
            formData.append('topic', currentTopic);
            const response = await fetch('squizzati.php', { method: 'POST', body: formData });
            const data = await response.json();
            if (data.success) {
                currentQuestions = data.questions;
                currentQuestionIndex = 0;
                score = 0;
                results = [];
                document.getElementById('progress-total').textContent = currentQuestions.length;
                loadQuestion();
            } else {
                document.getElementById('question').textContent = 'Error: ' + data.error;
            }
        } catch (error) {
            document.getElementById('question').textContent = 'Error: ' + error.message;
        }
    }

    // CARICA DOMANDA
    function loadQuestion() {
        if (currentQuestionIndex >= currentQuestions.length) {
            endQuiz();
            return;
        }
        const q = currentQuestions[currentQuestionIndex];
        document.getElementById('question').textContent = q.question;
        document.getElementById('progress-current').textContent = currentQuestionIndex + 1;
        const percent = Math.round((currentQuestionIndex / currentQuestions.length) * 100);
        document.getElementById('progress-percent').textContent = percent + '%';
        document.getElementById('progress-fill').style.width = percent + '%';

        const optionsDiv = document.getElementById('options');
        optionsDiv.innerHTML = '';
        q.options.forEach((option, index) => {
            const btn = document.createElement('div');
            btn.className = 'quiz-option';
            btn.textContent = option;
            btn.onclick = () => selectAnswer(index);
            optionsDiv.appendChild(btn);
        });

        answerSelected = false;
        timer = 45;
        updateTimerDisplay();
        const timerCircle = document.getElementById('timer-circle');
        timerCircle.classList.remove('warning');

        clearInterval(timerInterval);
        timerInterval = setInterval(() => {
            timer--;
            updateTimerDisplay();
            if (timer <= 10) timerCircle.classList.add('warning');
            if (timer <= 0) {
                clearInterval(timerInterval);
                showCorrectAnswer();
            }
        }, 1000);
    }

    function updateTimerDisplay() {
        document.getElementById('timer-number').textContent = timer;
        const fg = document.getElementById('timer-fg');
        const dasharray = 188.4;
        const offset = dasharray - (timer / 45) * dasharray;
        fg.style.strokeDashoffset = offset;
    }

    // SELEZIONA RISPOSTA
    function selectAnswer(index) {
        if (answerSelected) return;
        answerSelected = true;
        clearInterval(timerInterval);
        const q = currentQuestions[currentQuestionIndex];
        const options = document.querySelectorAll('.quiz-option');
        options.forEach(option => option.style.pointerEvents = 'none');
        const isCorrect = index === q.correct;
        if (isCorrect) {
            score++;
            options[index].classList.add('correct');
        } else {
            options[index].classList.add('wrong');
            options[q.correct].classList.add('correct');
        }
        results.push({
            question: q.question,
            correct: isCorrect,
            userAnswer: q.options[index],
            correctAnswer: q.options[q.correct]
        });
        currentQuestionIndex++;
        setTimeout(loadQuestion, 1400);
    }

    // TEMPO SCADUTO
    function showCorrectAnswer() {
        const q = currentQuestions[currentQuestionIndex];
        const options = document.querySelectorAll('.quiz-option');
        options.forEach(option => option.style.pointerEvents = 'none');
        options[q.correct].classList.add('correct');
        results.push({
            question: q.question,
            correct: false,
            userAnswer: 'Time up',
            correctAnswer: q.options[q.correct]
        });
        currentQuestionIndex++;
        setTimeout(loadQuestion, 1800);
    }

    // FINE QUIZ
    async function endQuiz() {
        clearInterval(timerInterval);
        document.getElementById('quiz-area').classList.remove('active');
        document.getElementById('result-area').classList.add('active');

        const percent = Math.round((score / currentQuestions.length) * 100);
        document.getElementById('progress-percent').textContent = '100%';
        document.getElementById('progress-fill').style.width = '100%';

        document.getElementById('final-score').textContent = score + '/' + currentQuestions.length;

        let emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 14s1.5 2 4 2 4-2 4-2"></path><line x1="9" y1="9" x2="9.01" y2="9"></line><line x1="15" y1="9" x2="15.01" y2="9"></line></svg>';
        let label = 'You can do better!';
        if (percent === 100) { emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 21h8M12 17v4M7 4h10v6a5 5 0 0 1-10 0V4z"></path><path d="M7 6H4a2 2 0 0 0 2 4h1M17 6h3a2 2 0 0 1-2 4h-1"></path></svg>'; label = 'PERFECT! You are a genius!'; }
        else if (percent >= 80) { emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z"></path></svg>'; label = 'Excellent!'; }
        else if (percent >= 60) { emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"></path><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"></path></svg>'; label = 'Good job!'; }
        else if (percent >= 40) { emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="9" y1="9" x2="9.01" y2="9"></line><line x1="15" y1="9" x2="15.01" y2="9"></line><line x1="8" y1="15" x2="16" y2="15"></line></svg>'; label = 'So so...'; }
        else { emoji = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 14s1.5 2 4 2 4-2 4-2"></path><path d="M10 8.5a.5.5 0 0 0-1 0a3 3 0 0 0 6 0a.5.5 0 0 0-1 0"></path></svg>'; label = 'Try again, you can improve!'; }

        document.getElementById('result-emoji').innerHTML = emoji;
        document.getElementById('final-label').textContent = label;
        document.getElementById('final-leaderboard-topic').textContent = currentTopicName;

        const details = document.getElementById('result-details');
        details.innerHTML = '';
        results.forEach((result, index) => {
            const div = document.createElement('div');
            div.className = 'result-detail ' + (result.correct ? 'correct' : 'wrong');
            div.innerHTML =
                '<div class="question">' + (index + 1) + '. ' + escapeHtml(result.question) + '</div>' +
                '<div class="answer ' + (result.correct ? 'correct-answer' : 'wrong-answer') + '">Your answer: ' + escapeHtml(result.userAnswer) + '</div>' +
                '<div class="answer correct-answer">Correct answer: ' + escapeHtml(result.correctAnswer) + '</div>';
            details.appendChild(div);
        });

        if (wantsLeaderboard && playerName) {
            await saveScoreAndLoadLeaderboard();
        } else {
            loadFinalLeaderboard();
        }
    }

    // SALVA PUNTEGGIO
    async function saveScoreAndLoadLeaderboard() {
        const formData = new FormData();
        formData.append('save_score', '1');
        formData.append('score', score);
        formData.append('name', playerName);
        formData.append('topic', currentTopic);
        try {
            const response = await fetch('squizzati.php', { method: 'POST', body: formData });
            const data = await response.json();
            if (data.success) {
                loadFinalLeaderboard();
            } else if (data.error === 'NOME_VIETATO') {
                alert(data.message);
                location.reload();
            }
        } catch (error) {
            console.error('Error saving score:', error);
        }
    }

    // CARICA CLASSIFICA FINALE
    async function loadFinalLeaderboard() {
        try {
            const response = await fetch('squizzati.php?topic_leaderboard=' + currentTopic);
            const data = await response.json();
            const list = document.getElementById('final-leaderboard-list');
            if (data.success && data.leaderboard) {
                const entries = data.leaderboard;
                if (entries.length === 0) {
                    list.innerHTML = '<div class="leaderboard-empty">No scores for this topic.</div>';
                } else {
                    list.innerHTML = renderLeaderboard(entries.slice(0, 10), playerName);
                }
                const userIndex = entries.findIndex(e => e.name === playerName && e.score === score);
                const positionDiv = document.getElementById('final-position');
                if (userIndex >= 0 && userIndex < 10) {
                    positionDiv.textContent = 'Your position: ' + (userIndex + 1) + '° with ' + score + '/15 points';
                } else if (playerName) {
                    positionDiv.textContent = 'You scored ' + score + '/15 points';
                }
            }
        } catch (error) {
            const list = document.getElementById('final-leaderboard-list');
            list.innerHTML = '<div class="leaderboard-empty">Error loading</div>';
        }
    }

    // RIPROVA
    function restartQuiz() {
        location.reload();
    }
</script>

