<script>
    let currentAnswer = '';
    let currentContext = '';
    const HISTORY_KEY = 'workmebot_history';
    const MAX_HISTORY = 5;

    function setExample(context, type) {
        document.getElementById('contextInput').value = context;
        document.getElementById('responseTypeSelect').value = type;
        showToast('Example loaded!', 'success');
    }

    async function generateBotResponse() {
        const context = document.getElementById('contextInput').value.trim();
        const responseType = document.getElementById('responseTypeSelect').value;

        if (!context || !responseType) {
            showToast('Please fill in all fields!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Generating...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('context', context);
            formData.append('response_type', responseType);

            const response = await fetch('workmebot.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentAnswer = data.result;
                currentContext = context.substring(0, 60) + (context.length > 60 ? '...' : '');
                document.getElementById('answerContent').innerHTML = markdownToHTML(data.result);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(context, responseType, data.result);
                showToast('Responses generated!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyAnswer() {
        if (!currentAnswer) { showToast('No response to copy', 'error'); return; }
        navigator.clipboard.writeText(currentAnswer).then(() => {
            showToast('Responses copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function speakAnswer() {
        if (!currentAnswer) { showToast('No response to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentAnswer);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadAnswer() {
        if (!currentAnswer) { showToast('No response to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Bot - Generated Responses\nDate: ' + date + '\n\n' + currentAnswer;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmebot_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Responses downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(context, responseType, answer) {
        let history = loadHistory();
        history = history.filter(h => h.context !== context);
        history.unshift({
            context: context,
            responseType: responseType,
            answer: answer,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No generation saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.context.length > 70 ? item.context.substring(0, 70) + '...' : item.context;
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + escapeHtml(item.responseType) + ' · ' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentAnswer = history[index].answer;
            currentContext = history[index].context;
            document.getElementById('contextInput').value = history[index].context;
            document.getElementById('responseTypeSelect').value = history[index].responseType;
            document.getElementById('answerContent').innerHTML = markdownToHTML(history[index].answer);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Generation loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the generation history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

