<script>
    let currentAnswer = '';
    let currentExpression = '';
    const HISTORY_KEY = 'workmecalc_history';
    const MAX_HISTORY = 5;

    function setExample(expr) {
        document.getElementById('expressionInput').value = expr;
        document.getElementById('expressionInput').focus();
    }

    async function calculate() {
        const expression = document.getElementById('expressionInput').value.trim();

        if (!expression) {
            showToast('Write an expression or problem!', 'error');
            return;
        }

        const btn = document.getElementById('calculateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> <?= t('Calculating...') ?>';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('calculate', '1');
            formData.append('expression', expression);

            const response = await fetch('workmecalc.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentAnswer = data.result;
                currentExpression = expression;
                document.getElementById('answerContent').innerHTML = markdownToHTML(data.result);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(expression, data.result);
                showToast('Calculation complete!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyAnswer() {
        if (!currentAnswer) { showToast('No result to copy', 'error'); return; }
        navigator.clipboard.writeText(currentAnswer).then(() => {
            showToast('Result copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function speakAnswer() {
        if (!currentAnswer) { showToast('No result to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentAnswer);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadAnswer() {
        if (!currentAnswer) { showToast('No result to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Calc - Result\nDate: ' + date + '\n\nExpression:\n' + currentExpression + '\n\nResult:\n' + currentAnswer;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmecalc_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Result downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(expression, answer) {
        let history = loadHistory();
        history = history.filter(h => h.expression !== expression);
        history.unshift({
            expression: expression,
            answer: answer,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No calculations saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.expression.length > 70 ? item.expression.substring(0, 70) + '...' : item.expression;
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentAnswer = history[index].answer;
            currentExpression = history[index].expression;
            document.getElementById('expressionInput').value = history[index].expression;
            document.getElementById('answerContent').innerHTML = markdownToHTML(history[index].answer);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Calculation loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the calculation history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

