        .debate-phase { display: none; }
        .debate-phase.active { display: block; animation: fadeIn 0.4s ease; }

        .suggestions { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 20px; }
        .suggestion-chip {
            padding: 7px 14px;
            background: rgba(255,255,255,0.04);
            border: 1px solid var(--border);
            border-radius: 20px;
            color: var(--text-light);
            font-size: 12.5px;
            cursor: pointer;
            transition: all 0.2s;
            font-family: var(--font-body);
            font-weight: 500;
        }
        .suggestion-chip:hover {
            border-color: var(--purple);
            color: #fff;
            background: rgba(200, 127, 42,0.08);
        }

        .difficulty-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 20px; }
        .difficulty-card {
            padding: 16px 14px;
            background: rgba(255,255,255,0.03);
            border: 2px solid var(--border);
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.2s;
            text-align: center;
        }
        .difficulty-card:hover { border-color: var(--border-hover); transform: translateY(-3px); }
        .difficulty-card.selected {
            border-color: var(--purple);
            background: rgba(200, 127, 42,0.06);
            box-shadow: 0 0 20px rgba(200, 127, 42,0.15);
        }
        .difficulty-card .diff-icon { font-size: 28px; margin-bottom: 8px; display: block; }
        .difficulty-card .diff-title { font-family: var(--font-title); font-size: 14px; font-weight: 700; color: #fff; margin-bottom: 4px; }
        .difficulty-card .diff-desc { font-size: 11.5px; color: var(--text-muted); line-height: 1.4; }
        .difficulty-card.selected .diff-desc { color: var(--text-light); }

        .side-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px; }
        .side-card {
            padding: 18px 16px;
            background: rgba(255,255,255,0.03);
            border: 2px solid var(--border);
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.2s;
            text-align: center;
        }
        .side-card:hover { border-color: var(--border-hover); transform: translateY(-3px); }
        .side-card.selected {
            border-color: var(--cyan);
            background: rgba(212, 170, 87,0.06);
            box-shadow: 0 0 20px rgba(212, 170, 87,0.15);
        }
        .side-card .side-icon { font-size: 32px; margin-bottom: 8px; display: block; }
        .side-card .side-title { font-family: var(--font-title); font-size: 15px; font-weight: 700; color: #fff; margin-bottom: 4px; }
        .side-card .side-desc { font-size: 11.5px; color: var(--text-muted); line-height: 1.4; }
        .side-card.selected .side-desc { color: var(--text-light); }

        /* Debate Header */
        .debate-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 16px;
            flex-wrap: wrap;
            margin-bottom: 20px;
            padding-bottom: 16px;
            border-bottom: 1px solid var(--border);
        }
        .debate-info { display: flex; flex-direction: column; gap: 4px; }
        .debate-info h2 { font-family: var(--font-title); font-size: 1.3em; font-weight: 700; color: #fff; }
        .debate-info p { font-size: 12.5px; color: var(--text-muted); }
        .debate-tags { display: flex; gap: 8px; flex-wrap: wrap; }
        .debate-tag {
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }
        .debate-tag.side { background: rgba(212, 170, 87,0.15); color: var(--cyan); }
        .debate-tag.side.ai { background: rgba(232,97,75,0.15); color: var(--pink); }
        .debate-tag.diff { background: rgba(200, 127, 42,0.15); color: var(--purple); }
        .debate-tag.round { background: rgba(212,175,55,0.15); color: var(--yellow); }

        /* Chat */
        .debate-chat {
            display: flex;
            flex-direction: column;
            gap: 16px;
            margin-bottom: 20px;
            min-height: 200px;
            max-height: 550px;
            overflow-y: auto;
            padding-right: 8px;
        }
        .msg { display: flex; gap: 10px; max-width: 88%; animation: msgIn 0.3s ease; }
        @keyframes msgIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .msg.user { align-self: flex-end; flex-direction: row-reverse; }
        .msg-avatar {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.85em;
            font-weight: 700;
        }
        .msg.user .msg-avatar { background: linear-gradient(135deg, var(--cyan), var(--purple)); }
        .msg.ai .msg-avatar { background: linear-gradient(135deg, var(--pink), var(--orange)); }
        .msg-bubble {
            padding: 12px 16px;
            border-radius: 16px;
            font-size: 14.5px;
            line-height: 1.7;
            word-wrap: break-word;
        }
        .msg.user .msg-bubble {
            background: linear-gradient(135deg, rgba(212, 170, 87,0.12), rgba(200, 127, 42,0.12));
            border: 1px solid rgba(212, 170, 87,0.2);
            color: #fff;
            border-bottom-right-radius: 4px;
        }
        .msg.ai .msg-bubble {
            background: rgba(255,255,255,0.04);
            border: 1px solid var(--border);
            color: var(--text-light);
            border-bottom-left-radius: 4px;
        }
        .msg.ai .msg-bubble strong { color: #fff; }
        .msg.ai .msg-bubble em { color: var(--purple); }

        .typing-indicator { display: flex; gap: 4px; padding: 12px 16px; }
        .typing-dot {
            width: 8px;
            height: 8px;
            background: var(--pink);
            border-radius: 50%;
            animation: typingBounce 1.4s infinite ease-in-out both;
        }
        .typing-dot:nth-child(1) { animation-delay: -0.32s; }
        .typing-dot:nth-child(2) { animation-delay: -0.16s; }
        @keyframes typingBounce {
            0%, 80%, 100% { transform: scale(0.6); opacity: 0.5; }
            40% { transform: scale(1); opacity: 1; }
        }

        .debate-input-area { display: flex; flex-direction: column; gap: 10px; }
        .debate-input-wrapper { display: flex; gap: 10px; align-items: flex-end; }
        .debate-input {
            flex: 1;
            padding: 14px 16px;
            background: rgba(255,255,255,0.04);
            border: 2px solid var(--border);
            border-radius: 12px;
            color: var(--text);
            font-size: 14.5px;
            font-family: var(--font-body);
            outline: none;
            transition: border-color 0.2s, box-shadow 0.2s;
            resize: none;
            min-height: 52px;
            max-height: 150px;
            line-height: 1.5;
        }
        .debate-input:focus { border-color: var(--cyan); box-shadow: 0 0 0 3px rgba(212, 170, 87,0.1); }
        .debate-send-btn {
            padding: 14px 24px;
            background: var(--gradient-primary);
            color: #fff;
            border: none;
            border-radius: 12px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
            display: flex;
            align-items: center;
            gap: 8px;
            font-family: var(--font-body);
            flex-shrink: 0;
            height: 52px;
        }
        .debate-send-btn:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(212, 170, 87,0.3); }
        .debate-send-btn:disabled { opacity: 0.5; cursor: not-allowed; }

        .debate-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 6px; }
        .btn-small svg { width: 14px; height: 14px; }
        .btn-small.danger { background: rgba(232,97,75,0.1); color: var(--pink); border-color: rgba(232,97,75,0.2); }
        .btn-small.danger:hover { background: rgba(232,97,75,0.2); }

        /* Evaluation */
        .evaluation-box {
            background: rgba(212,175,55,0.04);
            border: 1px solid rgba(212,175,55,0.15);
            border-left: 4px solid var(--yellow);
            border-radius: 14px;
            padding: 24px 28px;
            color: var(--text-light);
            font-size: 15px;
            line-height: 1.85;
            margin-top: 20px;
            display: none;
        }
        .evaluation-box.active { display: block; animation: fadeIn 0.4s ease; }
        .evaluation-box h3 { font-family: var(--font-title); color: var(--yellow); margin-bottom: 14px; font-size: 1.2em; display: flex; align-items: center; gap: 10px; }
        .evaluation-box p { margin-bottom: 8px; }
        .evaluation-box strong { color: #fff; }

        @media (max-width: 768px) {
            .hero p { font-size: 1.05em; }
            .content-box { padding: 22px; }
            .difficulty-grid { grid-template-columns: 1fr; }
            .side-grid { grid-template-columns: 1fr; }
            .msg { max-width: 95%; }
            .debate-send-btn span { display: none; }
        }
        @media (max-width: 480px) {
            .toast-container { right: 12px; left: 12px; }
            .toast { min-width: auto; font-size: 13px; padding: 12px 16px; }
        }
CSS;
