<script>
    // ============================================
    // STATO GLOBALE
    // ============================================
    let currentTopic = '';
    let currentDifficulty = 'medium';
    let currentUserSide = 'pro';
    let currentRound = 0;
    let history = [];
    let debateActive = false;
    const MAX_ROUNDS = 5;

    // ============================================
    // SETUP
    // ============================================
    function setTopic(topic) {
        document.getElementById('topicInput').value = topic;
        document.getElementById('topicInput').focus();
    }

    function setFromChip(btn) {
        setTopic(btn.dataset.topic);
    }

    function selectDifficulty(diff) {
        currentDifficulty = diff;
        document.querySelectorAll('.difficulty-card').forEach(function(c) { c.classList.remove('selected'); });
        const el = document.querySelector('.difficulty-card[data-diff="' + diff + '"]');
        if (el) el.classList.add('selected');
    }

    function selectSide(side) {
        currentUserSide = side;
        document.querySelectorAll('.side-card').forEach(function(c) { c.classList.remove('selected'); });
        const el = document.querySelector('.side-card[data-side="' + side + '"]');
        if (el) el.classList.add('selected');
    }

    // ============================================
    // AVVIA DIBATTITO
    // ============================================
    async function startDebate() {
        const topic = document.getElementById('topicInput').value.trim();
        if (!topic) {
            showToast('Write a topic for the debate!', 'error');
            return;
        }

        currentTopic = topic;
        currentRound = 1;
        history = [];
        debateActive = true;

        document.getElementById('setupPhase').classList.add('hidden');
        document.getElementById('debatePhase').classList.add('active');
        document.getElementById('debateTopic').textContent = topic;
        document.getElementById('roundNumber').textContent = '1';
        document.getElementById('userSideTag').textContent = 'YOU: ' + currentUserSide.toUpperCase();
        document.getElementById('aiSideTag').textContent = 'AI: ' + (currentUserSide === 'pro' ? 'CONTRO' : 'PRO');
        document.getElementById('diffTag').textContent = currentDifficulty.toUpperCase();
        document.getElementById('debateChat').innerHTML = '';
        document.getElementById('evaluationBox').classList.remove('active');
        document.getElementById('evaluationBox').innerHTML = '';
        document.getElementById('inputArea').style.display = 'flex';

        showTyping();

        try {
            const formData = new FormData();
            formData.append('action', 'start');
            formData.append('topic', topic);
            formData.append('difficulty', currentDifficulty);
            formData.append('user_side', currentUserSide);

            const response = await fetch('workmedebate.php', { method: 'POST', body: formData });
            const data = await response.json();

            removeTyping();

            if (data.success) {
                addMessage('ai', data.reply);
                history.push({ role: 'assistant', content: data.reply });
                document.getElementById('userInput').focus();
            } else {
                showToast('Error:' + data.error, 'error');
                debateActive = false;
            }
        } catch (error) {
            removeTyping();
            showToast('Connection error', 'error');
            debateActive = false;
        }
    }

    // ============================================
    // INVIA ARGOMENTO
    // ============================================
    async function sendArgument() {
        if (!debateActive) return;
        const input = document.getElementById('userInput');
        const message = input.value.trim();
        if (!message) return;

        addMessage('user', message);
        history.push({ role: 'user', content: message });
        input.value = '';
        input.style.height = 'auto';
        document.getElementById('sendBtn').disabled = true;

        showTyping();

        try {
            const formData = new FormData();
            formData.append('action', 'continue');
            formData.append('topic', currentTopic);
            formData.append('difficulty', currentDifficulty);
            formData.append('user_side', currentUserSide);
            formData.append('history', JSON.stringify(history.slice(0, -1)));
            formData.append('user_message', message);
            formData.append('round', currentRound);

            const response = await fetch('workmedebate.php', { method: 'POST', body: formData });
            const data = await response.json();

            removeTyping();

            if (data.success) {
                addMessage('ai', data.reply);
                history.push({ role: 'assistant', content: data.reply });
                currentRound++;
                document.getElementById('roundNumber').textContent = Math.min(currentRound, MAX_ROUNDS);

                if (currentRound > MAX_ROUNDS) {
                    showToast('Last round reached! You can end the debate.', 'info');
                }
                document.getElementById('userInput').focus();
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            removeTyping();
            showToast('Connection error', 'error');
        }

        document.getElementById('sendBtn').disabled = false;
    }

    // ============================================
    // TERMINA E VALUTA
    // ============================================
    async function endDebate() {
        if (!debateActive) return;
        const userMessages = history.filter(function(h) { return h.role === 'user'; });
        if (userMessages.length < 2) {
            showToast('Make at least 2 contributions before ending', 'error');
            return;
        }
        if (!confirm('End the debate and get the evaluation?')) return;

        debateActive = false;
        document.getElementById('inputArea').style.display = 'none';

        const box = document.getElementById('evaluationBox');
        box.innerHTML = '<h3>⏳ Evaluation in progress...</h3><p style="color: var(--text-muted);">The AI judge is analyzing your arguments...</p>';
        box.classList.add('active');

        try {
            const formData = new FormData();
            formData.append('evaluate', '1');
            formData.append('topic', currentTopic);
            formData.append('difficulty', currentDifficulty);
            formData.append('user_side', currentUserSide);
            formData.append('history', JSON.stringify(history));

            const response = await fetch('workmedebate.php', { method: 'POST', body: formData });
            const data = await response.json();

            if (data.success) {
                const html = data.evaluation
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                    .replace(/^\s*-\s(.*$)/gim, '<li>$1</li>')
                    .replace(/\n/g, '<br>');
                box.innerHTML = '<h3><i data-i=trophy class=ic></i> Final Evaluation</h3>' + html;
                saveToHistory();
                showToast('Evaluation completed!', 'success');
                box.scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                box.innerHTML = '<h3><i data-i=alert class=ic></i> Error</h3><p>Unable to complete the evaluation: ' + data.error + '</p>';
            }
        } catch (error) {
            box.innerHTML = '<h3><i data-i=alert class=ic></i> Error</h3><p>Connection error</p>';
        }
    }

    // ============================================
    // RICOMINCIA
    // ============================================
    function abortDebate() {
        if (debateActive && !confirm('Do you really want to restart? The current debate will be lost.')) return;
        debateActive = false;
        currentRound = 0;
        history = [];
        document.getElementById('debatePhase').classList.remove('active');
        document.getElementById('setupPhase').classList.remove('hidden');
        document.getElementById('evaluationBox').classList.remove('active');
        document.getElementById('inputArea').style.display = 'flex';
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    // ============================================
    // STORICO (localStorage)
    // ============================================
    function saveToHistory() {
        try {
            const key = 'workmedebate_history';
            let list = [];
            try { const r = localStorage.getItem(key); list = r ? JSON.parse(r) : []; } catch (e) {}
            list.unshift({
                topic: currentTopic,
                difficulty: currentDifficulty,
                side: currentUserSide,
                rounds: history.filter(function(h) { return h.role === 'user'; }).length,
                date: new Date().toISOString()
            });
            list = list.slice(0, 10);
            localStorage.setItem(key, JSON.stringify(list));
        } catch (e) {}
    }

    // ============================================
    // UI CHAT
    // ============================================
    function addMessage(role, text) {
        const chat = document.getElementById('debateChat');
        const div = document.createElement('div');
        div.className = 'msg ' + role;
        const avatar = role === 'user' ? 'YOU' : 'AI';
        const html = text
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
            .replace(/\*(.*?)\*/g, '<em>$1</em>')
            .replace(/\n/g, '<br>');
        div.innerHTML = '<div class="msg-avatar">' + avatar + '</div><div class="msg-bubble">' + html + '</div>';
        chat.appendChild(div);
        chat.scrollTop = chat.scrollHeight;
    }

    function showTyping() {
        const chat = document.getElementById('debateChat');
        const div = document.createElement('div');
        div.className = 'msg ai';
        div.id = 'typingIndicator';
        div.innerHTML = '<div class="msg-avatar">AI</div><div class="msg-bubble"><div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div></div>';
        chat.appendChild(div);
        chat.scrollTop = chat.scrollHeight;
    }

    function removeTyping() {
        const t = document.getElementById('typingIndicator');
        if (t) t.remove();
    }

    // ============================================
    // AUTO-RESIZE TEXTAREA + ENTER
    // ============================================
    document.addEventListener('DOMContentLoaded', function() {
        const input = document.getElementById('userInput');
        if (input) {
            input.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = Math.min(this.scrollHeight, 150) + 'px';
            });
            input.addEventListener('keydown', function(e) {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendArgument();
                }
            });
        }
    });
</script>

