if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action'])) {
    $action = $_POST['action'];
    $context = trim($_POST['context'] ?? '');

    if (empty($context)) {
        jsonResponse(['success' => false, 'error' => t('Missing context')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $system = 'Sei un coach di produttività esperto. Rispondi in italiano in modo chiaro, motivante e conciso. Usa testo semplice, paragrafi brevi. Non usare tabelle.';
    } else {
        $system = 'You are an expert productivity coach. Answer in English in a clear, motivating and concise way. Use simple text, short paragraphs. Do not use tables.';
    }

    switch ($action) {
        case 'motivation':
            if ($lang === 'it') {
                $prompt = "L'utente sta per iniziare una sessione di focus Pomodoro di 25 minuti. Il suo obiettivo è: '$context'. Scrivigli un breve messaggio motivazionale personalizzato (massimo 3 frasi) per iniziare al meglio. Sii caldo, diretto, incoraggiante.";
            } else {
                $prompt = "The user is about to start a 25-minute Pomodoro focus session. Their goal is: '$context'. Write them a short personalized motivational message (maximum 3 sentences) to start strong. Be warm, direct, encouraging.";
            }
            break;
        case 'microplan':
            if ($lang === 'it') {
                $prompt = "L'utente vuole concentrarsi su: '$context' per 25 minuti. Suggerisci un micro-piano in 3 punti per affrontare questa sessione in modo efficace. Sii specifico e pratico. Massimo 3 punti brevi.";
            } else {
                $prompt = "The user wants to focus on: '$context' for 25 minutes. Suggest a 3-point micro-plan to tackle this session effectively. Be specific and practical. Maximum 3 short points.";
            }
            break;
        case 'report':
            if ($lang === 'it') {
                $prompt = "L'utente ha appena completato una sessione di focus Pomodoro. Obiettivo: '$context'. Scrivigli un breve report (massimo 4 frasi) che: 1) complimenta per il lavoro fatto, 2) dà un consiglio concreto per la prossima sessione, 3) lo motiva a continuare. Sii positivo e specifico.";
            } else {
                $prompt = "The user just completed a Pomodoro focus session. Goal: '$context'. Write them a short report (maximum 4 sentences) that: 1) congratulates them on the work done, 2) gives concrete advice for the next session, 3) motivates them to keep going. Be positive and specific.";
            }
            break;
        case 'break':
            if ($lang === 'it') {
                $prompt = "L'utente è in pausa da una sessione di focus. Il suo prossimo obiettivo sarà: '$context'. Suggerisci una micro-attività di relax di 3-5 minuti (una sola) per ricaricare la mente. Sii specifico (es. respirazione, stretching, occhi chiusi, camminata breve, ecc.). Massimo 3 frasi.";
            } else {
                $prompt = "The user is on a break from a focus session. Their next goal will be: '$context'. Suggest a single 3-5 minute relaxation micro-activity to recharge the mind. Be specific (e.g. breathing, stretching, closed eyes, short walk, etc.). Maximum 3 sentences.";
            }
            break;
        default:
            jsonResponse(['success' => false, 'error' => t('Invalid action')]);
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $system],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.85, 'max_tokens' => 400]);

    if (!$result['success']) {
        jsonResponse(['success' => false, 'error' => $result['error']]);
    }

    jsonResponse(['success' => true, 'text' => $result['content']]);
}

