</main>

<script>
    const STORAGE_KEY = 'workmefocus_stats';
    const HISTORY_KEY = 'workmefocus_history';

    let state = {
        focusDuration: 25,
        shortBreak: 5,
        longBreak: 15,
        currentGoal: '',
        currentPhase: 'focus',
        currentSession: 1,
        secondsLeft: 25 * 60,
        totalSeconds: 25 * 60,
        isRunning: false,
        intervalId: null,
        sessionsCompleted: 0,
        stats: {
            today: 0,
            week: 0,
            total: 0,
            lastDate: null,
            unlockedAchievements: []
        }
    };

    const ACHIEVEMENTS = [
        { id: 'first', icon: '<i data-i=seedling class=ic></i>', title: <?= json_encode(t('First Step')) ?>, desc: <?= json_encode(t('Complete your first session')) ?>, required: 1 },
        { id: 'five', icon: '<i data-i=flame class=ic></i>', title: <?= json_encode(t('On Fire')) ?>, desc: <?= json_encode(t('Complete 5 sessions')) ?>, required: 5 },
        { id: 'ten', icon: '<i data-i=strength class=ic></i>', title: <?= json_encode(t('Determined')) ?>, desc: <?= json_encode(t('Complete 10 sessions')) ?>, required: 10 },
        { id: 'twentyfive', icon: '<i data-i=rocket class=ic></i>', title: <?= json_encode(t('Focused')) ?>, desc: <?= json_encode(t('Complete 25 sessions')) ?>, required: 25 },
        { id: 'fifty', icon: '<i data-i=trophy class=ic></i>', title: <?= json_encode(t('Focus Master')) ?>, desc: <?= json_encode(t('Complete 50 sessions')) ?>, required: 50 },
        { id: 'hundred', icon: '<i data-i=crown class=ic></i>', title: <?= json_encode(t('Legend')) ?>, desc: <?= json_encode(t('Complete 100 sessions')) ?>, required: 100 }
    ];

    function loadStats() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                state.stats = { ...state.stats, ...parsed };
            }
        } catch (e) {}
        const today = new Date().toISOString().slice(0, 10);
        if (state.stats.lastDate !== today) {
            state.stats.today = 0;
            state.stats.lastDate = today;
        }
        saveStats();
    }

    function saveStats() {
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.stats)); } catch (e) {}
    }

    function getWeekCount() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            const history = raw ? JSON.parse(raw) : [];
            const now = Date.now();
            const weekAgo = now - 7 * 24 * 60 * 60 * 1000;
            return history.filter(h => h.timestamp >= weekAgo).length;
        } catch (e) { return 0; }
    }

    function addToHistory(goal) {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            const history = raw ? JSON.parse(raw) : [];
            history.push({
                goal: goal,
                timestamp: Date.now(),
                duration: state.focusDuration
            });
            if (history.length > 500) history.splice(0, history.length - 500);
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function renderAchievements() {
        const grid = document.getElementById('achievementsGrid');
        grid.innerHTML = '';
        ACHIEVEMENTS.forEach(a => {
            const unlocked = state.stats.total >= a.required;
            const div = document.createElement('div');
            div.className = 'achievement' + (unlocked ? ' unlocked' : '');
            div.innerHTML =
                '<span class="ach-icon">' + a.icon + '</span>' +
                '<div class="ach-title">' + a.title + '</div>' +
                '<div class="ach-desc">' + a.desc + '</div>';
            grid.appendChild(div);
        });
        const unlockedCount = ACHIEVEMENTS.filter(a => state.stats.total >= a.required).length;
        document.getElementById('achProgress').textContent = unlockedCount + '/' + ACHIEVEMENTS.length;
    }

    function checkAchievements(oldTotal) {
        ACHIEVEMENTS.forEach(a => {
            if (oldTotal < a.required && state.stats.total >= a.required) {
                showToast('Achievement unlocked:' + a.title + '!', 'achievement');
            }
        });
        renderAchievements();
    }

    function setGoal(text) {
        document.getElementById('goalInput').value = text;
        document.getElementById('goalInput').focus();
    }

    async function fetchAI(action, context) {
        const formData = new FormData();
        formData.append('action', action);
        formData.append('context', context);
        try {
            const response = await fetch('workmefocus.php', { method: 'POST', body: formData });
            const data = await response.json();
            if (data.success) return data.text;
            return 'I could not generate the message. Try again!';
        } catch (e) {
            return 'Connection error. Try again!';
        }
    }

    async function startSession() {
        const goal = document.getElementById('goalInput').value.trim();
        if (!goal) {
            showToast('Write your goal!', 'error');
            return;
        }
        const focusTime = parseInt(document.getElementById('focusTime').value) || 25;
        const shortBreak = parseInt(document.getElementById('shortBreak').value) || 5;
        const longBreak = parseInt(document.getElementById('longBreak').value) || 15;

        state.currentGoal = goal;
        state.focusDuration = focusTime;
        state.shortBreak = shortBreak;
        state.longBreak = longBreak;
        state.currentPhase = 'focus';
        state.currentSession = 1;
        state.sessionsCompleted = 0;
        state.totalSeconds = focusTime * 60;
        state.secondsLeft = focusTime * 60;
        state.isRunning = false;

        document.getElementById('setupPhase').classList.add('hidden');
        document.getElementById('timerPhase').classList.add('active');
        document.getElementById('reportPhase').classList.remove('active');
        document.getElementById('timerPhase').scrollIntoView({ behavior: 'smooth', block: 'start' });

        updateTimerDisplay();
        setPhaseLabel('focus', 1);

        document.getElementById('aiMessage').innerHTML = '<div class="loading-box active" style="padding:0;text-align:left;"><span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0 8px 0 0;vertical-align:middle;"></span><span><?= tjs('The AI is preparing your message...') ?></span></div>';
        document.getElementById('aiAvatar').innerHTML = '<i data-i=bot class=ic></i>'; luxUpgrade(document.getElementById('aiAvatar'));

        const [motivation, microplan] = await Promise.all([
            fetchAI('motivation', goal),
            fetchAI('microplan', goal)
        ]);

        document.getElementById('aiMessage').innerHTML =
            '<strong><?= t('Motivation:') ?></strong> ' + escapeHtml(motivation) +
            '<br><br><strong><?= t('Micro-plan:') ?></strong><br>' + escapeHtml(microplan).replace(/\n/g, '<br>');

        if ('Notification' in window && Notification.permission === 'default') {
            Notification.requestPermission();
        }
    }

    function updateTimerDisplay() {
        const minutes = Math.floor(state.secondsLeft / 60);
        const seconds = state.secondsLeft % 60;
        document.getElementById('timerTime').textContent =
            String(minutes).padStart(2, '0') + ':' + String(seconds).padStart(2, '0');

        const fg = document.getElementById('circleFg');
        const circumference = 2 * Math.PI * 145;
        const progress = state.secondsLeft / state.totalSeconds;
        fg.style.strokeDasharray = circumference;
        fg.style.strokeDashoffset = circumference * (1 - progress);
    }

    function setPhaseLabel(phase, session) {
        const label = document.getElementById('timerLabel');
        const count = document.getElementById('timerSessionCount');
        const wrapper = document.getElementById('timerCircleWrapper');
        const aiBox = document.getElementById('aiMessageBox');

        if (phase === 'focus') {
            label.textContent = 'FOCUS';
            count.textContent = '<?= t('Session') ?> ' + session + ' <?= t('of 4') ?>';
            wrapper.classList.remove('break-mode');
            aiBox.classList.remove('break-mode');
        } else if (phase === 'shortBreak') {
            label.textContent = <?= json_encode(t('SHORT BREAK')) ?>;
            count.textContent = '<?= t('Break of') ?> ' + state.shortBreak + ' min';
            wrapper.classList.add('break-mode');
            aiBox.classList.add('break-mode');
        } else if (phase === 'longBreak') {
            label.textContent = <?= json_encode(t('LONG BREAK')) ?>;
            count.textContent = '<?= t('Break of') ?> ' + state.longBreak + ' min';
            wrapper.classList.add('break-mode');
            aiBox.classList.add('break-mode');
        }
    }

    function toggleTimer() {
        if (state.isRunning) {
            pauseTimer();
        } else {
            playTimer();
        }
    }

    function playTimer() {
        state.isRunning = true;
        document.getElementById('mainBtn').innerHTML =
            '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg><span id="mainBtnText"><?= t('Pause') ?></span>';

        clearInterval(state.intervalId);
        state.intervalId = setInterval(() => {
            state.secondsLeft--;
            if (state.secondsLeft <= 0) {
                clearInterval(state.intervalId);
                handlePhaseComplete();
            }
            updateTimerDisplay();
        }, 1000);
    }

    function pauseTimer() {
        state.isRunning = false;
        clearInterval(state.intervalId);
        document.getElementById('mainBtn').innerHTML =
            '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg><span id="mainBtnText"><?= t('Resume Session') ?></span>';
    }

    function resetTimer() {
        clearInterval(state.intervalId);
        state.isRunning = false;
        state.secondsLeft = state.totalSeconds;
        updateTimerDisplay();
        document.getElementById('mainBtn').innerHTML =
            '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg><span id="mainBtnText"><?= t('Start') ?></span>';
    }

    function skipToNext() {
        clearInterval(state.intervalId);
        state.isRunning = false;
        handlePhaseComplete(true);
    }

    function abortSession() {
        if (!confirm(<?= json_encode(t('Do you really want to interrupt the session? Your progress will be lost.')) ?>)) return;
        clearInterval(state.intervalId);
        state.isRunning = false;
        newSession();
    }

    async function handlePhaseComplete(skipped = false) {
        clearInterval(state.intervalId);
        state.isRunning = false;
        playBell();

        if (state.currentPhase === 'focus') {
            if (!skipped) {
                const oldTotal = state.stats.total;
                state.stats.total++;
                state.stats.today++;
                state.stats.lastDate = new Date().toISOString().slice(0, 10);
                saveStats();
                addToHistory(state.currentGoal);
                checkAchievements(oldTotal);
            }

            state.sessionsCompleted++;

            if (state.currentSession >= 4) {
                showReport();
                return;
            } else {
                state.currentPhase = 'shortBreak';
                state.totalSeconds = state.shortBreak * 60;
                state.secondsLeft = state.shortBreak * 60;
                setPhaseLabel('shortBreak');
                updateTimerDisplay();

                document.getElementById('aiMessage').innerHTML = '<div class="loading-box active" style="padding:0;text-align:left;"><span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0 8px 0 0;vertical-align:middle;"></span><span><?= tjs('The AI is suggesting a break...') ?></span></div>';
                document.getElementById('aiAvatar').innerHTML = '<i data-i=meditate class=ic></i>'; luxUpgrade(document.getElementById('aiAvatar'));
                const breakTip = await fetchAI('break', state.currentGoal);
                document.getElementById('aiMessage').innerHTML = '<strong><?= t('Smart break:') ?></strong> ' + escapeHtml(breakTip).replace(/\n/g, '<br>');

                setTimeout(() => playTimer(), 500);
            }
        } else if (state.currentPhase === 'shortBreak' || state.currentPhase === 'longBreak') {
            state.currentPhase = 'focus';
            state.currentSession++;
            state.totalSeconds = state.focusDuration * 60;
            state.secondsLeft = state.focusDuration * 60;
            setPhaseLabel('focus', state.currentSession);
            updateTimerDisplay();

            document.getElementById('aiMessage').innerHTML = '<strong><?= t('Session') ?> ' + state.currentSession + '</strong> - <?= t('Goal:') ?> ' + escapeHtml(state.currentGoal) + '<br><br>Ready to start again?';
            document.getElementById('aiAvatar').innerHTML = '<i data-i=bot class=ic></i>'; luxUpgrade(document.getElementById('aiAvatar'));

            setTimeout(() => playTimer(), 500);
        }
    }

    async function showReport() {
        document.getElementById('timerPhase').classList.remove('active');
        document.getElementById('reportPhase').classList.add('active');

        document.getElementById('statToday').textContent = state.stats.today;
        document.getElementById('statWeek').textContent = getWeekCount();
        document.getElementById('statTotal').textContent = state.stats.total;

        document.getElementById('reportAiText').innerHTML = '<div class="loading-box active" style="padding:0;text-align:left;"><span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0 8px 0 0;vertical-align:middle;"></span><span><?= tjs('The AI is preparing your report...') ?></span></div>';
        const report = await fetchAI('report', state.currentGoal + ' | Sessions: ' + state.sessionsCompleted);
        document.getElementById('reportAiText').innerHTML = escapeHtml(report).replace(/\n/g, '<br>');

        playBell();
        if ('Notification' in window && Notification.permission === 'granted') {
            new Notification('LUX.Focus', { body: 'You completed the Pomodoro cycle! <i data-i=party class=ic></i>' });
        }
    }

    function newSession() {
        clearInterval(state.intervalId);
        state.isRunning = false;
        document.getElementById('reportPhase').classList.remove('active');
        document.getElementById('setupPhase').classList.remove('hidden');
        document.getElementById('setupPhase').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function resetAllStats() {
        if (!confirm(<?= json_encode(t('Are you sure you want to reset ALL statistics and achievements?')) ?>)) return;
        if (!confirm(<?= json_encode(t('Really sure? This action is irreversible!')) ?>)) return;
        localStorage.removeItem(STORAGE_KEY);
        localStorage.removeItem(HISTORY_KEY);
        state.stats = { today: 0, week: 0, total: 0, lastDate: null, unlockedAchievements: [] };
        loadStats();
        renderAchievements();
        document.getElementById('statToday').textContent = '0';
        document.getElementById('statWeek').textContent = '0';
        document.getElementById('statTotal').textContent = '0';
        showToast('Statistics reset!', 'info');
    }

    let audioCtx = null;
    function playBell() {
        try {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            const notes = [523.25, 659.25, 783.99];
            notes.forEach((freq, i) => {
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.frequency.value = freq;
                osc.type = 'sine';
                const startTime = audioCtx.currentTime + i * 0.15;
                gain.gain.setValueAtTime(0.12, startTime);
                gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.6);
                osc.start(startTime);
                osc.stop(startTime + 0.7);
            });
        } catch (e) {}
    }

    document.addEventListener('DOMContentLoaded', function() {
        loadStats();
        renderAchievements();
    });

    window.addEventListener('beforeunload', function() {
        if (state.intervalId) clearInterval(state.intervalId);
    });
</script>

<?php lux_footer(); ?>
