<script>
    const games = <?= json_encode($gamesJS, JSON_UNESCAPED_UNICODE) ?>;
    const catNames = <?= json_encode($catNames, JSON_UNESCAPED_UNICODE) ?>;
    const S = <?= json_encode($JS, JSON_UNESCAPED_UNICODE) ?>;

    let activeFilter = 'all';
    let searchQuery = '';

    function renderGames() {
        const grid = document.getElementById('games-grid');
        const countEl = document.getElementById('count-visible');

        const filtered = games.filter(g => {
            const matchFilter = activeFilter === 'all' || g.category === activeFilter;
            const matchSearch = searchQuery === '' || g.name.toLowerCase().includes(searchQuery);
            return matchFilter && matchSearch;
        });

        countEl.textContent = filtered.length;

        if (filtered.length === 0) {
            grid.innerHTML = '<div class="empty-games"><p>' + S.noGames + '</p></div>';
            return;
        }

        let html = '';
        filtered.forEach(game => {
            html += `
                <div class="game-card" data-cat="${game.category}" onclick="startGame('${game.id}')">
                    <span class="game-icon">${game.icon}</span>
                    <div class="game-name">${game.name}</div>
                    <div class="game-cat-badge">${catNames[game.category] || game.category}</div>
                </div>
            `;
        });
        grid.innerHTML = html;
    }

    document.querySelectorAll('.filter-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
            this.classList.add('active');
            activeFilter = this.dataset.filter;
            renderGames();
        });
    });

    let searchTimeout;
    document.getElementById('search-games').addEventListener('input', function(e) {
        clearTimeout(searchTimeout);
        searchTimeout = setTimeout(() => {
            searchQuery = e.target.value.toLowerCase().trim();
            renderGames();
        }, 150);
    });

    let currentGame = null;

    function startGame(gameId) {
        currentGame = gameId;
        document.getElementById('game-selection').style.display = 'none';
        document.getElementById('game-area').classList.add('active');

        const game = games.find(g => g.id === gameId);
        document.getElementById('game-title').textContent = game.icon + ' ' + game.name;

        switch(gameId) {
            case 'memory': startMemory(); break;
            case 'memory_emoji': startMemoryEmoji(); break;
            case 'memory_numbers': startMemoryNumbers(); break;
            case 'memory_animals': startMemoryAnimals(); break;
            case 'quiz_cultura': startQuiz('cultura'); break;
            case 'quiz_scienze': startQuiz('scienze'); break;
            case 'quiz_storia': startQuiz('storia'); break;
            case 'quiz_geografia': startQuiz('geografia'); break;
            case 'quiz_cinema': startQuiz('cinema'); break;
            case 'quiz_musica': startQuiz('musica'); break;
            case 'reaction': startReaction(); break;
            case 'reaction_colors': startReactionColors(); break;
            case 'reaction_sequence': startReactionSequence(); break;
            case 'reaction_pattern': startReactionPattern(); break;
            case 'anagram': startAnagram(); break;
            case 'hangman': startHangman(); break;
            case 'word_search': startWordSearch(); break;
            case 'word_infinite': startWordInfinite(); break;
            case 'scrabble': startScrabble(); break;
            case 'math_quick': startMathQuick(); break;
            case 'math_equations': startMathEquations(); break;
            case 'math_fractions': startMathFractions(); break;
            case 'math_tables': startMathTables(); break;
            case 'aim': startAim(); break;
            case 'click_precision': startClickPrecision(); break;
            case 'maze': startMaze(); break;
            case 'balance': startBalance(); break;
            case 'sudoku': startSudoku(); break;
            case 'guess_number': startGuessNumber(); break;
            case 'logic_sequence': startLogicSequence(); break;
            case 'puzzle': startPuzzle(); break;
            case 'chess': startChess(); break;
            case 'pong': startPong(); break;
            case 'snake': startSnake(); break;
            case 'flappy': startFlappy(); break;
            case 'space_invaders': startSpaceInvaders(); break;
            case 'cards_memory': startCardsMemory(); break;
            case 'solitaire': startSolitaire(); break;
            case 'dice': startDice(); break;
            case 'roulette': startRoulette(); break;
            default: document.getElementById('game-content').innerHTML = '<p>' + S.underDev + '</p>';
        }
    }

    function closeGame() {
        document.getElementById('game-area').classList.remove('active');
        document.getElementById('game-selection').style.display = 'block';
        currentGame = null;
        if (typeof pongInterval !== 'undefined' && pongInterval) clearInterval(pongInterval);
        if (typeof snakeInterval !== 'undefined' && snakeInterval) clearInterval(snakeInterval);
        if (typeof flappyInterval !== 'undefined' && flappyInterval) clearInterval(flappyInterval);
    }

    // ============================================
    // GIOCHI: MEMORY (4)
    // ============================================
    let memoryCards = [];
    let memoryFlipped = [];
    let memoryMatched = 0;

    function startMemory() {
        const emojis = ['<i data-i=pizza class=ic></i>', '<i data-i=rocket class=ic></i>', '<i data-i=gamepad class=ic></i>', '<i data-i=rainbow class=ic></i>', '<i data-i=music class=ic></i>', '<i data-i=ball class=ic></i>', '<i data-i=burger class=ic></i>', '<i data-i=palette class=ic></i>'];
        memoryCards = [...emojis, ...emojis].sort(() => Math.random() - 0.5);
        memoryFlipped = [];
        memoryMatched = 0;
        let html = '<div class="game-memory-grid">';
        memoryCards.forEach((emoji, index) => {
            html += `<div class="memory-card" onclick="flipMemory(${index})" id="mem-${index}">?</div>`;
        });
        html += '</div><p class="game-status">' + S.findPairs + '</p>';
        document.getElementById('game-content').innerHTML = html;
    }

    function flipMemory(index) {
        if (memoryFlipped.length >= 2) return;
        if (memoryFlipped.includes(index)) return;
        const card = document.getElementById(`mem-${index}`);
        card.textContent = memoryCards[index];
        card.classList.add('flipped');
        memoryFlipped.push(index);
        if (memoryFlipped.length === 2) setTimeout(checkMemoryMatch, 800);
    }

    function checkMemoryMatch() {
        const [a, b] = memoryFlipped;
        const cardA = document.getElementById(`mem-${a}`);
        const cardB = document.getElementById(`mem-${b}`);
        if (memoryCards[a] === memoryCards[b]) {
            cardA.classList.add('matched');
            cardB.classList.add('matched');
            memoryMatched++;
            if (memoryMatched === memoryCards.length / 2) {
                document.getElementById('game-content').innerHTML += '<div class="game-result"><div class="result-text win">' + S.youWin + '</div></div>';
            }
        } else {
            cardA.textContent = '?';
            cardB.textContent = '?';
            cardA.classList.remove('flipped');
            cardB.classList.remove('flipped');
        }
        memoryFlipped = [];
    }

    function startMemoryEmoji() {
        const emojis = ['<i data-i=smile class=ic></i>', '<i data-i=laugh class=ic></i>', '<i data-i=laugh class=ic></i>', '<i data-i=heart class=ic></i>', '<i data-i=heart class=ic></i>', '<i data-i=flame class=ic></i>', '<i data-i=star-solid class=ic></i>', '<i data-i=rainbow class=ic></i>'];
        memoryCards = [...emojis, ...emojis].sort(() => Math.random() - 0.5);
        memoryFlipped = [];
        memoryMatched = 0;
        let html = '<div class="game-memory-grid">';
        memoryCards.forEach((emoji, index) => {
            html += `<div class="memory-card" onclick="flipMemory(${index})" id="mem-${index}">?</div>`;
        });
        html += '</div><p class="game-status">' + S.findEmojiPairs + '</p>';
        document.getElementById('game-content').innerHTML = html;
    }

    function startMemoryNumbers() {
        const numbers = [1,2,3,4,5,6,7,8];
        memoryCards = [...numbers, ...numbers].sort(() => Math.random() - 0.5);
        memoryFlipped = [];
        memoryMatched = 0;
        let html = '<div class="game-memory-grid">';
        memoryCards.forEach((num, index) => {
            html += `<div class="memory-card" onclick="flipMemory(${index})" id="mem-${index}">?</div>`;
        });
        html += '</div><p class="game-status">' + S.findNumberPairs + '</p>';
        document.getElementById('game-content').innerHTML = html;
    }

    function startMemoryAnimals() {
        const animals = ['<i data-i=dog class=ic></i>','<i data-i=cat class=ic></i>','<i data-i=mouse class=ic></i>','<i data-i=mouse class=ic></i>','<i data-i=rabbit class=ic></i>','<i data-i=fox class=ic></i>','<i data-i=bear class=ic></i>','<i data-i=panda class=ic></i>'];
        memoryCards = [...animals, ...animals].sort(() => Math.random() - 0.5);
        memoryFlipped = [];
        memoryMatched = 0;
        let html = '<div class="game-memory-grid">';
        memoryCards.forEach((animal, index) => {
            html += `<div class="memory-card" onclick="flipMemory(${index})" id="mem-${index}">?</div>`;
        });
        html += '</div><p class="game-status">' + S.findAnimalPairs + '</p>';
        document.getElementById('game-content').innerHTML = html;
