    }

    $signInfo = $zodiacSigns[$sign];
    $signName = workmeHoroscopeLang($signInfo['name'], $workmeLang);
    $element = workmeHoroscopeLang($signInfo['element'], $workmeLang);
    $dates = workmeHoroscopeLang($signInfo['dates'], $workmeLang);

    if ($workmeLang === 'it') {
        $periodMap = [
            'giornaliero' => 'oroscopo giornaliero (per oggi)',
            'settimanale' => 'oroscopo settimanale (per questa settimana)',
            'mensile'     => 'oroscopo mensile (per questo mese)'
        ];
        $periodName = $periodMap[$period] ?? $periodMap['giornaliero'];

        $personalInfo = '';
        if (!empty($name) || !empty($birthdate)) {
            $personalInfo = "\n\nInformazioni personali dell'utente:";
            if (!empty($name)) $personalInfo .= "\n- Nome: $name";
            if (!empty($birthdate)) $personalInfo .= "\n- Data di nascita: $birthdate";
            $personalInfo .= "\nUsa queste info per rendere l'oroscopo più personale e diretto (rivolgiti all'utente per nome se disponibile).";
        }

        $today = date('d/m/Y');

        $systemPrompt = "Sei un astrologo esperto e creativo. Generi oroscopi positivi, ispirazionali e personalizzati. Rispondi SEMPRE in italiano e segui ESATTAMENTE la struttura richiesta.";
        $prompt = "Genera un $periodName per il segno zodiacale $signName (elemento: $element, date: $dates). Data odierna: $today.$personalInfo\n\nStruttura la risposta ESATTAMENTE così (usa questi titoli, uno per riga):\n\n**Frase del Giorno**\n[Una frase breve, ispirazionale e specifica per il segno, max 2 righe]\n\n**Amore**\n[2-3 frasi sull'ambito amoroso]\n\n**Lavoro e Studio**\n[2-3 frasi sull'ambito lavorativo o di studio]\n\n**Salute e Benessere**\n[2-3 frasi su energia e benessere fisico]\n\n**Fortuna**\n[2-3 frasi su opportunità e colpi di fortuna]\n\n**Numero Fortunato**\n[Un numero da 1 a 99]\n\n**Colore del Giorno**\n[Un colore con il suo significato]\n\n**Attenzione**\n[Un avvertimento o una cosa a cui fare attenzione]\n\nRegole:\n- Tono positivo, ispirazionale, mai negativo o catastrofico\n- Sii specifico per il segno $signName\n- Varia il contenuto ad ogni generazione (non essere ripetitivo)\n- Scrivi in italiano, in seconda persona (\"tu\", \"il tuo\", ecc.)\n- Sii poetico ma concreto\n- NON aggiungere altro testo fuori dalla struttura richiesta";
    } else {
        $periodMap = [
            'giornaliero' => 'daily horoscope (for today)',
            'settimanale' => 'weekly horoscope (for this week)',
            'mensile'     => 'monthly horoscope (for this month)'
        ];
        $periodName = $periodMap[$period] ?? $periodMap['giornaliero'];

        $personalInfo = '';
        if (!empty($name) || !empty($birthdate)) {
            $personalInfo = "\n\nPersonal information about the user:";
            if (!empty($name)) $personalInfo .= "\n- Name: $name";
            if (!empty($birthdate)) $personalInfo .= "\n- Birth date: $birthdate";
            $personalInfo .= "\nUse this information to make the horoscope more personal and direct (address the user by name if available).";
        }

        $today = date('d/m/Y');

        $systemPrompt = "You are an expert and creative astrologer. You generate positive, inspirational and personalized horoscopes. Always reply in English and follow EXACTLY the requested structure.";
        $prompt = "Generate a $periodName for the zodiac sign $signName (element: $element, dates: $dates). Today's date: $today.$personalInfo\n\nStructure the response EXACTLY like this (use these titles, one per line):\n\n**Phrase of the Day**\n[A short, inspirational phrase specific to the sign, max 2 lines]\n\n**Love**\n[2-3 sentences about love]\n\n**Work and Study**\n[2-3 sentences about work or study]\n\n**Health and Wellbeing**\n[2-3 sentences about energy and physical wellbeing]\n\n**Luck**\n[2-3 sentences about opportunities and lucky breaks]\n\n**Lucky Number**\n[A number from 1 to 99]\n\n**Color of the Day**\n[A color with its meaning]\n\n**Attention**\n[A warning or something to pay attention to]\n\nRules:\n- Positive, inspirational tone, never negative or catastrophic\n- Be specific to the sign $signName\n- Vary the content with each generation (do not be repetitive)\n- Write in English, in the second person (\"you\", \"your\", etc.)\n- Be poetic but concrete\n- Do NOT add any text outside the requested structure";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.95, 'max_tokens' => 1200]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);
    jsonResponse([
        'success' => true,
        'horoscope' => $result['content'],
        'sign' => $sign,
        'sign_name' => $signName,
        'sign_icon' => $signInfo['icon'],
        'period' => $period
    ]);
}

