<script>
    let currentSign = '';
    let currentPeriod = 'giornaliero';
    let currentHoroscope = '';
    let currentSignName = '';
    let currentSignIcon = '';
    let currentPeriodLabel = '';
    let lastRequest = null;

    const periodLabels = {
        'giornaliero': '<?= t('Daily Horoscope') ?>',
        'settimanale': '<?= t('Weekly Horoscope') ?>',
        'mensile': '<?= t('Monthly Horoscope') ?>'
    };

    function selectSign(sign) {
        currentSign = sign;
        document.querySelectorAll('.zodiac-card').forEach(function(c) { c.classList.remove('selected'); });
        const el = document.querySelector('.zodiac-card[data-sign="' + sign + '"]');
        if (el) el.classList.add('selected');
    }

    function selectPeriod(period) {
        currentPeriod = period;
        document.querySelectorAll('.period-card').forEach(function(c) { c.classList.remove('selected'); });
        const el = document.querySelector('.period-card[data-period="' + period + '"]');
        if (el) el.classList.add('selected');
    }

    async function generateHoroscope() {
        if (!currentSign) {
            showToast('Select your zodiac sign!', 'error');
            return;
        }

        const name = document.getElementById('nameInput').value.trim();
        const birthdate = document.getElementById('birthdateInput').value;

        lastRequest = { sign: currentSign, period: currentPeriod, name: name, birthdate: birthdate };

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:18px;height:18px;border-width:2px;margin:0;"></span> <?= t('Reading the stars...') ?>';

        document.getElementById('setupPhase').classList.add('hidden');
        document.getElementById('resultPhase').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('sign', currentSign);
            formData.append('period', currentPeriod);
            formData.append('name', name);
            formData.append('birthdate', birthdate);

            const response = await fetch('workmehoroscope.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentHoroscope = data.horoscope;
                currentSignName = data.sign_name;
                currentSignIcon = data.sign_icon;
                currentPeriodLabel = periodLabels[data.period] || '<?= t('Horoscope') ?>';
                renderResult();
                showToast('Horoscope generated!', 'success');
            } else {
                showToast('Error:' + data.error, 'error');
                document.getElementById('setupPhase').classList.remove('hidden');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            document.getElementById('setupPhase').classList.remove('hidden');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function renderResult() {
        document.getElementById('resultSignIcon').textContent = currentSignIcon;
        document.getElementById('resultSignName').textContent = currentSignName;
        document.getElementById('resultPeriod').textContent = currentPeriodLabel;
        document.getElementById('horoscopeContent').innerHTML = formatHoroscope(currentHoroscope);
        document.getElementById('resultPhase').classList.add('active');
    }

    function formatHoroscope(text) {
        let html = text
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
        html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
        html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');
        html = html.replace(/\n/g, '<br>');
        return html;
    }

    function copyHoroscope() {
        if (!currentHoroscope) return;
        const text = '<i data-i=orb class=ic></i> ' + currentSignName + ' — ' + currentPeriodLabel + '\n\n' + currentHoroscope + '\n\n— L.U.X. Verse Horoscope';
        navigator.clipboard.writeText(text).then(function() {
