<script>
    let currentAnswer = '';
    let currentJournal = '';
    const HISTORY_KEY = 'workmejournal_history';
    const MAX_HISTORY = 5;

    const journalInput = document.getElementById('journalInput');
    const charCounter = document.getElementById('charCounter');
    const wordCounter = document.getElementById('wordCounter');

    journalInput.addEventListener('input', function() {
        const text = this.value;
        charCounter.textContent = text.length + ' ' + <?= json_encode(t('characters')) ?>;
        const words = text.trim() ? text.trim().split(/\s+/).length : 0;
        wordCounter.textContent = words + ' ' + <?= json_encode(t('words')) ?>;
    });

    function setExample(text) {
        journalInput.value = text;
        journalInput.dispatchEvent(new Event('input'));
        journalInput.focus();
        showToast('Prompt loaded!', 'success');
    }

    async function analyzeJournal() {
        const journal = journalInput.value.trim();

        if (!journal) {
            showToast('Write something in the journal!', 'error');
            return;
        }
        if (journal.length < 20) {
            showToast('Write at least a few sentences!', 'error');
            return;
        }

        const btn = document.getElementById('analyzeBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> <?= t('Analyzing...') ?>';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('analyze', '1');
            formData.append('journal', journal);

            const response = await fetch('workmejournal.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentAnswer = data.analysis;
                currentJournal = journal;
                document.getElementById('answerContent').innerHTML = markdownToHTML(data.analysis);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(journal, data.analysis);
                showToast('Analysis completed!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyAnswer() {
        if (!currentAnswer) { showToast('No analysis to copy', 'error'); return; }
        navigator.clipboard.writeText(currentAnswer).then(() => {
            showToast('Analysis copied!', 'success');
        }).catch(() => showToast('Error copying', 'error'));
    }

    function speakAnswer() {
        if (!currentAnswer) { showToast('No analysis to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentAnswer);
        utterance.lang = '<?= currentLang() === 'it' ? 'it-IT' : 'en-US' ?>';
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadAnswer() {
        if (!currentAnswer) { showToast('No analysis to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = '<?= t('LUX.Journal - Analysis') ?>\n' + '<?= t('Date:') ?>' + date + '\n\n=== THOUGHT ===\n\n' + currentJournal + '\n\n=== ANALYSIS ===\n\n' + currentAnswer;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmejournal_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Analysis downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(journal, answer) {
        let history = loadHistory();
        history = history.filter(h => h.journal !== journal);
        history.unshift({
            journal: journal,
            answer: answer,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No analyses saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.journal.length > 70 ? item.journal.substring(0, 70) + '...' : item.journal;
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentAnswer = history[index].answer;
            currentJournal = history[index].journal;
            journalInput.value = history[index].journal;
            journalInput.dispatchEvent(new Event('input'));
            document.getElementById('answerContent').innerHTML = markdownToHTML(history[index].answer);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Analysis loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all analysis history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

