    color: var(--text-muted);
    font-size: 12px;
    margin-bottom: 8px;
}
.btn-file {
    display: inline-block;
    padding: 8px 14px;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-light);
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    font-family: var(--font-body);
    transition: background 0.15s;
    text-align: center;
}
.btn-file:hover { background: rgba(255,255,255,0.1); color: #fff; }
.btn-file input[type="file"] { display: none; }

.dynamic-row {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 14px;
    margin-bottom: 10px;
    position: relative;
    animation: fadeIn 0.3s ease;
}
.dynamic-row .remove-btn {
    position: absolute;
    top: 8px; right: 8px;
    width: 26px; height: 26px;
    border-radius: 8px;
    background: rgba(232,97,75,0.12);
    color: var(--pink);
    border: 1px solid rgba(232,97,75,0.2);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: 700;
    font-family: var(--font-body);
    transition: background 0.15s;
}
.dynamic-row .remove-btn:hover { background: rgba(232,97,75,0.25); }

.add-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 9px 16px;
    background: rgba(212, 170, 87,0.08);
    border: 1px dashed rgba(212, 170, 87,0.3);
    border-radius: 10px;
    color: var(--cyan);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    font-family: var(--font-body);
    transition: background 0.15s;
    width: 100%;
}
.add-btn:hover { background: rgba(212, 170, 87,0.15); }

.template-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}
.template-option {
    background: rgba(255,255,255,0.03);
    border: 2px solid var(--border);
    border-radius: 12px;
    padding: 14px;
    cursor: pointer;
    transition: all 0.2s;
    text-align: center;
}
.template-option:hover { border-color: var(--border-hover); transform: translateY(-2px); }
.template-option.selected {
    border-color: var(--cyan);
    background: rgba(212, 170, 87,0.06);
}
.template-option .tpl-icon { font-size: 28px; margin-bottom: 6px; display: block; }
.template-option .tpl-name {
    font-family: var(--font-title);
    font-size: 12.5px;
    font-weight: 700;
    color: #fff;
}

.actions-bar {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    position: sticky;
    top: 84px;
    background: rgba(5,5,10,0.9);
    backdrop-filter: blur(12px);
    padding: 14px;
    border-radius: 14px;
    border: 1px solid var(--border);
    z-index: 50;
}
.actions-bar .btn-primary,
.actions-bar .btn-secondary,
.actions-bar .btn-danger {
    flex: 1;
    min-width: 140px;
    width: auto;
    padding: 12px 20px;
}
.btn-danger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 20px;
    border-radius: 12px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    font-family: var(--font-body);
    transition: all 0.2s;
    border: 1px solid rgba(232,97,75,0.2);
    background: rgba(232,97,75,0.12);
    color: var(--pink);
}
.btn-danger:hover { background: rgba(232,97,75,0.2); }
.toast.achievement { border-left: 4px solid var(--yellow); }

.preview-col { position: sticky; top: 84px; }
.preview-wrapper {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 18px;
}
.preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}
.preview-header h3 {
    font-family: var(--font-title);
    font-size: 1em;
    font-weight: 700;
    color: var(--text-light);
    text-transform: uppercase;
    letter-spacing: 1px;
    display: flex;
    align-items: center;
    gap: 8px;
}
.preview-header h3 svg { width: 16px; height: 16px; stroke: var(--text-light); }
.preview-zoom { display: flex; gap: 4px; }
.zoom-btn {
    width: 30px; height: 30px;
    border-radius: 8px;
    background: rgba(255,255,255,0.04);
    border: 1px solid var(--border);
    color: var(--text-light);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-body);
    font-size: 14px;
    font-weight: 700;
    transition: background 0.15s;
}
.zoom-btn:hover { background: rgba(255,255,255,0.1); color: #fff; }
.preview-scroll {
    max-height: 800px;
    overflow-y: auto;
    overflow-x: hidden;
    border-radius: 12px;
    background: #fff;
    padding: 0;
}

.cv-page {
    width: 210mm;
    min-height: 297mm;
    background: #ffffff;
    color: #121417;
    font-family: 'Inter', sans-serif;
    box-sizing: border-box;
    transform-origin: top left;
}
.cv-moderno { display: flex; }
.cv-moderno .cv-sidebar { width: 33%; padding: 30px 22px; color: #fff; box-sizing: border-box; }
.cv-moderno .cv-main { width: 67%; padding: 30px 26px; box-sizing: border-box; }
.cv-moderno .cv-photo {
    width: 130px; height: 130px;
    border-radius: 50%;
    background: rgba(255,255,255,0.15);
    margin: 0 auto 18px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 42px;
    color: rgba(255,255,255,0.7);
    border: 3px solid rgba(255,255,255,0.3);
}
.cv-moderno .cv-photo img { width: 100%; height: 100%; object-fit: cover; }
.cv-moderno .cv-name {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 24px;
    font-weight: 700;
    text-align: center;
    margin-bottom: 4px;
    color: #fff;
}
.cv-moderno .cv-title {
    font-size: 12px;
    text-align: center;
    margin-bottom: 22px;
    opacity: 0.9;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.cv-moderno .sidebar-section { margin-bottom: 22px; }
.cv-moderno .sidebar-section h4 {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 10px;
    padding-bottom: 6px;
    border-bottom: 2px solid rgba(255,255,255,0.25);
    color: #fff;
}
.cv-moderno .contact-item {
    font-size: 11px;
    margin-bottom: 8px;
    line-height: 1.5;
    color: #fff;
    word-break: break-word;
}
.cv-moderno .contact-item strong {
    display: block;
    font-size: 9.5px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 2px;
    letter-spacing: 0.5px;
}
.cv-moderno .skill-tag {
    display: inline-block;
    padding: 3px 9px;
    background: rgba(255,255,255,0.15);
    border-radius: 10px;
    font-size: 10.5px;
    margin: 0 4px 5px 0;
    color: #fff;
}
.cv-moderno .lang-item { font-size: 11px; margin-bottom: 6px; color: #fff; }
.cv-moderno .lang-item strong { font-weight: 600; }
.cv-moderno .lang-item span { opacity: 0.85; }
.cv-moderno .main-section { margin-bottom: 22px; }
.cv-moderno .main-section h3 {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 15px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 12px;
    padding-bottom: 6px;
    border-bottom: 2px solid;
    color: #121417;
}
.cv-moderno .main-section p { font-size: 11.5px; line-height: 1.65; color: #333; }
.cv-moderno .exp-item { margin-bottom: 14px; }
.cv-moderno .exp-item:last-child { margin-bottom: 0; }
.cv-moderno .exp-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 2px;
    flex-wrap: wrap;
    gap: 6px;
}
.cv-moderno .exp-role { font-size: 12.5px; font-weight: 700; color: #121417; }
.cv-moderno .exp-date { font-size: 10px; color: #666; font-weight: 500; }
.cv-moderno .exp-company { font-size: 11.5px; font-weight: 600; margin-bottom: 4px; }
.cv-moderno .exp-desc { font-size: 11px; line-height: 1.6; color: #444; }

.cv-classico { padding: 40px 45px; }
.cv-classico .cv-header {
    text-align: center;
    padding-bottom: 20px;
    border-bottom: 3px solid;
    margin-bottom: 24px;
}
.cv-classico .cv-photo {
    width: 110px; height: 110px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0 auto 14px;
    border: 3px solid;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    background: #EDE9E0;
}
.cv-classico .cv-photo img { width: 100%; height: 100%; object-fit: cover; }
.cv-classico .cv-name {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 28px;
    font-weight: 700;
    color: #121417;
}
.cv-classico .cv-title {
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-top: 4px;
}
.cv-classico .cv-contacts {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 10px 18px;
    margin-top: 12px;
    font-size: 11px;
    color: #444;
}
.cv-classico .main-section { margin-bottom: 20px; }
.cv-classico .main-section h3 {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 10px;
    padding-bottom: 4px;
    border-bottom: 2px solid;
    color: #121417;
}
.cv-classico .main-section p { font-size: 11.5px; line-height: 1.65; color: #333; }
.cv-classico .exp-item { margin-bottom: 14px; }
.cv-classico .exp-item:last-child { margin-bottom: 0; }
.cv-classico .exp-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 2px;
    flex-wrap: wrap;
    gap: 6px;
}
.cv-classico .exp-role { font-size: 12.5px; font-weight: 700; color: #121417; }
.cv-classico .exp-date { font-size: 10px; color: #666; font-weight: 500; }
.cv-classico .exp-company { font-size: 11.5px; font-weight: 600; margin-bottom: 4px; }
.cv-classico .exp-desc { font-size: 11px; line-height: 1.6; color: #444; }
.cv-classico .two-cols {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px;
}
.cv-classico .skill-tag {
    display: inline-block;
    padding: 4px 10px;
    background: #EDE9E0;
    border-radius: 10px;
    font-size: 10.5px;
    margin: 0 5px 5px 0;
    color: #333;
    font-weight: 500;
}
.cv-classico .lang-item { font-size: 11.5px; margin-bottom: 5px; color: #333; }

.achievements-section {
    margin-top: 40px;
    padding-top: 30px;
    border-top: 1px solid var(--border);
}
.achievements-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
    flex-wrap: wrap;
    gap: 12px;
}
.achievements-header h3 {
    font-family: var(--font-title);
    font-size: 1.1em;
    font-weight: 700;
    color: var(--text-light);
    display: flex;
    align-items: center;
    gap: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.achievements-header h3 svg { width: 18px; height: 18px; stroke: var(--yellow); }
.achievements-progress { font-size: 13px; color: var(--text-muted); font-weight: 600; }
.achievements-progress strong { color: var(--yellow); font-family: var(--font-title); }
.achievements-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 10px;
}
.achievement {
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 16px 12px;
    text-align: center;
    transition: all 0.3s;
}
.achievement.unlocked {
    background: rgba(212,175,55,0.05);
    border-color: rgba(212,175,55,0.3);
}
.achievement .ach-icon {
    font-size: 28px;
    margin-bottom: 6px;
    display: block;
    filter: grayscale(1) opacity(0.3);
    transition: filter 0.3s;
}
.achievement.unlocked .ach-icon { filter: none; }
.achievement .ach-title {
    font-family: var(--font-title);
    font-size: 12.5px;
    font-weight: 700;
    color: var(--text-muted);
    margin-bottom: 3px;
}
.achievement.unlocked .ach-title { color: #fff; }
.achievement .ach-desc { font-size: 10.5px; color: var(--text-muted); line-height: 1.3; }

.form-col .info-box {
    background: rgba(212, 170, 87,0.05);
    border-left: 3px solid var(--cyan);
    border-radius: 0 12px 12px 0;
    padding: 14px 18px;
    margin-top: 20px;
    max-width: none;
    margin-left: 0;
    margin-right: 0;
}
.form-col .info-box p { color: var(--text-light); font-size: 12.5px; line-height: 1.6; margin: 0; }
.form-col .info-box strong { color: var(--cyan); }

@media (max-width: 768px) {
    .row { grid-template-columns: 1fr; }
    .actions-bar { position: static; }
}
@media (max-width: 480px) {
    .template-grid { grid-template-columns: 1fr; }
    .cta-buttons .btn-secondary { width: 100%; justify-content: center; }
}
CSS;

lux_header();
