                    <div class="form-card">
                        <h3>
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>
                            <?= t('Languages') ?>
                        </h3>
                        <div id="languagesContainer"></div>
                        <button class="add-btn" onclick="addLanguage()">
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                            <?= t('Add Language') ?>
                        </button>
                    </div>

                    <!-- TEMPLATE -->
                    <div class="form-card">
                        <h3>
                            <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="13.5" cy="6.5" r=".5"></circle><circle cx="17.5" cy="10.5" r=".5"></circle><circle cx="8.5" cy="7.5" r=".5"></circle><circle cx="6.5" cy="12.5" r=".5"></circle><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"></path></svg>
                            <?= t('Style & Color') ?>
                        </h3>
                        <div class="template-grid">
                            <div class="template-option selected" data-template="moderno" onclick="selectTemplate('moderno')">
                                <span class="tpl-icon"><i data-i=sparkles class=ic></i></span>
                                <div class="tpl-name"><?= t('Modern') ?></div>
                            </div>
                            <div class="template-option" data-template="classico" onclick="selectTemplate('classico')">
                                <span class="tpl-icon"><i data-i=scroll class=ic></i></span>
                                <div class="tpl-name"><?= t('Classic') ?></div>
                            </div>
                        </div>
                        <div class="fg" style="margin-top: 14px;">
                            <label><?= t('Accent color') ?></label>
                            <input type="color" id="accentColor" value="#D8A93C" style="height: 44px;" oninput="updatePreview()">
                        </div>
                    </div>

                    <div class="info-box">
                        <p><strong><?= t('Total privacy:') ?></strong> <?= t('your data and photo are never sent to our servers. Everything stays in your browser and the PDF is generated locally.') ?></p>
                    </div>

                </div>

                <!-- COLONNA PREVIEW -->
                <div class="preview-col">
                    <div class="preview-wrapper">
                        <div class="preview-header">
                            <h3>
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path><circle cx="12" cy="12" r="3"></circle></svg>
                                <?= t('Live Preview') ?>
                            </h3>
                            <div class="preview-zoom">
                                <button class="zoom-btn" onclick="changeZoom(-0.1)">−</button>
                                <button class="zoom-btn" onclick="changeZoom(0.1)">+</button>
                            </div>
                        </div>
                        <div class="preview-scroll">
                            <div id="cvPreviewContainer" style="transform-origin: top left;"></div>
                        </div>
                    </div>
                </div>

            </div>

            <!-- ACHIEVEMENTS -->
            <div class="achievements-section">
                <div class="achievements-header">
                    <h3>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="7"></circle><polyline points="8.21 13.89 7 23 12 20 17 23 15.79 13.88"></polyline></svg>
                        <?= t('Achievements') ?>
                    </h3>
                    <div class="achievements-progress">
                        <?= t('Unlocked:') ?> <strong id="achProgress">0/6</strong>
                    </div>
                </div>
                <div class="achievements-grid" id="achievementsGrid"></div>
            </div>

            <!-- CTA -->
            <div class="cta-box">
                <h3><?= t('Discover more tools') ?></h3>
                <p><?= t('Explore all the other tools of the L.U.X. Verse ecosystem.') ?></p>
                <div class="cta-buttons">
                    <a href="../webapp.php" class="btn-secondary">
                        <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7"></rect><rect x="14" y="3" width="7" height="7"></rect><rect x="14" y="14" width="7" height="7"></rect><rect x="3" y="14" width="7" height="7"></rect></svg>
                        <?= t('All Projects') ?>
                    </a>
                    <a href="../promailer.php" class="btn-secondary">
                        <svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"></path><polyline points="22,6 12,13 2,6"></polyline></svg>
                        LUX.Mail
                    </a>
                </div>
            </div>

        </div>
    </section>

</main>

<!-- jsPDF + html2canvas da CDN -->
<script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>

<script>
    // ============================================
    // STATO GLOBALE
    // ============================================
    const DRAFT_KEY = 'workmeresume_draft';
    const ACH_KEY = 'workmeresume_achievements';

    let currentPhoto = null;
    let currentTemplate = 'moderno';
    let currentZoom = 1;

    // ============================================
    // ACHIEVEMENTS
    // ============================================
    const ACHIEVEMENTS = [
        { id: 'first_fill', icon: '<i data-i=note class=ic></i>', title: 'First Step', desc: 'Fill in the basic data' },
        { id: 'exp_added', icon: '<i data-i=brief class=ic></i>', title: 'Professional', desc: 'Add an experience' },
        { id: 'edu_added', icon: '<i data-i=gradcap class=ic></i>', title: 'Scholar', desc: 'Add an education' },
        { id: 'photo_added', icon: '<i data-i=camera class=ic></i>', title: 'CV Face', desc: 'Add a photo' },
        { id: 'skills_added', icon: '<i data-i=bolt class=ic></i>', title: 'Skilled', desc: 'Add 5+ skills' },
        { id: 'pdf_generated', icon: '<i data-i=file class=ic></i>', title: 'Ready to Work', desc: 'Generate your first PDF' }
    ];

    function loadAch() {
        try { const r = localStorage.getItem(ACH_KEY); return r ? JSON.parse(r) : []; } catch (e) { return []; }
    }
    function saveAch(list) {
        try { localStorage.setItem(ACH_KEY, JSON.stringify(list)); } catch (e) {}
    }
    function unlockAch(id) {
        const unlocked = loadAch();
        if (!unlocked.includes(id)) {
            unlocked.push(id);
            saveAch(unlocked);
            const a = ACHIEVEMENTS.find(x => x.id === id);
            if (a) showToast('Achievement:' + a.title + '!', 'achievement');
            renderAch();
        }
    }
    function renderAch() {
        const grid = document.getElementById('achievementsGrid');
        const unlocked = loadAch();
        grid.innerHTML = '';
        ACHIEVEMENTS.forEach(a => {
            const isUnlocked = unlocked.includes(a.id);
            const div = document.createElement('div');
            div.className = 'achievement' + (isUnlocked ? ' unlocked' : '');
            div.innerHTML =
                '<span class="ach-icon">' + a.icon + '</span>' +
                '<div class="ach-title">' + a.title + '</div>' +
                '<div class="ach-desc">' + a.desc + '</div>';
            grid.appendChild(div);
        });
        document.getElementById('achProgress').textContent = unlocked.length + '/' + ACHIEVEMENTS.length;
    }

    // ============================================
    // FOTO
    // ============================================
    document.getElementById('photoInput').addEventListener('change', function(e) {
        const file = e.target.files[0];
        if (!file) return;
        if (!file.type.startsWith('image/')) {
            showToast('Select a valid image', 'error');
            return;
        }
        if (file.size > 5 * 1024 * 1024) {
            showToast('Photo too large (max 5MB)', 'error');
            return;
        }
        const reader = new FileReader();
        reader.onload = function(ev) {
            currentPhoto = ev.target.result;
            const img = document.getElementById('photoImg');
            img.src = currentPhoto;
            img.style.display = 'block';
            document.getElementById('photoPlaceholder').style.display = 'none';
            updatePreview();
            unlockAch('photo_added');
            showToast('Photo uploaded!', 'success');
        };
        reader.readAsDataURL(file);
    });

    function removePhoto() {
        currentPhoto = null;
        document.getElementById('photoImg').style.display = 'none';
        document.getElementById('photoPlaceholder').style.display = 'block';
        document.getElementById('photoInput').value = '';
        updatePreview();
    }

    // ============================================
    // ESPERIENZE DINAMICHE
    // ============================================
    function addExperience(data) {
        data = data || {};
        const container = document.getElementById('experiencesContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        div.innerHTML = `
            <button class="remove-btn" onclick="removeDynamic(this)">×</button>
            <div class="fg"><label>Role</label><input type="text" class="exp-role" placeholder="e.g. Web Developer" value="${data.role || ''}" oninput="updatePreview()"></div>
            <div class="fg"><label>Company</label><input type="text" class="exp-company" placeholder="e.g. L.U.X. Verse" value="${data.company || ''}" oninput="updatePreview()"></div>
            <div class="fg"><label>Period</label><input type="text" class="exp-date" placeholder="e.g. 2023 - Present" value="${data.date || ''}" oninput="updatePreview()"></div>
            <div class="fg"><label>Description</label><textarea class="exp-desc" placeholder="Describe your responsibilities..." oninput="updatePreview()">${data.desc || ''}</textarea></div>
        `;
        container.appendChild(div);
        updatePreview();
        unlockAch('exp_added');
    }

    function addEducation(data) {
        data = data || {};
        const container = document.getElementById('educationContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        div.innerHTML = `
            <button class="remove-btn" onclick="removeDynamic(this)">×</button>
            <div class="fg"><label>Degree</label><input type="text" class="edu-title" placeholder="e.g. IT Diploma" value="${data.title || ''}" oninput="updatePreview()"></div>
            <div class="fg"><label>Institute</label><input type="text" class="edu-institute" placeholder="e.g. Galileo Galilei Institute" value="${data.institute || ''}" oninput="updatePreview()"></div>
            <div class="fg"><label>Period</label><input type="text" class="edu-date" placeholder="e.g. 2020 - 2025" value="${data.date || ''}" oninput="updatePreview()"></div>
        `;
        container.appendChild(div);
        updatePreview();
        unlockAch('edu_added');
    }

    function addLanguage(data) {
        data = data || {};
        const container = document.getElementById('languagesContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        const levels = ['Native', 'C2', 'C1', 'B2', 'B1', 'A2', 'A1'];
        let optionsHtml = '';
        levels.forEach(lv => {
            optionsHtml += '<option value="' + lv + '"' + (data.level === lv ? ' selected' : '') + '>' + lv + '</option>';
        });
        div.innerHTML = `
            <button class="remove-btn" onclick="removeDynamic(this)">×</button>
            <div class="row">
                <div class="fg"><label>Language</label><input type="text" class="lang-name" placeholder="e.g. English" value="${data.name || ''}" oninput="updatePreview()"></div>
                <div class="fg"><label>Level</label><select class="lang-level" onchange="updatePreview()">${optionsHtml}</select></div>
            </div>
        `;
        container.appendChild(div);
        updatePreview();
    }

    function removeDynamic(btn) {
        btn.closest('.dynamic-row').remove();
        updatePreview();
    }

    // ============================================
    // TEMPLATE
    // ============================================
    function selectTemplate(name) {
        currentTemplate = name;
        document.querySelectorAll('.template-option').forEach(el => el.classList.remove('selected'));
        document.querySelector('.template-option[data-template="' + name + '"]').classList.add('selected');
        updatePreview();
    }

    // ============================================
    // ZOOM
    // ============================================
    function changeZoom(delta) {
        if (delta !== 0) {
            currentZoom = Math.max(0.3, Math.min(1.5, currentZoom + delta));
        }
        const container = document.getElementById('cvPreviewContainer');
        container.style.transform = 'scale(' + currentZoom + ')';
    }

    // ============================================
    // AGGIORNA PREVIEW
    // ============================================
    function updatePreview() {
        try {
            const container = document.getElementById('cvPreviewContainer');
            const accent = document.getElementById('accentColor').value;

            const data = {
                firstName: document.getElementById('firstName').value.trim(),
                lastName: document.getElementById('lastName').value.trim(),
                jobTitle: document.getElementById('jobTitle').value.trim(),
                email: document.getElementById('email').value.trim(),
                phone: document.getElementById('phone').value.trim(),
                city: document.getElementById('city').value.trim(),
                website: document.getElementById('website').value.trim(),
                bio: document.getElementById('bio').value.trim(),
                skills: document.getElementById('skills').value.trim(),
                photo: currentPhoto,
                accent: accent
            };

            const experiences = [];
            document.querySelectorAll('#experiencesContainer .dynamic-row').forEach(row => {
                const r = row.querySelector('.exp-role');
                const c = row.querySelector('.exp-company');
                const d = row.querySelector('.exp-date');
                const de = row.querySelector('.exp-desc');
                experiences.push({
                    role: r ? r.value.trim() : '',
                    company: c ? c.value.trim() : '',
                    date: d ? d.value.trim() : '',
                    desc: de ? de.value.trim() : ''
                });
            });

            const educations = [];
            document.querySelectorAll('#educationContainer .dynamic-row').forEach(row => {
                const t = row.querySelector('.edu-title');
                const i = row.querySelector('.edu-institute');
                const d = row.querySelector('.edu-date');
                educations.push({
                    title: t ? t.value.trim() : '',
                    institute: i ? i.value.trim() : '',
                    date: d ? d.value.trim() : ''
                });
            });

            const languages = [];
            document.querySelectorAll('#languagesContainer .dynamic-row').forEach(row => {
                const n = row.querySelector('.lang-name');
                const l = row.querySelector('.lang-level');
                languages.push({
                    name: n ? n.value.trim() : '',
                    level: l ? l.value : 'B1'
                });
            });

            let html = '';
            if (currentTemplate === 'moderno') {
                html = renderModernTemplate(data, experiences, educations, languages);
            } else {
                html = renderClassicTemplate(data, experiences, educations, languages);
            }

            container.innerHTML = html;
            container.style.transform = 'scale(' + currentZoom + ')';
        } catch (e) {
            console.error('updatePreview error:', e);
        }
    }

    // ============================================
    // TEMPLATE MODERNO
    // ============================================
    function renderModernTemplate(data, experiences, educations, languages) {
        const skillsList = data.skills ? data.skills.split(',').map(s => s.trim()).filter(s => s) : [];
        const hasExperiences = experiences.some(e => e.role || e.company);
        const hasEducations = educations.some(e => e.title || e.institute);
        const hasLanguages = languages.some(l => l.name);

        const name = (data.firstName || data.lastName) ? (data.firstName + ' ' + data.lastName).trim() : 'Your Name';
        const title = data.jobTitle || 'Professional Title';

        let html = '<div class="cv-page cv-moderno">';

        html += '<div class="cv-sidebar" style="background: ' + data.accent + ';">';
        html += '<div class="cv-photo">';
        if (data.photo) {
            html += '<img src="' + data.photo + '" alt="">';
        } else {
            html += '<i data-i=user class=ic></i>';
        }
        html += '</div>';
        html += '<div class="cv-name">' + escapeHtml(name) + '</div>';
        html += '<div class="cv-title">' + escapeHtml(title) + '</div>';

        html += '<div class="sidebar-section"><h4>Contact</h4>';
        if (data.email) html += '<div class="contact-item"><strong>Email</strong>' + escapeHtml(data.email) + '</div>';
        if (data.phone) html += '<div class="contact-item"><strong>Phone</strong>' + escapeHtml(data.phone) + '</div>';
        if (data.city) html += '<div class="contact-item"><strong>City</strong>' + escapeHtml(data.city) + '</div>';
        if (data.website) html += '<div class="contact-item"><strong>Web</strong>' + escapeHtml(data.website) + '</div>';
        html += '</div>';

        if (skillsList.length > 0) {
            html += '<div class="sidebar-section"><h4>Skills</h4>';
            skillsList.forEach(s => { html += '<span class="skill-tag">' + escapeHtml(s) + '</span>'; });
            html += '</div>';
        }

        if (hasLanguages) {
            html += '<div class="sidebar-section"><h4>Languages</h4>';
            languages.forEach(l => {
                if (!l.name) return;
                html += '<div class="lang-item"><strong>' + escapeHtml(l.name) + '</strong> <span>· ' + escapeHtml(l.level) + '</span></div>';
            });
            html += '</div>';
        }

        html += '</div>';

        html += '<div class="cv-main">';

        if (data.bio) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Profile</h3>';
            html += '<p>' + nl2br(escapeHtml(data.bio)) + '</p></div>';
        }

        if (hasExperiences) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Work Experience</h3>';
            experiences.forEach(e => {
                if (!e.role && !e.company) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header">';
                html += '<div class="exp-role">' + escapeHtml(e.role || 'Role') + '</div>';
                if (e.date) html += '<div class="exp-date">' + escapeHtml(e.date) + '</div>';
                html += '</div>';
                if (e.company) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + escapeHtml(e.company) + '</div>';
                if (e.desc) html += '<div class="exp-desc">' + nl2br(escapeHtml(e.desc)) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }

        if (hasEducations) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Education</h3>';
            educations.forEach(e => {
                if (!e.title && !e.institute) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header">';
                html += '<div class="exp-role">' + escapeHtml(e.title || 'Title') + '</div>';
                if (e.date) html += '<div class="exp-date">' + escapeHtml(e.date) + '</div>';
                html += '</div>';
                if (e.institute) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + escapeHtml(e.institute) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }

        html += '</div></div>';
        return html;
    }

    // ============================================
    // TEMPLATE CLASSICO
    // ============================================
    function renderClassicTemplate(data, experiences, educations, languages) {
        const skillsList = data.skills ? data.skills.split(',').map(s => s.trim()).filter(s => s) : [];
        const hasExperiences = experiences.some(e => e.role || e.company);
        const hasEducations = educations.some(e => e.title || e.institute);
        const hasLanguages = languages.some(l => l.name);

        const name = (data.firstName || data.lastName) ? (data.firstName + ' ' + data.lastName).trim() : 'Your Name';
        const title = data.jobTitle || 'Professional Title';

        let html = '<div class="cv-page cv-classico">';

        html += '<div class="cv-header" style="border-color: ' + data.accent + ';">';
        if (data.photo) {
            html += '<div class="cv-photo" style="border-color: ' + data.accent + ';"><img src="' + data.photo + '" alt=""></div>';
        }
        html += '<div class="cv-name">' + escapeHtml(name) + '</div>';
        html += '<div class="cv-title" style="color: ' + data.accent + ';">' + escapeHtml(title) + '</div>';

        const contacts = [];
        if (data.email) contacts.push('<i data-i=mail class=ic></i> ' + escapeHtml(data.email));
        if (data.phone) contacts.push('<i data-i=phone class=ic></i> ' + escapeHtml(data.phone));
        if (data.city) contacts.push('<i data-i=pin class=ic></i> ' + escapeHtml(data.city));
        if (data.website) contacts.push('<i data-i=globe class=ic></i> ' + escapeHtml(data.website));
        if (contacts.length > 0) {
            html += '<div class="cv-contacts">';
            contacts.forEach(c => { html += '<span>' + c + '</span>'; });
            html += '</div>';
        }
        html += '</div>';

        html += '<div class="cv-main">';

        if (data.bio) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Profile</h3>';
            html += '<p>' + nl2br(escapeHtml(data.bio)) + '</p></div>';
        }

        if (hasExperiences) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Work Experience</h3>';
            experiences.forEach(e => {
                if (!e.role && !e.company) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header">';
                html += '<div class="exp-role">' + escapeHtml(e.role || 'Role') + '</div>';
                if (e.date) html += '<div class="exp-date">' + escapeHtml(e.date) + '</div>';
                html += '</div>';
                if (e.company) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + escapeHtml(e.company) + '</div>';
                if (e.desc) html += '<div class="exp-desc">' + nl2br(escapeHtml(e.desc)) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }

        if (hasEducations) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Education</h3>';
            educations.forEach(e => {
                if (!e.title && !e.institute) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header">';
                html += '<div class="exp-role">' + escapeHtml(e.title || 'Title') + '</div>';
                if (e.date) html += '<div class="exp-date">' + escapeHtml(e.date) + '</div>';
                html += '</div>';
                if (e.institute) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + escapeHtml(e.institute) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }

        if (skillsList.length > 0 || hasLanguages) {
            html += '<div class="two-cols">';
            if (skillsList.length > 0) {
                html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Skills</h3>';
                skillsList.forEach(s => { html += '<span class="skill-tag">' + escapeHtml(s) + '</span>'; });
                html += '</div>';
            }
            if (hasLanguages) {
                html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';">Languages</h3>';
                languages.forEach(l => {
                    if (!l.name) return;
                    html += '<div class="lang-item"><strong>' + escapeHtml(l.name) + '</strong> · ' + escapeHtml(l.level) + '</div>';
                });
                html += '</div>';
            }
            html += '</div>';
        }

        html += '</div>';
        return html;
    }

    // ============================================
    // UTILITY HTML
    // ============================================
    function nl2br(str) {
        return str.replace(/\n/g, '<br>');
    }

    // ============================================
    // GENERA PDF
    // ============================================
    document.getElementById('pdfBtn').addEventListener('click', async function() {
        const btn = this;
        const firstName = document.getElementById('firstName').value.trim();
        const lastName = document.getElementById('lastName').value.trim();
        const email = document.getElementById('email').value.trim();

        if (!firstName || !lastName || !email) {
            showToast('Fill in First Name, Last Name and Email!', 'error');
            return;
        }

        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:16px;height:16px;border-width:2px;margin:0;"></span> Generating...';

        try {
            const cvPage = document.querySelector('#cvPreviewContainer .cv-page');
            if (!cvPage) {
                showToast('No CV to generate', 'error');
                btn.disabled = false;
                btn.innerHTML = originalText;
                return;
            }

            // Clona il CV in un container temporaneo NON scalato
            const tempContainer = document.createElement('div');
            tempContainer.style.cssText = 'position: fixed; left: -99999px; top: 0; z-index: -1; background: #fff;';
            tempContainer.appendChild(cvPage.cloneNode(true));
            document.body.appendChild(tempContainer);

            const clonedCv = tempContainer.querySelector('.cv-page');
            clonedCv.style.transform = 'none';

            // Aspetta rendering
            await new Promise(r => setTimeout(r, 200));

            const canvas = await html2canvas(clonedCv, {
                scale: 2,
                useCORS: true,
                backgroundColor: '#ffffff',
                logging: false,
                windowWidth: clonedCv.scrollWidth,
                windowHeight: clonedCv.scrollHeight
            });

            const imgData = canvas.toDataURL('image/jpeg', 0.95);
            const { jsPDF } = window.jspdf;

            const pdf = new jsPDF({
                orientation: 'portrait',
                unit: 'mm',
                format: 'a4'
            });

            const pageW = 210;
            const pageH = 297;
            const imgW = canvas.width;
            const imgH = canvas.height;
            const ratio = imgW / imgH;
            let pdfW = pageW;
            let pdfH = pageW / ratio;

            if (pdfH <= pageH) {
                pdf.addImage(imgData, 'JPEG', 0, 0, pdfW, pdfH);
            } else {
                // Multi-pagina
                let yOffset = 0;
                let remaining = pdfH;
                while (remaining > 0) {
                    pdf.addImage(imgData, 'JPEG', 0, yOffset, pdfW, pdfH);
                    remaining -= pageH;
                    yOffset -= pageH;
                    if (remaining > 0) pdf.addPage();
                }
            }

            tempContainer.remove();

            pdf.save('CV_' + firstName + '_' + lastName + '.pdf');

            unlockAch('pdf_generated');
            showToast('PDF generated successfully!', 'success');
        } catch (error) {
            console.error(error);
            showToast('PDF Error:' + error.message, 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    });

    // ============================================
    // SALVA BOZZA
    // ============================================
    function saveDraft() {
        try {
            const draft = {
                firstName: document.getElementById('firstName').value,
                lastName: document.getElementById('lastName').value,
                jobTitle: document.getElementById('jobTitle').value,
                email: document.getElementById('email').value,
                phone: document.getElementById('phone').value,
                city: document.getElementById('city').value,
                website: document.getElementById('website').value,
                bio: document.getElementById('bio').value,
                skills: document.getElementById('skills').value,
                accentColor: document.getElementById('accentColor').value,
                template: currentTemplate,
                photo: currentPhoto,
                experiences: [],
                educations: [],
                languages: []
            };
            document.querySelectorAll('#experiencesContainer .dynamic-row').forEach(row => {
                draft.experiences.push({
                    role: row.querySelector('.exp-role').value,
                    company: row.querySelector('.exp-company').value,
                    date: row.querySelector('.exp-date').value,
                    desc: row.querySelector('.exp-desc').value
                });
            });
            document.querySelectorAll('#educationContainer .dynamic-row').forEach(row => {
                draft.educations.push({
                    title: row.querySelector('.edu-title').value,
                    institute: row.querySelector('.edu-institute').value,
                    date: row.querySelector('.edu-date').value
                });
            });
            document.querySelectorAll('#languagesContainer .dynamic-row').forEach(row => {
                draft.languages.push({
                    name: row.querySelector('.lang-name').value,
                    level: row.querySelector('.lang-level').value
                });
            });

            localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
            showToast('Draft saved!', 'success');
        } catch (e) {
            showToast('Error saving (photo too large?)', 'error');
        }
    }

    // ============================================
    // CARICA BOZZA
    // ============================================
    function loadDraft() {
        try {
            const raw = localStorage.getItem(DRAFT_KEY);
            if (!raw) return;
            const draft = JSON.parse(raw);

            document.getElementById('firstName').value = draft.firstName || '';
            document.getElementById('lastName').value = draft.lastName || '';
            document.getElementById('jobTitle').value = draft.jobTitle || '';
            document.getElementById('email').value = draft.email || '';
            document.getElementById('phone').value = draft.phone || '';
            document.getElementById('city').value = draft.city || '';
            document.getElementById('website').value = draft.website || '';
            document.getElementById('bio').value = draft.bio || '';
            document.getElementById('skills').value = draft.skills || '';
            document.getElementById('accentColor').value = draft.accentColor || '#D8A93C';

            if (draft.photo) {
                currentPhoto = draft.photo;
                document.getElementById('photoImg').src = draft.photo;
                document.getElementById('photoImg').style.display = 'block';
                document.getElementById('photoPlaceholder').style.display = 'none';
            }

            if (draft.template) selectTemplate(draft.template);

            (draft.experiences || []).forEach(e => addExperience(e));
            (draft.educations || []).forEach(e => addEducation(e));
            (draft.languages || []).forEach(l => addLanguage(l));

            showToast('Draft loaded!', 'info');
        } catch (e) {
            console.error('loadDraft error:', e);
        }
    }

    // ============================================
    // RESET
    // ============================================
    function resetAll() {
        if (!confirm('Are you sure you want to reset everything? Unsaved data will be lost.')) return;

        document.getElementById('firstName').value = '';
        document.getElementById('lastName').value = '';
        document.getElementById('jobTitle').value = '';
        document.getElementById('email').value = '';
        document.getElementById('phone').value = '';
        document.getElementById('city').value = '';
        document.getElementById('website').value = '';
        document.getElementById('bio').value = '';
        document.getElementById('skills').value = '';
        document.getElementById('accentColor').value = '#D8A93C';
        document.getElementById('experiencesContainer').innerHTML = '';
        document.getElementById('educationContainer').innerHTML = '';
        document.getElementById('languagesContainer').innerHTML = '';
        currentPhoto = null;
        document.getElementById('photoImg').style.display = 'none';
        document.getElementById('photoPlaceholder').style.display = 'block';
        document.getElementById('photoInput').value = '';

        localStorage.removeItem(DRAFT_KEY);
        selectTemplate('moderno');

        addExperience();
        addEducation();
        addLanguage();

        updatePreview();
        showToast('Reset completed', 'success');
    }

    // ============================================
    // INIT
    // ============================================
    document.addEventListener('DOMContentLoaded', function() {
        try {
            renderAch();
            loadDraft();

            if (document.querySelectorAll('#experiencesContainer .dynamic-row').length === 0) addExperience();
            if (document.querySelectorAll('#educationContainer .dynamic-row').length === 0) addEducation();
            if (document.querySelectorAll('#languagesContainer .dynamic-row').length === 0) addLanguage();

            ['firstName', 'lastName', 'email'].forEach(id => {
                document.getElementById(id).addEventListener('input', function() {
                    const fn = document.getElementById('firstName').value.trim();
                    const ln = document.getElementById('lastName').value.trim();
                    const em = document.getElementById('email').value.trim();
                    if (fn && ln && em) unlockAch('first_fill');
                });
            });

            document.getElementById('skills').addEventListener('input', function() {
                const skills = this.value.trim();
                if (skills) {
                    const list = skills.split(',').filter(s => s.trim());
                    if (list.length >= 5) unlockAch('skills_added');
                }
            });

            updatePreview();
        } catch (e) {
            console.error('Init error:', e);
        }
    });
</script>

