if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate'])) {
    $theme = trim($_POST['theme'] ?? '');
    $genre = trim($_POST['genre'] ?? '');

    if (empty($theme) || empty($genre)) {
        jsonResponse(['success' => false, 'error' => t('Fill in all the fields!')]);
    }

    $genreMap = [
        'pop' => 'Pop',
        'rap' => 'Rap',
        'rock' => 'Rock',
        'romantico' => 'Romantico',
        'triste' => 'Triste / Malinconico',
        'felice' => 'Felice / Allegro',
        'estate' => 'Estate',
        'inverno' => 'Inverno',
        'elettronica' => 'Elettronica',
        'indie' => 'Indie'
    ];
    $genreName = $genreMap[$genre] ?? $genre;

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = 'Sei un cantautore esperto. Scrivi testi di canzoni emozionanti e originali. Rispondi in italiano con testo semplice.';
        $prompt = "Scrivi una canzone in stile $genreName sul tema: '$theme'. Struttura: Titolo, Strofa 1, Ritornello, Strofa 2, Ritornello, Bridge, Ritornello finale. Scrivi almeno 4-6 versi per strofa. Sii creativo, emozionante e originale. Rispondi in italiano. Usa testo semplice con paragrafi. NON usare tabelle.";
    } else {
        $systemPrompt = 'You are an expert songwriter. Write emotional and original song lyrics. Answer in English with plain text.';
        $prompt = "Write a song in $genreName style on the theme: '$theme'. Structure: Title, Verse 1, Chorus, Verse 2, Chorus, Bridge, Final Chorus. Write at least 4-6 lines per verse. Be creative, emotional and original. Answer in English. Use plain text with paragraphs. Do NOT use tables.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.95, 'max_tokens' => 2500]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);

    jsonResponse(['success' => true, 'result' => $result['content']]);
}

