if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['message'])) {
    jsonCorsHeaders();
    $lang = currentLang();

    $message = trim($_POST['message'] ?? '');
    $tone = trim($_POST['tone'] ?? 'friendly');
    $history = $_POST['history'] ?? '[]';

    if ($message === '') {
        jsonResponse(['success' => false, 'error' => $lang === 'it' ? 'Messaggio vuoto' : 'Empty message'], 400);
    }

    $toneMap = [
        'friendly' => $lang === 'it'
            ? 'amichevole, informale e alla mano. Usa un tono caldo e accessibile.'
            : 'friendly, informal and approachable. Use a warm and accessible tone.',
        'professional' => $lang === 'it'
            ? 'professionale, formale e preciso. Usa un linguaggio tecnico ma chiaro.'
            : 'professional, formal and precise. Use technical but clear language.',
        'sarcastic' => $lang === 'it'
            ? 'sarcastico, ironico e pungente. Rispondi con umorismo intelligente.'
            : 'sarcastic, ironic and sharp. Answer with smart humor.',
        'poetic' => $lang === 'it'
            ? 'poetico, evocativo e ricco di metafore. Scrivi in modo elegante e suggestivo.'
            : 'poetic, evocative and rich in metaphors. Write in an elegant and suggestive way.'
    ];
    $tonePrompt = $toneMap[$tone] ?? $toneMap['friendly'];

    $systemPrompt = $lang === 'it'
        ? "Sei LUX.AI, un assistente virtuale intelligente dell'ecosistema L.U.X. Verse. Il tuo tono deve essere $tonePrompt. Rispondi sempre in italiano in modo chiaro, utile e completo."
        : "You are LUX.AI, a smart virtual assistant of the L.U.X. Verse ecosystem. Your tone must be $tonePrompt. Always answer in English in a clear, useful and complete way.";

    $messages = [['role' => 'system', 'content' => $systemPrompt]];

    $historyArray = json_decode($history, true);
    if (is_array($historyArray)) {
        $historyArray = array_slice($historyArray, -10);
        foreach ($historyArray as $msg) {
            if (isset($msg['role'], $msg['content'])) {
                $messages[] = [
                    'role' => $msg['role'] === 'user' ? 'user' : 'assistant',
                    'content' => $msg['content']
                ];
            }
        }
    }
    $messages[] = ['role' => 'user', 'content' => $message];

    $ai = askGroq($messages, ['temperature' => 0.8, 'max_tokens' => 1500]);
    if (!$ai['success']) {
        jsonResponse(['success' => false, 'error' => $ai['error']], 502);
    }

    jsonResponse(['success' => true, 'reply' => $ai['content']]);
}

