<script>
    // ============================================
    // STATO GLOBALE
    // ============================================
    let conversationHistory = [];
    let cooldownActive = false;
    let cooldownTimer = 60;
    let cooldownInterval = null;
    let lastQuestionIndex = -1;

    // ============================================
    // INVIA MESSAGGIO
    // ============================================
    async function sendMessage() {
        if (cooldownActive) return;

        const input = document.getElementById('messageInput');
        const message = input.value.trim();
        const tone = document.getElementById('toneSelect').value;

        if (!message) return;

        const chatArea = document.getElementById('chatArea');

        const userMsg = document.createElement('div');
        userMsg.className = 'chat-message user';
        userMsg.innerHTML = '<div class="msg-avatar">YOU</div><div class="msg-bubble">' + escapeHtml(message) + '</div>';
        chatArea.appendChild(userMsg);

        conversationHistory.push({ role: 'user', content: message });

        input.value = '';
        input.style.height = 'auto';
        document.getElementById('sendBtn').disabled = true;

        const typingMsg = document.createElement('div');
        typingMsg.className = 'chat-message ai';
        typingMsg.id = 'typingIndicator';
        typingMsg.innerHTML = '<div class="msg-avatar">AI</div><div class="msg-bubble"><div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div></div>';
        chatArea.appendChild(typingMsg);
        chatArea.scrollTop = chatArea.scrollHeight;

        try {
            const formData = new FormData();
            formData.append('message', message);
            formData.append('tone', tone);
            formData.append('history', JSON.stringify(conversationHistory.slice(0, -1)));

            const response = await fetch('workmeparlare.php', { method: 'POST', body: formData });
            const data = await response.json();

            const typing = document.getElementById('typingIndicator');
            if (typing) typing.remove();

            if (data.success) {
                const aiMsg = document.createElement('div');
                aiMsg.className = 'chat-message ai';
                aiMsg.innerHTML = '<div class="msg-avatar">AI</div><div class="msg-bubble">' + markdownToHTML(data.reply) + '</div>';
                chatArea.appendChild(aiMsg);

                conversationHistory.push({ role: 'assistant', content: data.reply });

                if (conversationHistory.length > 20) {
                    conversationHistory = conversationHistory.slice(-20);
                }
            } else {
                const errMsg = document.createElement('div');
                errMsg.className = 'chat-message ai';
                errMsg.innerHTML = '<div class="msg-avatar">AI</div><div class="msg-bubble" style="color: var(--pink);">Error: ' + escapeHtml(data.error) + '</div>';
                chatArea.appendChild(errMsg);
            }
        } catch (error) {
            const typing = document.getElementById('typingIndicator');
            if (typing) typing.remove();
            const errMsg = document.createElement('div');
            errMsg.className = 'chat-message ai';
            errMsg.innerHTML = '<div class="msg-avatar">AI</div><div class="msg-bubble" style="color: var(--pink);">Connection error</div>';
            chatArea.appendChild(errMsg);
        }

        chatArea.scrollTop = chatArea.scrollHeight;

        startCooldown();
    }

    // ============================================
    // COOLDOWN
    // ============================================
    function startCooldown() {
        cooldownActive = true;
        cooldownTimer = 60;

        const sendBtn = document.getElementById('sendBtn');
        const cooldownContainer = document.getElementById('cooldownContainer');
        const cooldownNum = document.getElementById('cooldownNum');
        const cooldownFg = document.getElementById('cooldownFg');

        sendBtn.disabled = true;
        cooldownContainer.classList.add('active');
        cooldownNum.textContent = '60';
        cooldownFg.style.strokeDashoffset = 0;

        showMinigame();

        cooldownInterval = setInterval(() => {
            cooldownTimer--;
            cooldownNum.textContent = cooldownTimer;

            const dasharray = 188.4;
            const offset = dasharray - (cooldownTimer / 60) * dasharray;
            cooldownFg.style.strokeDashoffset = offset;

            if (cooldownTimer <= 0) {
                clearInterval(cooldownInterval);
                cooldownActive = false;
                sendBtn.disabled = false;
                cooldownContainer.classList.remove('active');
                document.getElementById('minigameContainer').classList.remove('active');
                document.getElementById('messageInput').focus();
            }
        }, 1000);
    }

    // ============================================
    // MINIGIOCO
    // ============================================
    const minigameQuestions = [
        { question: "What is the capital of France?", options: ["Rome", "Paris", "Madrid", "London"], correct: 1 },
        { question: "How many planets are in the solar system?", options: ["7", "8", "9", "10"], correct: 1 },
        { question: "Who painted the Mona Lisa?", options: ["Michelangelo", "Leonardo da Vinci", "Raphael", "Picasso"], correct: 1 },
        { question: "What is the fastest land animal?", options: ["Lion", "Cheetah", "Falcon", "Horse"], correct: 1 },
        { question: "In which year did the Berlin Wall fall?", options: ["1985", "1989", "1991", "1993"], correct: 1 },
        { question: "What is the longest river in the world?", options: ["Nile", "Amazon", "Mississippi", "Ganges"], correct: 1 },
        { question: "Who wrote the Divine Comedy?", options: ["Petrarch", "Boccaccio", "Dante Alighieri", "Machiavelli"], correct: 2 },
        { question: "Which is the largest planet in the solar system?", options: ["Earth", "Mars", "Jupiter", "Saturn"], correct: 2 },
        { question: "What is the largest ocean?", options: ["Atlantic", "Pacific", "Indian", "Arctic"], correct: 1 },
        { question: "Who discovered America in 1492?", options: ["Marco Polo", "Christopher Columbus", "Amerigo Vespucci", "Magellan"], correct: 1 },
        { question: "What is the highest mountain in the world?", options: ["K2", "Mont Blanc", "Everest", "Kilimanjaro"], correct: 2 },
        { question: "How many strings does a classical guitar have?", options: ["4", "5", "6", "7"], correct: 2 },
        { question: "What is the chemical symbol of gold?", options: ["Ag", "Fe", "Au", "Cu"], correct: 2 },
        { question: "How many minutes are in an hour?", options: ["30", "45", "60", "90"], correct: 2 },
        { question: "Who wrote 'The Little Prince'?", options: ["Oscar Wilde", "Antoine de Saint-Exupery", "Charles Dickens", "Hemingway"], correct: 1 }
    ];

    function showMinigame() {
        const questionEl = document.getElementById('minigameQuestion');
        const optionsEl = document.getElementById('minigameOptions');
        const resultEl = document.getElementById('minigameResult');

        resultEl.textContent = '';

        let randomIndex;
        do {
            randomIndex = Math.floor(Math.random() * minigameQuestions.length);
        } while (randomIndex === lastQuestionIndex && minigameQuestions.length > 1);

        lastQuestionIndex = randomIndex;
        const q = minigameQuestions[randomIndex];

        questionEl.textContent = q.question;
        optionsEl.innerHTML = '';

        q.options.forEach((option, index) => {
            const btn = document.createElement('div');
            btn.className = 'minigame-option';
            btn.textContent = option;
            btn.onclick = () => checkMinigameAnswer(index, q.correct, btn);
            optionsEl.appendChild(btn);
        });
    }

    function checkMinigameAnswer(selected, correct, btn) {
        const resultEl = document.getElementById('minigameResult');
        const options = document.querySelectorAll('.minigame-option');

        options.forEach(option => { option.style.pointerEvents = 'none'; });

        if (selected === correct) {
            btn.classList.add('correct');
            resultEl.textContent = 'Correct!';
            resultEl.style.color = 'var(--green)';
        } else {
            btn.classList.add('wrong');
            options[correct].classList.add('correct');
            resultEl.textContent = 'Wrong! The answer was: ' + options[correct].textContent;
            resultEl.style.color = 'var(--pink)';
        }

        if (cooldownTimer > 10) {
            setTimeout(showMinigame, 2000);
        }
    }

    // ============================================
    // UTILITY
    // ============================================
    function clearChat() {
        if (!confirm('Delete the whole conversation?')) return;
        conversationHistory = [];
        const chatArea = document.getElementById('chatArea');
        chatArea.innerHTML = '<div class="chat-message ai"><div class="msg-avatar">AI</div><div class="msg-bubble">Hi! I\'m <strong>LUX.AI</strong>, your virtual assistant. How can I help you today?<br><br>You can ask me anything: curiosity, explanations, advice, recipes, creative ideas and much more!</div></div>';
        document.getElementById('messageInput').focus();
    }

    const messageInput = document.getElementById('messageInput');
    messageInput.addEventListener('input', function() {
        this.style.height = 'auto';
        this.style.height = Math.min(this.scrollHeight, 120) + 'px';
    });

    messageInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    });

    document.addEventListener('DOMContentLoaded', function() {
        messageInput.focus();
    });
</script>

