if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate_recipe'])) {
    $ingredients = trim($_POST['ingredients'] ?? '');

    if (empty($ingredients)) {
        jsonResponse(['success' => false, 'error' => t('Write the ingredients!')]);
    }

    $lang = currentLang();
    if ($lang === 'it') {
        $systemPrompt = "Sei uno chef esperto. Genera ricette creative e dettagliate. Rispondi in italiano. Usa testo semplice e punti elenco.";
        $prompt = "Genera una ricetta creativa usando questi ingredienti: $ingredients. Fornisci: 1) Nome della ricetta. 2) Tempo di preparazione. 3) Difficoltà. 4) Ingredienti dettagliati con quantità. 5) Passaggi di preparazione numerati. 6) Un consiglio finale dello chef. Usa SOLO testo semplice con paragrafi e punti elenco. NON usare tabelle. Rispondi in italiano in modo COMPLETO.";
    } else {
        $systemPrompt = "You are an expert chef. Generate creative and detailed recipes. Reply in English. Use plain text and bullet points.";
        $prompt = "Generate a creative recipe using these ingredients: $ingredients. Provide: 1) Recipe name. 2) Preparation time. 3) Difficulty. 4) Detailed ingredients with quantities. 5) Numbered preparation steps. 6) A final tip from the chef. Use ONLY plain text with paragraphs and bullet points. Do NOT use tables. Reply in English, completely.";
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.8, 'max_tokens' => 2000]);

    if (!$result['success']) jsonResponse(['success' => false, 'error' => $result['error']]);
    jsonResponse(['success' => true, 'recipe' => $result['content']]);
}

