<script>
    let currentAnswer = '';
    let currentIngredients = '';
    const HISTORY_KEY = 'workmerecipe_history';
    const MAX_HISTORY = 5;

    function setExample(text) {
        document.getElementById('ingredientsInput').value = text;
        document.getElementById('ingredientsInput').focus();
    }

    async function generateRecipe() {
        const ingredients = document.getElementById('ingredientsInput').value.trim();
        if (!ingredients) {
            showToast('Write the ingredients!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> <?= t('Generating...') ?>';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate_recipe', '1');
            formData.append('ingredients', ingredients);

            const response = await fetch('workmerecipe.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentAnswer = data.recipe;
                currentIngredients = ingredients;
                document.getElementById('answerContent').innerHTML = markdownToHTML(data.recipe);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(ingredients, data.recipe);
                showToast('Recipe generated!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyAnswer() {
        if (!currentAnswer) { showToast('No recipe to copy', 'error'); return; }
        navigator.clipboard.writeText(currentAnswer).then(() => {
            showToast('Recipe copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function speakAnswer() {
        if (!currentAnswer) { showToast('No recipe to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentAnswer);
        utterance.lang = <?= currentLang() === 'it' ? "'it-IT'" : "'en-US'" ?>;
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadAnswer() {
        if (!currentAnswer) { showToast('No recipe to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Recipe - Generated Recipe\nDate: ' + date + '\nIngredients: ' + currentIngredients + '\n\n' + currentAnswer;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmerecipe_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Recipe downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(ingredients, answer) {
        let history = loadHistory();
        history = history.filter(h => h.ingredients !== ingredients);
        history.unshift({ ingredients: ingredients, answer: answer, date: new Date().toISOString() });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No recipes saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(item.ingredients) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentAnswer = history[index].answer;
            currentIngredients = history[index].ingredients;
            document.getElementById('ingredientsInput').value = history[index].ingredients;
            document.getElementById('answerContent').innerHTML = markdownToHTML(history[index].answer);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Recipe loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear all the recipe history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

<?php lux_footer(); ?>
