<script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js" defer></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js" defer></script>

<script>
(function() {
    let libsReady = false;
    let pendingGenerate = null;

    function checkLibs() {
        if (typeof html2canvas !== 'undefined' && typeof window.jspdf !== 'undefined' && window.jspdf.jsPDF) {
            libsReady = true;
            if (pendingGenerate) {
                const fn = pendingGenerate;
                pendingGenerate = null;
                fn();
            }
        }
    }

    let attempts = 0;
    const interval = setInterval(function() {
        checkLibs();
        attempts++;
        if (libsReady || attempts > 50) clearInterval(interval);
    }, 200);

    window.__waitForPDFLibs = function(callback) {
        if (libsReady) {
            callback();
        } else {
            pendingGenerate = callback;
        }
    };
})();

document.addEventListener('DOMContentLoaded', function() {

    const DRAFT_KEY = 'workmeresume_draft';
    const ACH_KEY = 'workmeresume_achievements';
    let currentPhoto = null;
    let currentTemplate = 'moderno';
    let currentZoom = 1;

    const LEVEL_LABELS = { 'Madrelingua': <?= json_encode(t('Mother tongue')) ?> };
    function levelLabel(v) { return LEVEL_LABELS[v] || v; }

    const ACHIEVEMENTS = [
        { id: 'first_fill', icon: '<i data-i=note class=ic></i>', title: <?= json_encode(t('First Step')) ?>, desc: <?= json_encode(t('Fill in your basic details')) ?> },
        { id: 'exp_added', icon: '<i data-i=brief class=ic></i>', title: <?= json_encode(t('Professional')) ?>, desc: <?= json_encode(t('Add a work experience')) ?> },
        { id: 'edu_added', icon: '<i data-i=gradcap class=ic></i>', title: <?= json_encode(t('Scholar')) ?>, desc: <?= json_encode(t('Add an education')) ?> },
        { id: 'photo_added', icon: '<i data-i=camera class=ic></i>', title: <?= json_encode(t('CV Photo')) ?>, desc: <?= json_encode(t('Add a photo')) ?> },
        { id: 'skills_added', icon: '<i data-i=bolt class=ic></i>', title: <?= json_encode(t('Skilled')) ?>, desc: <?= json_encode(t('Add 5+ skills')) ?> },
        { id: 'pdf_generated', icon: '<i data-i=file class=ic></i>', title: <?= json_encode(t('Job Ready')) ?>, desc: <?= json_encode(t('Generate your first PDF')) ?> }
    ];

    function loadAch() {
        try { const r = localStorage.getItem(ACH_KEY); return r ? JSON.parse(r) : []; } catch (e) { return []; }
    }
    function saveAch(list) {
        try { localStorage.setItem(ACH_KEY, JSON.stringify(list)); } catch (e) {}
    }
    function unlockAch(id) {
        const unlocked = loadAch();
        if (!unlocked.includes(id)) {
            unlocked.push(id);
            saveAch(unlocked);
            const a = ACHIEVEMENTS.find(x => x.id === id);
            if (a) showToast('Achievement:' + a.title + '!', 'achievement');
            renderAch();
        }
    }
    function renderAch() {
        const grid = document.getElementById('achievementsGrid');
        if (!grid) return;
        const unlocked = loadAch();
        grid.innerHTML = '';
        ACHIEVEMENTS.forEach(a => {
            const isUnlocked = unlocked.includes(a.id);
            const div = document.createElement('div');
            div.className = 'achievement' + (isUnlocked ? ' unlocked' : '');
            div.innerHTML =
                '<span class="ach-icon">' + a.icon + '</span>' +
                '<div class="ach-title">' + a.title + '</div>' +
                '<div class="ach-desc">' + a.desc + '</div>';
            grid.appendChild(div);
        });
        document.getElementById('achProgress').textContent = <?= json_encode(t('Unlocked:')) ?> + unlocked.length + '/' + ACHIEVEMENTS.length;
    }

    const photoInput = document.getElementById('photoInput');
    if (photoInput) {
        photoInput.addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (!file) return;
            if (!file.type.startsWith('image/')) { showToast('Select a valid image', 'error'); return; }
            if (file.size > 5 * 1024 * 1024) { showToast('Photo too large (max 5MB)', 'error'); return; }
            const reader = new FileReader();
            reader.onload = function(ev) {
                currentPhoto = ev.target.result;
                const img = document.getElementById('photoImg');
                img.src = currentPhoto;
                img.style.display = 'block';
                document.getElementById('photoPlaceholder').style.display = 'none';
                updatePreview();
                unlockAch('photo_added');
                showToast('Photo uploaded!', 'success');
            };
            reader.readAsDataURL(file);
        });
    }

    window.removePhoto = function() {
        currentPhoto = null;
        document.getElementById('photoImg').style.display = 'none';
        document.getElementById('photoPlaceholder').style.display = 'block';
        document.getElementById('photoInput').value = '';
        updatePreview();
    };

    window.addExperience = function(data) {
        data = data || {};
        const container = document.getElementById('experiencesContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        div.innerHTML =
            '<button class="remove-btn" onclick="removeDynamic(this)" type="button">×</button>' +
            '<div class="fg"><label><?= t('Role') ?></label><input type="text" class="exp-role" placeholder="<?= t('E.g. Web Developer') ?>" value="' + (data.role || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
            '<div class="fg"><label><?= t('Company') ?></label><input type="text" class="exp-company" placeholder="<?= t('E.g. L.U.X. Verse') ?>" value="' + (data.company || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
            '<div class="fg"><label><?= t('Period') ?></label><input type="text" class="exp-date" placeholder="<?= t('E.g. 2023 - Present') ?>" value="' + (data.date || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
            '<div class="fg"><label><?= t('Description') ?></label><textarea class="exp-desc" placeholder="<?= t('Describe your responsibilities...') ?>" oninput="updatePreview()">' + (data.desc || '') + '</textarea></div>';
        container.appendChild(div);
        updatePreview();
        unlockAch('exp_added');
    };

    window.addEducation = function(data) {
        data = data || {};
        const container = document.getElementById('educationContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        div.innerHTML =
            '<button class="remove-btn" onclick="removeDynamic(this)" type="button">×</button>' +
            '<div class="fg"><label><?= t('Degree') ?></label><input type="text" class="edu-title" placeholder="<?= t('E.g. Informatics Diploma') ?>" value="' + (data.title || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
            '<div class="fg"><label><?= t('Institute') ?></label><input type="text" class="edu-institute" placeholder="E.g. ITIS Galileo Galilei" value="' + (data.institute || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
            '<div class="fg"><label><?= t('Period') ?></label><input type="text" class="edu-date" placeholder="<?= t('E.g. 2020 - 2025') ?>" value="' + (data.date || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>';
        container.appendChild(div);
        updatePreview();
        unlockAch('edu_added');
    };

    window.addLanguage = function(data) {
        data = data || {};
        const container = document.getElementById('languagesContainer');
        const div = document.createElement('div');
        div.className = 'dynamic-row';
        const levels = ['Madrelingua','C2','C1','B2','B1','A2','A1'];
        let optionsHtml = '';
        levels.forEach(function(lv) {
            optionsHtml += '<option value="' + lv + '"' + (data.level === lv ? ' selected' : '') + '>' + levelLabel(lv) + '</option>';
        });
        div.innerHTML =
            '<button class="remove-btn" onclick="removeDynamic(this)" type="button">×</button>' +
            '<div class="row">' +
                '<div class="fg"><label><?= t('Language') ?></label><input type="text" class="lang-name" placeholder="<?= t('E.g. English') ?>" value="' + (data.name || '').replace(/"/g, '&quot;') + '" oninput="updatePreview()"></div>' +
                '<div class="fg"><label><?= t('Level') ?></label><select class="lang-level" onchange="updatePreview()">' + optionsHtml + '</select></div>' +
            '</div>';
        container.appendChild(div);
        updatePreview();
    };

    window.removeDynamic = function(btn) {
        btn.closest('.dynamic-row').remove();
        updatePreview();
    };

    window.selectTemplate = function(name) {
        currentTemplate = name;
        document.querySelectorAll('.template-option').forEach(function(el) { el.classList.remove('selected'); });
        const t = document.querySelector('.template-option[data-template="' + name + '"]');
        if (t) t.classList.add('selected');
        updatePreview();
    };

    window.changeZoom = function(delta) {
        currentZoom = Math.max(0.3, Math.min(1.5, currentZoom + delta));
        const container = document.getElementById('cvPreviewContainer');
        if (container) container.style.transform = 'scale(' + currentZoom + ')';
    };

    window.updatePreview = function() {
        try {
            const container = document.getElementById('cvPreviewContainer');
            if (!container) return;
            const accent = (document.getElementById('accentColor') || {}).value || '#D8A93C';
            const data = {
                firstName: (document.getElementById('firstName') || {}).value || '',
                lastName: (document.getElementById('lastName') || {}).value || '',
                jobTitle: (document.getElementById('jobTitle') || {}).value || '',
                email: (document.getElementById('email') || {}).value || '',
                phone: (document.getElementById('phone') || {}).value || '',
                city: (document.getElementById('city') || {}).value || '',
                website: (document.getElementById('website') || {}).value || '',
                bio: (document.getElementById('bio') || {}).value || '',
                skills: (document.getElementById('skills') || {}).value || '',
                photo: currentPhoto,
                accent: accent
            };
            const experiences = [];
            document.querySelectorAll('#experiencesContainer .dynamic-row').forEach(function(row) {
                experiences.push({
                    role: (row.querySelector('.exp-role') || {}).value || '',
                    company: (row.querySelector('.exp-company') || {}).value || '',
                    date: (row.querySelector('.exp-date') || {}).value || '',
                    desc: (row.querySelector('.exp-desc') || {}).value || ''
                });
            });
            const educations = [];
            document.querySelectorAll('#educationContainer .dynamic-row').forEach(function(row) {
                educations.push({
                    title: (row.querySelector('.edu-title') || {}).value || '',
                    institute: (row.querySelector('.edu-institute') || {}).value || '',
                    date: (row.querySelector('.edu-date') || {}).value || ''
                });
            });
            const languages = [];
            document.querySelectorAll('#languagesContainer .dynamic-row').forEach(function(row) {
                languages.push({
                    name: (row.querySelector('.lang-name') || {}).value || '',
                    level: (row.querySelector('.lang-level') || {}).value || 'B1'
                });
            });

            let html = '';
            if (currentTemplate === 'moderno') {
                html = renderModernTemplate(data, experiences, educations, languages);
            } else {
                html = renderClassicTemplate(data, experiences, educations, languages);
            }
            container.innerHTML = html;
            container.style.transform = 'scale(' + currentZoom + ')';
        } catch (e) { console.error('updatePreview error:', e); }
    };

    function esc(str) {
        const div = document.createElement('div');
        div.textContent = str == null ? '' : String(str);
        return div.innerHTML;
    }
    function nl2br(str) {
        return esc(str).replace(/\n/g, '<br>');
    }

    function renderModernTemplate(data, experiences, educations, languages) {
        const skillsList = data.skills ? data.skills.split(',').map(function(s){return s.trim();}).filter(function(s){return s;}) : [];
        const hasExperiences = experiences.some(function(e){return e.role || e.company;});
        const hasEducations = educations.some(function(e){return e.title || e.institute;});
        const hasLanguages = languages.some(function(l){return l.name;});
        const name = (data.firstName || data.lastName) ? (data.firstName + ' ' + data.lastName).trim() : <?= json_encode(t('Your Name')) ?>;
        const title = data.jobTitle || <?= json_encode(t('Professional Title')) ?>;

        let html = '<div class="cv-page cv-moderno">';
        html += '<div class="cv-sidebar" style="background: ' + data.accent + ';">';
        html += '<div class="cv-photo">';
        html += data.photo ? '<img src="' + data.photo + '" alt="">' : '<i data-i=user class=ic></i>';
        html += '</div>';
        html += '<div class="cv-name">' + esc(name) + '</div>';
        html += '<div class="cv-title">' + esc(title) + '</div>';
        html += '<div class="sidebar-section"><h4><?= t('Contacts') ?></h4>';
        if (data.email) html += '<div class="contact-item"><strong><?= t('Email') ?></strong>' + esc(data.email) + '</div>';
        if (data.phone) html += '<div class="contact-item"><strong><?= t('Phone') ?></strong>' + esc(data.phone) + '</div>';
        if (data.city) html += '<div class="contact-item"><strong><?= t('City') ?></strong>' + esc(data.city) + '</div>';
        if (data.website) html += '<div class="contact-item"><strong>Web</strong>' + esc(data.website) + '</div>';
        html += '</div>';
        if (skillsList.length > 0) {
            html += '<div class="sidebar-section"><h4><?= t('Skills') ?></h4>';
            skillsList.forEach(function(s){ html += '<span class="skill-tag">' + esc(s) + '</span>'; });
            html += '</div>';
        }
        if (hasLanguages) {
            html += '<div class="sidebar-section"><h4><?= t('Languages') ?></h4>';
            languages.forEach(function(l){
                if (!l.name) return;
                html += '<div class="lang-item"><strong>' + esc(l.name) + '</strong> <span>· ' + esc(levelLabel(l.level)) + '</span></div>';
            });
            html += '</div>';
        }
        html += '</div>';
        html += '<div class="cv-main">';
        if (data.bio) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Profile') ?></h3>';
            html += '<p>' + nl2br(data.bio) + '</p></div>';
        }
        if (hasExperiences) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Work Experience') ?></h3>';
            experiences.forEach(function(e){
                if (!e.role && !e.company) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header"><div class="exp-role">' + esc(e.role || <?= json_encode(t('Role')) ?>) + '</div>';
                if (e.date) html += '<div class="exp-date">' + esc(e.date) + '</div>';
                html += '</div>';
                if (e.company) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + esc(e.company) + '</div>';
                if (e.desc) html += '<div class="exp-desc">' + nl2br(e.desc) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }
        if (hasEducations) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Education') ?></h3>';
            educations.forEach(function(e){
                if (!e.title && !e.institute) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header"><div class="exp-role">' + esc(e.title || <?= json_encode(t('Degree')) ?>) + '</div>';
                if (e.date) html += '<div class="exp-date">' + esc(e.date) + '</div>';
                html += '</div>';
                if (e.institute) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + esc(e.institute) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }
        html += '</div></div>';
        return html;
    }

    function renderClassicTemplate(data, experiences, educations, languages) {
        const skillsList = data.skills ? data.skills.split(',').map(function(s){return s.trim();}).filter(function(s){return s;}) : [];
        const hasExperiences = experiences.some(function(e){return e.role || e.company;});
        const hasEducations = educations.some(function(e){return e.title || e.institute;});
        const hasLanguages = languages.some(function(l){return l.name;});
        const name = (data.firstName || data.lastName) ? (data.firstName + ' ' + data.lastName).trim() : <?= json_encode(t('Your Name')) ?>;
        const title = data.jobTitle || <?= json_encode(t('Professional Title')) ?>;

        let html = '<div class="cv-page cv-classico">';
        html += '<div class="cv-header" style="border-color: ' + data.accent + ';">';
        if (data.photo) html += '<div class="cv-photo" style="border-color: ' + data.accent + ';"><img src="' + data.photo + '" alt=""></div>';
        html += '<div class="cv-name">' + esc(name) + '</div>';
        html += '<div class="cv-title" style="color: ' + data.accent + ';">' + esc(title) + '</div>';
        const contacts = [];
        if (data.email) contacts.push('<i data-i=mail class=ic></i> ' + esc(data.email));
        if (data.phone) contacts.push('<i data-i=phone class=ic></i> ' + esc(data.phone));
        if (data.city) contacts.push('<i data-i=pin class=ic></i> ' + esc(data.city));
        if (data.website) contacts.push('<i data-i=globe class=ic></i> ' + esc(data.website));
        if (contacts.length > 0) {
            html += '<div class="cv-contacts">';
            contacts.forEach(function(c){ html += '<span>' + c + '</span>'; });
            html += '</div>';
        }
        html += '</div>';
        if (data.bio) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Profile') ?></h3>';
            html += '<p>' + nl2br(data.bio) + '</p></div>';
        }
        if (hasExperiences) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Work Experience') ?></h3>';
            experiences.forEach(function(e){
                if (!e.role && !e.company) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header"><div class="exp-role">' + esc(e.role || <?= json_encode(t('Role')) ?>) + '</div>';
                if (e.date) html += '<div class="exp-date">' + esc(e.date) + '</div>';
                html += '</div>';
                if (e.company) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + esc(e.company) + '</div>';
                if (e.desc) html += '<div class="exp-desc">' + nl2br(e.desc) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }
        if (hasEducations) {
            html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Education') ?></h3>';
            educations.forEach(function(e){
                if (!e.title && !e.institute) return;
                html += '<div class="exp-item">';
                html += '<div class="exp-header"><div class="exp-role">' + esc(e.title || <?= json_encode(t('Degree')) ?>) + '</div>';
                if (e.date) html += '<div class="exp-date">' + esc(e.date) + '</div>';
                html += '</div>';
                if (e.institute) html += '<div class="exp-company" style="color: ' + data.accent + ';">' + esc(e.institute) + '</div>';
                html += '</div>';
            });
            html += '</div>';
        }
        if (skillsList.length > 0 || hasLanguages) {
            html += '<div class="two-cols">';
            if (skillsList.length > 0) {
                html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Skills') ?></h3>';
                skillsList.forEach(function(s){ html += '<span class="skill-tag">' + esc(s) + '</span>'; });
                html += '</div>';
            }
            if (hasLanguages) {
                html += '<div class="main-section"><h3 style="border-color: ' + data.accent + '; color: ' + data.accent + ';"><?= t('Languages') ?></h3>';
                languages.forEach(function(l){
                    if (!l.name) return;
                    html += '<div class="lang-item"><strong>' + esc(l.name) + '</strong> · ' + esc(levelLabel(l.level)) + '</div>';
                });
                html += '</div>';
            }
            html += '</div>';
        }
        html += '</div>';
        return html;
    }

    window.generatePDF = function() {
        const firstName = (document.getElementById('firstName') || {}).value || '';
        const lastName = (document.getElementById('lastName') || {}).value || '';
        const email = (document.getElementById('email') || {}).value || '';
        if (!firstName.trim() || !lastName.trim() || !email.trim()) {
            showToast('Fill in First Name, Last Name and Email!', 'error');
            return;
        }

        if (typeof html2canvas === 'undefined' || typeof window.jspdf === 'undefined') {
            showToast('Loading PDF libraries... wait a moment', 'info');
            window.__waitForPDFLibs(function() {
                window.generatePDF();
            });
            return;
        }

        const btn = document.getElementById('pdfBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:16px;height:16px;border-width:2px;margin:0;"></span> <?= t('Generating...') ?>';

        try {
            const cvPage = document.querySelector('#cvPreviewContainer .cv-page');
            if (!cvPage) { showToast('No CV to generate', 'error'); btn.disabled = false; btn.innerHTML = originalText; return; }

            const tempContainer = document.createElement('div');
            tempContainer.style.cssText = 'position: fixed; left: -99999px; top: 0; z-index: -1; background: #fff;';
            tempContainer.appendChild(cvPage.cloneNode(true));
            document.body.appendChild(tempContainer);
            const clonedCv = tempContainer.querySelector('.cv-page');
            clonedCv.style.transform = 'none';

            setTimeout(function() {
                html2canvas(clonedCv, { scale: 2, useCORS: true, backgroundColor: '#ffffff', logging: false })
                    .then(function(canvas) {
                        try {
                            const imgData = canvas.toDataURL('image/jpeg', 0.95);
                            const jsPDF = window.jspdf.jsPDF;
                            const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
                            const pageW = 210, pageH = 297;
                            const imgW = canvas.width, imgH = canvas.height;
                            const ratio = imgW / imgH;
                            let pdfW = pageW, pdfH = pageW / ratio;
                            if (pdfH > pageH) {
                                let remainingHeight = pdfH;
                                let yPos = 0;
                                while (remainingHeight > 0) {
                                    pdf.addImage(imgData, 'JPEG', 0, yPos, pdfW, pdfH);
                                    remainingHeight -= pageH;
                                    yPos -= pageH;
                                    if (remainingHeight > 0) pdf.addPage();
                                }
                            } else {
                                pdf.addImage(imgData, 'JPEG', 0, 0, pdfW, pdfH);
                            }
                            tempContainer.remove();
                            pdf.save('CV_' + firstName + '_' + lastName + '.pdf');
                            unlockAch('pdf_generated');
                            showToast('PDF generated successfully!', 'success');
                        } catch (e) {
                            tempContainer.remove();
                            showToast('PDF error:' + e.message, 'error');
                        }
                        btn.disabled = false;
                        btn.innerHTML = originalText;
                    })
                    .catch(function(err) {
                        tempContainer.remove();
                        showToast('Error during generation:' + err.message, 'error');
                        btn.disabled = false;
                        btn.innerHTML = originalText;
                    });
            }, 150);
        } catch (e) {
            console.error(e);
            showToast('Error:' + e.message, 'error');
            btn.disabled = false;
            btn.innerHTML = originalText;
        }
    };

    window.saveDraft = function() {
        try {
            const draft = {
                firstName: (document.getElementById('firstName') || {}).value || '',
                lastName: (document.getElementById('lastName') || {}).value || '',
                jobTitle: (document.getElementById('jobTitle') || {}).value || '',
                email: (document.getElementById('email') || {}).value || '',
                phone: (document.getElementById('phone') || {}).value || '',
                city: (document.getElementById('city') || {}).value || '',
                website: (document.getElementById('website') || {}).value || '',
                bio: (document.getElementById('bio') || {}).value || '',
                skills: (document.getElementById('skills') || {}).value || '',
                accentColor: (document.getElementById('accentColor') || {}).value || '#D8A93C',
                template: currentTemplate,
                photo: currentPhoto,
                experiences: [],
                educations: [],
                languages: []
            };
            document.querySelectorAll('#experiencesContainer .dynamic-row').forEach(function(row) {
                draft.experiences.push({
                    role: (row.querySelector('.exp-role') || {}).value || '',
                    company: (row.querySelector('.exp-company') || {}).value || '',
                    date: (row.querySelector('.exp-date') || {}).value || '',
                    desc: (row.querySelector('.exp-desc') || {}).value || ''
                });
            });
            document.querySelectorAll('#educationContainer .dynamic-row').forEach(function(row) {
                draft.educations.push({
                    title: (row.querySelector('.edu-title') || {}).value || '',
                    institute: (row.querySelector('.edu-institute') || {}).value || '',
                    date: (row.querySelector('.edu-date') || {}).value || ''
                });
            });
            document.querySelectorAll('#languagesContainer .dynamic-row').forEach(function(row) {
                draft.languages.push({
                    name: (row.querySelector('.lang-name') || {}).value || '',
                    level: (row.querySelector('.lang-level') || {}).value || 'B1'
                });
            });
            localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
            showToast('Draft saved!', 'success');
        } catch (e) {
            showToast('Error saving draft', 'error');
        }
    };

    function loadDraft() {
        try {
            const raw = localStorage.getItem(DRAFT_KEY);
            if (!raw) return;
            const draft = JSON.parse(raw);
            ['firstName','lastName','jobTitle','email','phone','city','website','bio','skills'].forEach(function(id) {
                if (document.getElementById(id)) document.getElementById(id).value = draft[id] || '';
            });
            if (document.getElementById('accentColor') && draft.accentColor) document.getElementById('accentColor').value = draft.accentColor;
            if (draft.photo) {
                currentPhoto = draft.photo;
                document.getElementById('photoImg').src = draft.photo;
                document.getElementById('photoImg').style.display = 'block';
                document.getElementById('photoPlaceholder').style.display = 'none';
            }
            if (draft.template) window.selectTemplate(draft.template);
            (draft.experiences || []).forEach(function(e) { window.addExperience(e); });
            (draft.educations || []).forEach(function(e) { window.addEducation(e); });
            (draft.languages || []).forEach(function(l) { window.addLanguage(l); });
            showToast('Draft loaded!', 'info');
        } catch (e) {}
    }

    window.resetAll = function() {
        if (!confirm(<?= json_encode(t('Are you sure you want to reset everything? Unsaved data will be lost.')) ?>)) return;
        ['firstName','lastName','jobTitle','email','phone','city','website','bio','skills'].forEach(function(id) {
            if (document.getElementById(id)) document.getElementById(id).value = '';
        });
        document.getElementById('accentColor').value = '#D8A93C';
        document.getElementById('experiencesContainer').innerHTML = '';
        document.getElementById('educationContainer').innerHTML = '';
        document.getElementById('languagesContainer').innerHTML = '';
        currentPhoto = null;
        document.getElementById('photoImg').style.display = 'none';
        document.getElementById('photoPlaceholder').style.display = 'block';
        document.getElementById('photoInput').value = '';
        localStorage.removeItem(DRAFT_KEY);
        window.selectTemplate('moderno');
        window.addExperience();
        window.addEducation();
        window.addLanguage();
        window.updatePreview();
        showToast('Reset completed', 'success');
    };

    renderAch();
    loadDraft();
    if (document.querySelectorAll('#experiencesContainer .dynamic-row').length === 0) window.addExperience();
    if (document.querySelectorAll('#educationContainer .dynamic-row').length === 0) window.addEducation();
    if (document.querySelectorAll('#languagesContainer .dynamic-row').length === 0) window.addLanguage();

    ['firstName','lastName','email'].forEach(function(id) {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', function() {
            const fn = (document.getElementById('firstName') || {}).value || '';
            const ln = (document.getElementById('lastName') || {}).value || '';
            const em = (document.getElementById('email') || {}).value || '';
            if (fn.trim() && ln.trim() && em.trim()) unlockAch('first_fill');
        });
    });
    const skillsInput = document.getElementById('skills');
    if (skillsInput) skillsInput.addEventListener('input', function() {
        const skills = this.value.trim();
        if (skills) {
            const list = skills.split(',').filter(function(s){return s.trim();});
            if (list.length >= 5) unlockAch('skills_added');
        }
    });

    window.updatePreview();
});
</script>

