if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['generate'])) {
    jsonCorsHeaders();

    $tasks = trim($_POST['tasks'] ?? '');
    $hours = trim($_POST['hours'] ?? '');
    $priority = trim($_POST['priority'] ?? '');
    $wakeTime = trim($_POST['wake_time'] ?? '07:00');

    $lang = currentLang();

    if (empty($tasks) || empty($hours) || empty($priority)) {
        $msg = $lang === 'it' ? 'Compila tutti i campi obbligatori!' : 'Fill in all the required fields!';
        jsonResponse(['success' => false, 'error' => $msg], 400);
        exit;
    }

    $priorityMap = [
        'work' => ['en' => 'Work and productivity', 'it' => 'Lavoro e produttività'],
        'study' => ['en' => 'Study and learning', 'it' => 'Studio e apprendimento'],
        'health' => ['en' => 'Health and well-being', 'it' => 'Salute e benessere'],
        'relax' => ['en' => 'Relax and free time', 'it' => 'Relax e tempo libero'],
        'personal' => ['en' => 'Personal growth', 'it' => 'Crescita personale'],
        'family' => ['en' => 'Family and relationships', 'it' => 'Famiglia e relazioni']
    ];
    $priorityName = $priorityMap[$priority][$lang] ?? $priority;

    if ($lang === 'it') {
        $system = 'Sei un esperto di produttività e organizzazione. Crea programmi giornalieri realistici e dettagliati. Rispondi in italiano. Usa testo semplice e punti elenco.';
        $prompt = "Crea un programma giornaliero dettagliato ottimizzato per queste attività: '$tasks'.\nOre disponibili: $hours.\nPriorità principale: $priorityName.\nOra di sveglia: $wakeTime.\n\nOrganizza la giornata in blocchi orari specifici (con orari precisi), includendo pause e momenti di riposo. Aggiungi anche 3 consigli finali per una giornata produttiva. Usa SOLO testo semplice con paragrafi e punti elenco. NON usare tabelle. Rispondi in italiano in modo COMPLETO.";
    } else {
        $system = 'You are a productivity and organization expert. Create realistic, detailed daily schedules. Answer in English. Use plain text and bullet points.';
        $prompt = "Create a detailed daily schedule optimized for these activities: '$tasks'.\nAvailable hours: $hours.\nMain priority: $priorityName.\nWake-up time: $wakeTime.\n\nOrganize the day into specific time blocks (with precise times), including breaks and rest moments. Add 3 final tips for a productive day at the end. Use ONLY plain text with paragraphs and bullet points. Do NOT use tables. Answer fully in English.";
    }

    $ai = askGroq([
        ['role' => 'system', 'content' => $system],
        ['role' => 'user', 'content' => $prompt]
    ], [
        'temperature' => 0.7,
        'max_tokens' => 3000
    ]);

    if (!$ai['success']) {
        jsonResponse(['success' => false, 'error' => $ai['error']], 502);
        exit;
    }

    jsonResponse(['success' => true, 'schedule' => $ai['content']]);
    exit;
}

