<script>
    function setFromChip(chip) {
        document.getElementById('tasksInput').value = chip.dataset.tasks;
        document.getElementById('hoursInput').value = chip.dataset.hours;
        document.getElementById('prioritySelect').value = chip.dataset.priority;
        showToast('Example loaded!', 'success');
    }

    async function generateSchedule() {
        const tasks = document.getElementById('tasksInput').value.trim();
        const hours = document.getElementById('hoursInput').value.trim();
        const priority = document.getElementById('prioritySelect').value;
        const wakeTime = document.getElementById('wakeTimeInput').value;

        if (!tasks || !hours || !priority) {
            showToast('Fill in all the required fields!', 'error');
            return;
        }

        const btn = document.getElementById('generateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Planning...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('generate', '1');
            formData.append('tasks', tasks);
            formData.append('hours', hours);
            formData.append('priority', priority);
            formData.append('wake_time', wakeTime);

            const response = await fetch('workmeschedule.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentAnswer = data.schedule;
                currentContext = tasks.substring(0, 60) + (tasks.length > 60 ? '...' : '');
                document.getElementById('answerContent').innerHTML = markdownToHTML(data.schedule);
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(tasks, hours, priority, wakeTime, data.schedule);
                showToast('Schedule generated!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    function copyAnswer() {
        if (!currentAnswer) { showToast('No program to copy', 'error'); return; }
        navigator.clipboard.writeText(currentAnswer).then(() => {
            showToast('Program copied!', 'success');
        }).catch(() => showToast('Copy error', 'error'));
    }

    function speakAnswer() {
        if (!currentAnswer) { showToast('No program to read', 'error'); return; }
        if (!('speechSynthesis' in window)) { showToast('Your browser does not support speech synthesis', 'error'); return; }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentAnswer);
        const pageLang = (document.documentElement.lang || 'en').toLowerCase();
        utterance.lang = pageLang.indexOf('it') === 0 ? 'it-IT' : 'en-US';
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function downloadAnswer() {
        if (!currentAnswer) { showToast('No program to download', 'error'); return; }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'LUX.Schedule - Daily Program\nDate: ' + date + '\n\n' + currentAnswer;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmeschedule_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Program downloaded!', 'success');
    }

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
    }

    function saveToHistory(tasks, hours, priority, wakeTime, answer) {
        let history = loadHistory();
        history = history.filter(h => h.tasks !== tasks);
        history.unshift({
            tasks: tasks,
            hours: hours,
            priority: priority,
            wakeTime: wakeTime,
            answer: answer,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No saved programs</div>';
            return;
        }
        let html = '';
        const locale = navigator.language || 'en-US';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString(locale, { day: '2-digit', month: '2-digit' }) + ' ' +
                            date.toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' });
            const preview = item.tasks.substring(0, 70) + (item.tasks.length > 70 ? '...' : '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentAnswer = history[index].answer;
            document.getElementById('tasksInput').value = history[index].tasks;
            document.getElementById('hoursInput').value = history[index].hours;
            document.getElementById('prioritySelect').value = history[index].priority;
            if (history[index].wakeTime) document.getElementById('wakeTimeInput').value = history[index].wakeTime;
            document.getElementById('answerContent').innerHTML = markdownToHTML(history[index].answer);
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Program loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole program history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    let currentAnswer = '';
    let currentContext = '';
    const HISTORY_KEY = 'workmeschedule_history';
    const MAX_HISTORY = 5;

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

