    $sourceLang = trim($_POST['source_lang'] ?? 'auto');

    if ($text === '' || $targetLang === '') {
        jsonResponse(['success' => false, 'error' => $lang === 'it' ? 'Compila tutti i campi!' : 'Fill in all the fields!'], 400);
    }

    if ($lang === 'it') {
        $langNames = [
            'italian' => 'italiano', 'english' => 'inglese', 'spanish' => 'spagnolo',
            'french' => 'francese', 'german' => 'tedesco', 'portuguese' => 'portoghese',
            'russian' => 'russo', 'arabic' => 'arabo', 'chinese' => 'cinese',
            'japanese' => 'giapponese', 'korean' => 'coreano', 'dutch' => 'olandese',
            'polish' => 'polacco', 'turkish' => 'turco', 'greek' => 'greco'
        ];
        $targetName = $langNames[$targetLang] ?? $targetLang;
        $sourceName = $langNames[$sourceLang] ?? $sourceLang;
        $sourceInstruction = $sourceLang === 'auto'
            ? "Rileva automaticamente la lingua di origine e traduci il testo in $targetName."
            : "Traduci il testo dalla lingua $sourceName alla lingua $targetName.";
        $systemPrompt = 'Sei un traduttore esperto. Traduci testi mantenendo tono e stile. Rispondi SOLO con la traduzione, senza aggiungere nulla.';
        $userPrompt = "$sourceInstruction Mantieni il tono e lo stile originale. Testo: '$text'. Rispondi SOLO con la traduzione, senza spiegazioni, senza introduzioni, senza virgolette.";
    } else {
        $sourceInstruction = $sourceLang === 'auto'
            ? "Automatically detect the source language and translate the text into $targetLang."
            : "Translate the text from $sourceLang to $targetLang.";
        $systemPrompt = 'You are an expert translator. Translate texts while keeping tone and style. Reply ONLY with the translation, without adding anything.';
        $userPrompt = "$sourceInstruction Keep the original tone and style. Text: '$text'. Reply ONLY with the translation, no explanations, no introductions, no quotes.";
    }

    $messages = [
        ['role' => 'system', 'content' => $systemPrompt],
        ['role' => 'user', 'content' => $userPrompt]
    ];

    $ai = askGroq($messages, ['temperature' => 0.5, 'max_tokens' => 2000]);
    if (!$ai['success']) {
        jsonResponse(['success' => false, 'error' => $ai['error']], 502);
    }

    jsonResponse(['success' => true, 'translation' => $ai['content'], 'target_lang' => $targetLang]);
}

