<script>
    // ============================================
    // STATO GLOBALE
    // ============================================
    let currentTranslation = '';
    let currentTargetLang = '';
    let currentOriginalText = '';

    const HISTORY_KEY = 'workmetranslate_history';
    const MAX_HISTORY = 5;

    // Language map for TTS
    const langCodeMap = {
        'italian': 'it-IT',
        'english': 'en-US',
        'spanish': 'es-ES',
        'french': 'fr-FR',
        'german': 'de-DE',
        'portuguese': 'pt-PT',
        'russian': 'ru-RU',
        'arabic': 'ar-SA',
        'chinese': 'zh-CN',
        'japanese': 'ja-JP',
        'korean': 'ko-KR',
        'dutch': 'nl-NL',
        'polish': 'pl-PL',
        'turkish': 'tr-TR',
        'greek': 'el-GR'
    };

    // ============================================
    // SWAP LANGUAGES
    // ============================================
    function swapLanguages() {
        const source = document.getElementById('sourceLang');
        const target = document.getElementById('targetLang');
        const textInput = document.getElementById('textInput');
        const translationContent = document.getElementById('translationContent');

        const sourceVal = source.value;
        const targetVal = target.value;
        const originalText = textInput.value;
        const translatedText = currentTranslation;

        if (sourceVal === 'auto') {
            showToast('Cannot swap with "Detect automatically"', 'error');
            return;
        }

        source.value = targetVal || 'italian';
        target.value = sourceVal;

        if (translatedText && originalText) {
            textInput.value = translatedText;
            currentTranslation = originalText;
            currentOriginalText = translatedText;
            currentTargetLang = source.value;
            translationContent.textContent = originalText;
        }
    }

    // ============================================
    // TRANSLATE
    // ============================================
    async function translateText() {
        const text = document.getElementById('textInput').value.trim();
        const targetLang = document.getElementById('targetLang').value;
        const sourceLang = document.getElementById('sourceLang').value;

        if (!text) {
            showToast('Enter a text to translate!', 'error');
            return;
        }
        if (!targetLang) {
            showToast('Select a destination language!', 'error');
            return;
        }
        if (sourceLang !== 'auto' && sourceLang === targetLang) {
            showToast('The source and destination languages are the same!', 'error');
            return;
        }

        const btn = document.getElementById('translateBtn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner" style="width:20px;height:20px;border-width:2px;margin:0;"></span> Translating...';

        document.getElementById('resultWrapper').classList.remove('active');
        document.getElementById('loadingBox').classList.add('active');

        try {
            const formData = new FormData();
            formData.append('translate', '1');
            formData.append('text', text);
            formData.append('target_lang', targetLang);
            formData.append('source_lang', sourceLang);

            const response = await fetch('workmetranslate.php', { method: 'POST', body: formData });
            const data = await response.json();

            document.getElementById('loadingBox').classList.remove('active');

            if (data.success) {
                currentTranslation = data.translation;
                currentTargetLang = data.target_lang;
                currentOriginalText = text;
                document.getElementById('translationContent').textContent = data.translation;
                document.getElementById('resultWrapper').classList.add('active');
                saveToHistory(data.translation, text, sourceLang, targetLang);
                showToast('Translation completed!', 'success');
                document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
            } else {
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            document.getElementById('loadingBox').classList.remove('active');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
    }

    // ============================================
    // COPY
    // ============================================
    function copyTranslation() {
        if (!currentTranslation) {
            showToast('No translation to copy', 'error');
            return;
        }
        navigator.clipboard.writeText(currentTranslation).then(() => {
            showToast('Translation copied!', 'success');
        }).catch(() => {
            showToast('Copy error', 'error');
        });
    }

    // ============================================
    // TEXT-TO-SPEECH
    // ============================================
    function speakTranslation() {
        if (!currentTranslation) {
            showToast('No translation to read', 'error');
            return;
        }
        if (!('speechSynthesis' in window)) {
            showToast('Your browser does not support speech synthesis', 'error');
            return;
        }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentTranslation);
        utterance.lang = langCodeMap[currentTargetLang] || 'en-US';
        utterance.rate = 1;
        utterance.onstart = () => showToast('Playing...', 'info');
        utterance.onend = () => showToast('Playback finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    // ============================================
    // DOWNLOAD
    // ============================================
    function downloadTranslation() {
        if (!currentTranslation) {
            showToast('No translation to download', 'error');
            return;
        }
        const date = new Date().toISOString().slice(0, 10);
        const content = 'TRANSLATION - LUX.Translate\nDate: ' + date + '\nLanguage: ' + currentTargetLang + '\n\n' +
                        '=== ORIGINAL ===\n\n' + currentOriginalText + '\n\n' +
                        '=== TRANSLATION ===\n\n' + currentTranslation;
        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'workmetranslate_' + date + '.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('Translation downloaded!', 'success');
    }

    // ============================================
    // HISTORY
    // ============================================
    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(translation, originalText, sourceLang, targetLang) {
        let history = loadHistory();
        history = history.filter(h => h.translation !== translation);
        history.unshift({
            translation: translation,
            originalText: originalText.substring(0, 300),
            sourceLang: sourceLang,
            targetLang: targetLang,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty">No saved translations</div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString() + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const preview = item.translation.substring(0, 60) + (item.translation.length > 60 ? '...' : '');
            html +=
                '<div class="history-item" onclick="loadFromHistory(' + i + ')">' +
                    '<div class="history-item-info">' +
                        '<div class="history-item-preview">' + escapeHtml(preview) + '</div>' +
                        '<div class="history-item-date">' + item.sourceLang + '<i data-i=arrow-right class=ic></i>' + item.targetLang + ' · ' + timeStr + '</div>' +
                    '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            currentTranslation = history[index].translation;
            currentOriginalText = history[index].originalText;
            currentTargetLang = history[index].targetLang;
            document.getElementById('translationContent').textContent = history[index].translation;
            document.getElementById('resultWrapper').classList.add('active');
            showToast('Translation loaded from history', 'success');
            document.getElementById('resultWrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }

    function clearHistory() {
        if (!confirm('Clear the whole translation history?')) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    // ============================================
    // INIT
    // ============================================
    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
    });
</script>

