$isAdmin = isAdminLoggedIn();

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    $text = trim($_POST['text'] ?? '');

    if ($text === '') {
        jsonResponse(['success' => false, 'error' => t('Empty text.')]);
    }

    $isIT = currentLang() === 'it';
    $translateNameMap = [
        'inglese' => 'English',
        'francese' => 'French',
        'spagnolo' => 'Spanish',
        'tedesco' => 'German',
        'giapponese' => 'Japanese',
        'cinese' => 'Chinese',
        'arabo' => 'Arabic',
        'russo' => 'Russian',
        'portoghese' => 'Portuguese'
    ];

    if ($action === 'summarize') {
        $prompt = $isIT
            ? "Riassumi il seguente testo in modo conciso, mantenendo i punti principali. Testo: '$text'"
            : "Summarize the following text concisely, keeping the main points. Text: '$text'";
        $system = $isIT
            ? 'Sei un esperto di riassunti. Riassumi testi in modo chiaro e conciso.'
            : 'You are a summarization expert. Summarize texts clearly and concisely.';
    } elseif ($action === 'translate') {
        $targetLang = $_POST['target_lang'] ?? 'inglese';
        $targetName = $isIT ? $targetLang : ($translateNameMap[$targetLang] ?? 'English');
        $prompt = $isIT
            ? "Traduci il seguente testo in $targetLang. Testo: '$text'"
            : "Translate the following text into $targetName. Text: '$text'";
        $system = $isIT
            ? 'Sei un traduttore professionista. Traduci testi mantenendo tono e stile.'
            : 'You are a professional translator. Translate texts keeping tone and style.';
    } elseif ($action === 'grammar') {
        $prompt = $isIT
            ? "Correggi la grammatica e l'ortografia del seguente testo, migliorandolo senza cambiarne il significato. Testo: '$text'. Restituisci SOLO il testo corretto, senza spiegazioni."
            : "Correct the grammar and spelling of the following text, improving it without changing its meaning. Text: '$text'. Return ONLY the corrected text, without explanations.";
        $system = $isIT
            ? 'Sei un correttore di bozze professionista. Correggi grammatica, ortografia e punteggiatura mantenendo lo stile originale.'
            : 'You are a professional proofreader. Correct grammar, spelling and punctuation keeping the original style.';
    } elseif ($action === 'keypoints') {
        $prompt = $isIT
            ? "Estrai i punti chiave dal seguente testo e presentali come una lista puntata. Testo: '$text'"
            : "Extract the key points from the following text and present them as a bullet list. Text: '$text'";
        $system = $isIT
            ? 'Sei un esperto di sintesi. Estrai i punti chiave in modo chiaro e organizzato usando punti elenco.'
            : 'You are a summarization expert. Extract key points in a clear and organized way using bullet points.';
    } else {
        jsonResponse(['success' => false, 'error' => t('Invalid action')]);
    }

    $result = askGroq([
        ['role' => 'system', 'content' => $system],
        ['role' => 'user', 'content' => $prompt]
    ], ['temperature' => 0.7, 'max_tokens' => 2000]);

    if (!$result['success']) {
        jsonResponse(['success' => false, 'error' => $result['error']]);
    }

    jsonResponse(['success' => true, 'result' => $result['content']]);
}

