            transition: background 0.15s, border-color 0.15s;
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 10px;
        }
        .history-item:hover {
            background: rgba(255,255,255,0.04);
            border-color: var(--border-hover);
        }
        .history-text {
            flex: 1;
            font-size: 13px;
            color: var(--text-light);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .history-time {
            font-size: 11px;
            color: var(--text-muted);
            white-space: nowrap;
        }
        .history-empty {
            text-align: center;
            color: var(--text-muted);
            font-size: 13px;
            padding: 20px 10px;
        }

        .cta-box {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 24px;
            padding: 40px 32px;
            text-align: center;
            margin-top: 50px;
            max-width: 1100px;
            margin-left: auto;
            margin-right: auto;
            position: relative;
            overflow: hidden;
        }
        .cta-box::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 3px;
            background: var(--gradient-full);
        }
        .cta-box h3 {
            font-family: var(--font-title);
            font-size: 1.5em;
            font-weight: 700;
            margin-bottom: 10px;
            background: var(--gradient-full);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }
        .cta-box p {
            color: var(--text-light);
            font-size: 14.5px;
            margin-bottom: 22px;
            max-width: 600px;
            margin-left: auto;
            margin-right: auto;
        }
        .cta-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

        .info-box {
            background: rgba(212, 170, 87,0.05);
            border-left: 3px solid var(--cyan);
            border-radius: 0 12px 12px 0;
            padding: 12px 16px;
            margin-top: 14px;
        }
        .info-box p {
            color: var(--text-light);
            font-size: 12.5px;
            line-height: 1.6;
            margin: 0;
        }
        .info-box strong { color: var(--cyan); }

        @media (max-width: 1024px) {
            .hero h1 { font-size: 3em; }
            .voice-grid { grid-template-columns: 1fr; max-width: 700px; }
        }
        @media (max-width: 768px) {
            .hero { padding: 130px 0 50px; }
            .hero h1 { font-size: 2.4em; letter-spacing: -1px; }
            .hero p { font-size: 1.05em; }
            .card { padding: 22px; }
            .mic-btn { width: 90px; height: 90px; }
            .mic-btn svg { width: 40px; height: 40px; }
            .mic-wave.w1, .mic-wave.w2, .mic-wave.w3 { width: 90px; height: 90px; }
            .cta-box { padding: 30px 20px; }
            .action-buttons .btn { padding: 9px 12px; font-size: 12px; }
        }
        @media (max-width: 480px) {
            .hero h1 { font-size: 2em; }
            .cta-buttons { flex-direction: column; }
            .cta-buttons .btn,
            .cta-buttons .btn-primary,
            .cta-buttons .btn-secondary { width: 100%; justify-content: center; }
            .transcription-area { font-size: 14px; min-height: 120px; }
            .stats-bar { font-size: 11px; padding: 8px 10px; }
            .stats-bar .stat-mini { font-size: 11px; }
        }
CSS;

lux_header();
