<script>
    const hamburger = document.getElementById('hamburger');
    const mobileMenu = document.getElementById('mobileMenu');
    hamburger.addEventListener('click', function() {
        this.classList.toggle('active');
        mobileMenu.classList.toggle('active');
    });

    const header = document.getElementById('header');
    let ticking = false;
    window.addEventListener('scroll', function() {
        if (!ticking) {
            window.requestAnimationFrame(function() {
                header.classList.toggle('scrolled', window.pageYOffset > 50);
                ticking = false;
            });
            ticking = true;
        }
    }, { passive: true });

    let recognition = null;
    let isRecording = false;
    let finalTranscript = '';

    function toggleRecording() {
        if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
            showToast('Your browser does not support voice transcription. Use Chrome.', 'error');
            return;
        }
        if (isRecording) stopRecording();
        else startRecording();
    }

    function startRecording() {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        recognition = new SpeechRecognition();
        recognition.lang = document.getElementById('langSelect').value;
        recognition.continuous = true;
        recognition.interimResults = true;

        recognition.onstart = function() {
            isRecording = true;
            document.getElementById('micBtn').classList.add('listening');
            document.getElementById('micWrapper').classList.add('listening');
            document.getElementById('transcription').classList.add('recording');
            document.getElementById('liveBadge').classList.add('active');
            document.getElementById('micStatus').textContent = 'Listening... Speak now!';
            document.getElementById('micStatus').className = 'mic-status active';
        };

        recognition.onresult = function(event) {
            let interim = '';
            let final = '';
            for (let i = event.resultIndex; i < event.results.length; i++) {
                if (event.results[i].isFinal) final += event.results[i][0].transcript;
                else interim += event.results[i][0].transcript;
            }
            if (final) {
                finalTranscript += final + ' ';
                document.getElementById('transcription').value = finalTranscript.trim();
                updateStats();
                autoScroll();
            } else if (interim) {
                document.getElementById('transcription').value = finalTranscript.trim() + ' ' + interim;
                updateStats();
                autoScroll();
            }
        };

        recognition.onerror = function(event) {
            if (event.error === 'not-allowed') {
                showToast('Microphone permission denied. Enable it in your settings.', 'error');
            } else if (event.error === 'no-speech') {
                document.getElementById('micStatus').textContent = 'No speech detected. Try again.';
            } else {
                showToast('Error:' + event.error, 'error');
            }
            resetMicUI();
        };

        recognition.onend = function() {
            if (isRecording) return;
            resetMicUI();
            document.getElementById('micStatus').textContent = 'Recording finished';
            document.getElementById('micStatus').className = 'mic-status done';
            if (finalTranscript.trim()) saveToHistory(finalTranscript.trim());
        };

        recognition.start();
    }

    function stopRecording() {
        if (recognition) {
            recognition.stop();
            isRecording = false;
        }
    }

    function resetMicUI() {
        isRecording = false;
        document.getElementById('micBtn').classList.remove('listening');
        document.getElementById('micWrapper').classList.remove('listening');
        document.getElementById('transcription').classList.remove('recording');
        document.getElementById('liveBadge').classList.remove('active');
    }

    function autoScroll() {
        const area = document.getElementById('transcription');
        area.scrollTop = area.scrollHeight;
    }

    function updateStats() {
        const text = document.getElementById('transcription').value.trim();
        const words = text ? text.split(/\s+/).filter(w => w.length > 0).length : 0;
        const chars = text.length;
        const readTime = Math.max(1, Math.ceil(words / 200));
        document.getElementById('wordCount').textContent = words;
        document.getElementById('charCount').textContent = chars;
        document.getElementById('readTime').textContent = words > 0 ? readTime : 0;
    }

    document.getElementById('transcription').addEventListener('input', updateStats);

    function getText() { return document.getElementById('transcription').value.trim(); }

    function clearText() {
        if (!getText()) return;
        if (confirm(<?= json_encode(t('Clear all text?')) ?>)) {
            finalTranscript = '';
            document.getElementById('transcription').value = '';
            document.getElementById('aiResult').classList.remove('show');
            document.getElementById('aiContent').innerHTML = '';
            updateStats();
            showToast('Text cleared', 'success');
        }
    }

    function copyText() {
        const text = getText();
        if (!text) { showToast('No text to copy', 'error'); return; }
        navigator.clipboard.writeText(text).then(() => {
            showToast('Text copied to clipboard!', 'success');
        }).catch(() => {
            const area = document.getElementById('transcription');
            area.select();
            document.execCommand('copy');
            showToast('Text copied!', 'success');
        });
    }

    function downloadText() {
        const text = getText();
        if (!text) { showToast('No text to download', 'error'); return; }
        const blob = new Blob([text], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'transcription_workmevoice.txt';
        a.click();
        URL.revokeObjectURL(url);
        showToast('File downloaded!', 'success');
    }

    function speakText() {
        const text = getText();
        if (!text) { showToast('No text to read', 'error'); return; }
        if (!('speechSynthesis' in window)) {
            showToast('Your browser does not support speech synthesis', 'error');
            return;
        }
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = document.getElementById('langSelect').value;
        utterance.rate = 1;
        utterance.pitch = 1;
        utterance.onstart = () => showToast('Speaking...', 'info');
        utterance.onend = () => showToast('Reading finished', 'success');
        window.speechSynthesis.speak(utterance);
    }

    function showLoadingAI(show) {
        document.getElementById('aiLoading').style.display = show ? 'block' : 'none';
    }

    function showAIResult(content, label) {
        const result = document.getElementById('aiResult');
        document.getElementById('aiContent').textContent = content;
        document.getElementById('aiLabel').textContent = label || 'AI Result';
        result.classList.add('show');
        result.scrollTop = 0;
    }

    const translateNames = {
        inglese: 'English',
        francese: 'French',
        spagnolo: 'Spanish',
        tedesco: 'German',
        giapponese: 'Japanese',
        cinese: 'Chinese',
        arabo: 'Arabic',
        russo: 'Russian',
        portoghese: 'Portuguese'
    };

    async function runAI(action) {
        const text = getText();
        if (!text) { showToast('Insert or record some text first', 'error'); return; }

        const actionMap = {
            'summarize': { btn: 'btnSummarize', label: 'Summary' },
            'grammar': { btn: 'btnGrammar', label: 'Corrected text' },
            'keypoints': { btn: 'btnKeypoints', label: 'Key points' },
            'translate': { btn: 'btnTranslate', label: 'Translation' }
        };

        const config = actionMap[action];
        if (!config) return;

        const btn = document.getElementById(config.btn);
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner"></span> <?= t('Wait') ?>';
        showLoadingAI(true);
        document.getElementById('aiResult').classList.remove('show');

        try {
            const formData = new FormData();
            formData.append('action', action);
            formData.append('text', text);
            if (action === 'translate') {
                formData.append('target_lang', document.getElementById('translateLang').value);
            }

            const response = await fetch('workmevoice.php', { method: 'POST', body: formData });
            const data = await response.json();

            if (data.success) {
                let label = config.label;
                if (action === 'translate') {
                    const langName = translateNames[document.getElementById('translateLang').value] || '';
                    label = langName ? 'Translation into ' + langName : config.label;
                }
                showAIResult(data.result, label);
                showToast(config.label + ' completed!', 'success');
            } else {
                showAIResult('Error:' + data.error, 'Error');
                showToast('Error:' + data.error, 'error');
            }
        } catch (error) {
            showAIResult('Error:' + error.message, 'Error');
            showToast('Connection error', 'error');
        }

        btn.disabled = false;
        btn.innerHTML = originalText;
        showLoadingAI(false);
    }

    const HISTORY_KEY = 'workmevoice_history';
    const MAX_HISTORY = 5;

    function loadHistory() {
        try {
            const raw = localStorage.getItem(HISTORY_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) { return []; }
    }

    function saveHistory(history) {
        try {
            localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
        } catch (e) {}
    }

    function saveToHistory(text) {
        if (!text || text.length < 5) return;
        let history = loadHistory();
        history = history.filter(h => h.text !== text);
        history.unshift({
            text: text,
            date: new Date().toISOString()
        });
        history = history.slice(0, MAX_HISTORY);
        saveHistory(history);
        renderHistory();
    }

    function renderHistory() {
        const history = loadHistory();
        const list = document.getElementById('historyList');
        if (history.length === 0) {
            list.innerHTML = '<div class="history-empty"><?= t('No transcription saved') ?></div>';
            return;
        }
        let html = '';
        history.forEach((item, i) => {
            const preview = item.text.length > 55 ? item.text.substring(0, 55) + '...' : item.text;
            const date = new Date(item.date);
            const timeStr = date.toLocaleDateString([], { day: '2-digit', month: '2-digit' }) + ' ' +
                            date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            html += `
                <div class="history-item" onclick="loadFromHistory(${i})">
                    <div class="history-text">${escapeHtml(preview)}</div>
                    <div class="history-time">${timeStr}</div>
                </div>
            `;
        });
        list.innerHTML = html;
    }

    function loadFromHistory(index) {
        const history = loadHistory();
        if (history[index]) {
            finalTranscript = history[index].text;
            document.getElementById('transcription').value = history[index].text;
            updateStats();
            showToast('Transcription loaded', 'success');
        }
    }

    function clearHistory() {
        if (!confirm(<?= json_encode(t('Clear all history?')) ?>)) return;
        localStorage.removeItem(HISTORY_KEY);
        renderHistory();
        showToast('History cleared', 'success');
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderHistory();
        updateStats();
    });
</script>
<?php lux_footer();
        break;

    default:
        // Strumenti del catalogo senza pagina dedicata: lo spec viene
        // generato da data/projects.json (vedi lux_tool_auto). Se non
        // esiste nemmeno li', si va sul classico 404.
        if (lux_tool($__lux_slug) !== null) {
            lux_render_tool($__lux_slug);
            break;
        }
        // Indirizzo vecchio del catalogo ricostruito? Si risponde con un
        // reindirizzamento alla voce nuova: nessun link muore.
        if (function_exists('lux_catalog_alias')) {
            $__alias = lux_catalog_alias($__lux_slug);
            if ($__alias !== '') {
                header('Location: /' . $__alias . '.php', true, 301);
                exit;
            }
        }
        http_response_code(404);
        $pageTitle       = t('This tool is not available right now.');
        $pageDescription = '';
        lux_header();
        ?>
        <main>
            <section class="hero">
                <div class="container">
                    <h1><?= t('This tool is not available right now.') ?></h1>
                </div>
            </section>
        </main>
        <?php
        lux_footer();
        break;
}
